package main

// This file is the CANDIDATE SLOT for evolved routing algorithms. During
// optimization, the entire file is replaced (via go build -overlay) with a
// generated implementation. The contract is a single constructor:
//
//	newCandidateRouter(view, source, localBalances, spec)
//
// returning a routing.SimRouter. The router sees only the public gossip
// graph, its own channel balances and per-attempt feedback — the same
// information a real Lightning sender has. The in-tree implementation below
// is the seed algorithm: a deliberately simple fee-optimizing Dijkstra with
// failure blacklisting and halving-based MPP splitting.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

// candidateEdge is one directed edge of the public graph: a channel from
// one node to another, with the policy the sending node announced.
type candidateEdge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

// fee returns the fee the sending node charges to forward amt over this
// edge.
func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

// usable reports whether the edge can carry the given amount per its
// announced policy.
func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	// The public capacity is a hard upper bound on what can flow.
	return amt <= e.capacity
}

// candidateRouter is the seed algorithm: cheapest-path routing with a
// failure blacklist and amount halving when no route is found.
type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// incomingEdges maps a node to the directed edges arriving at it,
	// the natural shape for backward Dijkstra.
	incomingEdges map[route.Vertex][]*candidateEdge

	// localBalances is the exact outbound liquidity of our own channels.
	localBalances map[uint64]lnwire.MilliSatoshi

	// failedAmt records, per directed channel, the lowest amount that
	// failed with a liquidity error; routes are built to stay below it.
	failedAmt map[uint64]lnwire.MilliSatoshi

	// shardAmt is the current shard size for MPP splitting.
	shardAmt lnwire.MilliSatoshi

	// partsUsed counts the successful shards so far.
	partsUsed uint32

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route
}

// newCandidateRouter builds the router for one payment. This signature is
// the stable contract between the harness and generated candidates.
func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	router := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		localBalances: localBalances,
		failedAmt:     make(map[uint64]lnwire.MilliSatoshi),
		shardAmt:      spec.Amount,
		pending:       make(map[uint64]*route.Route),
	}

	// Build the adjacency list from gossip. Iterating a node's channels
	// yields, per channel, the policy the OTHER node announced toward us
	// (InPolicy). That is exactly the policy governing the directed edge
	// other -> node, so we record the reversed edge at each visit.
	ctx := context.Background()
	seen := make(map[route.Vertex]bool)
	queue := []route.Vertex{source}
	seen[source] = true

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: pol.FeeBaseMSat,
					feeRatePPM: pol.
						FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				router.incomingEdges[edge.to] = append(
					router.incomingEdges[edge.to], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return router, nil
}

// dijkstraItem is a priority queue entry.
type dijkstraItem struct {
	node route.Vertex
	cost lnwire.MilliSatoshi
	idx  int
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int           { return len(q) }
func (q dijkstraQueue) Less(i, j int) bool { return q[i].cost < q[j].cost }
func (q dijkstraQueue) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *dijkstraQueue) Push(x any) {
	item := x.(*dijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}
func (q *dijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

// findRoute computes the cheapest usable path delivering amt to the target,
// walking backward from the target so fees accumulate correctly.
func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (*route.Route,
	error) {

	// dist[node] = amount that must arrive at node to deliver amt.
	dist := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	dist[r.spec.Target] = amt
	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{node: r.spec.Target, cost: amt})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		node, arriving := item.node, item.cost

		if arriving > dist[node] {
			continue
		}
		if node == r.source {
			break
		}

		// Consider all edges INTO node: for edge u->node, u must
		// send arriving plus u's fee.
		for _, edge := range r.incomingEdges[node] {
			amtOver := arriving

			if !edge.usable(amtOver) {
				continue
			}

			// Skip channels whose liquidity failure bound says
			// this amount cannot pass.
			if bound, ok := r.failedAmt[edge.chanID]; ok &&
				amtOver >= bound {

				continue
			}

			// Our own channels: check exact local balance.
			if edge.from == r.source {
				if r.localBalances[edge.chanID] < amtOver {
					continue
				}
			}

			var sending lnwire.MilliSatoshi
			if edge.from == r.source {
				// We pay no fee to ourselves.
				sending = amtOver
			} else {
				sending = amtOver + edge.fee(amtOver)
			}

			best, ok := dist[edge.from]
			if !ok || sending < best {
				dist[edge.from] = sending
				next[edge.from] = edge
				heap.Push(pq, &dijkstraItem{
					node: edge.from,
					cost: sending,
				})
			}
		}
	}

	if _, ok := dist[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

// buildRoute walks the next-pointers from source to target and constructs a
// route with correctly accumulated fees and cltv deltas.
func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	const finalCltvDelta = 40

	// Collect the path edges source -> target.
	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.to
	}

	// Amounts and expiries per channel, computed backward.
	numHops := len(path)
	amtOver := make([]lnwire.MilliSatoshi, numHops)
	expiryOver := make([]uint32, numHops)

	amtOver[numHops-1] = amt
	expiryOver[numHops-1] = finalCltvDelta

	for i := numHops - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(fwd.timeLockDelta)
	}

	hops := make([]*route.Hop, numHops)
	for i, edge := range path {
		amtToFwd := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < numHops-1 {
			amtToFwd = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     amtToFwd,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

// RequestRoute returns the next route to try: the cheapest path for the
// current shard size, halving the shard when no route exists.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if r.shardAmt > amt {
		r.shardAmt = amt
	}

	for {
		rt, err := r.findRoute(r.shardAmt)
		if err == nil {
			return rt, nil
		}

		// No route at this shard size: split if we're allowed more
		// parts and the shard is still meaningfully large.
		partsLeft := r.spec.MaxParts - inFlightHtlcs
		if partsLeft <= 1 || r.shardAmt < 10_000_000 {
			return nil, err
		}
		r.shardAmt /= 2
	}
}

// ReportAttempt learns from an attempt: liquidity failures set an upper
// bound on the failing channel.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if result.Failure == nil {
		return nil
	}

	// Locate the failing hop and record the amount bound on its
	// outgoing channel.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == result.FailureSource {
			failIdx = i + 1
		}
	}

	// The failing node could not forward over its outgoing channel,
	// which is rt.Hops[failIdx].
	if failIdx >= 0 && failIdx < len(rt.Hops) {
		hop := rt.Hops[failIdx]
		amtOver := rt.TotalAmount
		if failIdx > 0 {
			amtOver = rt.Hops[failIdx-1].AmtToForward
		}

		bound, ok := r.failedAmt[hop.ChannelID]
		if !ok || amtOver < bound {
			r.failedAmt[hop.ChannelID] = amtOver
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta   = uint32(40)
	riskCostMsat     = 250000.0
	minProbability   = 0.003
	maxProbability   = 0.995
	lowerRetryFactor = 0.68
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return true
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[candidateEdgeKey]liquidityBelief
}{
	values: make(map[candidateEdgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]liquidityBelief
	blocked       map[candidateEdgeKey]bool
	reserved      map[candidateEdgeKey]lnwire.MilliSatoshi
	routePenalty  map[candidateEdgeKey]float64

	baseShard           lnwire.MilliSatoshi
	lastRemaining       lnwire.MilliSatoshi
	consecutiveFailures uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeByKey:     make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		beliefs:       make(map[candidateEdgeKey]liquidityBelief),
		blocked:       make(map[candidateEdgeKey]bool),
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		routePenalty:  make(map[candidateEdgeKey]float64),
		lastRemaining: spec.Amount,
	}

	parts := uint32(1)
	switch {
	case spec.Amount > 1_000_000_000:
		parts = 6
	case spec.Amount > 250_000_000:
		parts = 4
	case spec.Amount > 50_000_000:
		parts = 2
	}
	if spec.MaxParts < parts {
		parts = spec.MaxParts
	}
	if parts == 0 {
		parts = 1
	}
	r.baseShard = ceilDiv(spec.Amount, lnwire.MilliSatoshi(parts))

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edgeByKey[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, belief := range sharedBeliefs.values {
		if _, ok := r.edgeByKey[key]; ok {
			r.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}
	return (a + b - 1) / b
}

func clampProbability(p float64) float64 {
	if p < minProbability {
		return minProbability
	}
	if p > maxProbability {
		return maxProbability
	}
	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-x/0.025)
	highMode := 0.48 / (1 + math.Exp(14*(x-0.78)))

	return clampProbability(0.005 + lowMode + highMode)
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		available := r.localBalances[edge.key.chanID]
		if reserved := r.reserved[edge.key]; reserved < available {
			available -= reserved
		} else {
			available = 0
		}
		if amt > available {
			return minProbability
		}
		return maxProbability
	}

	belief := r.beliefs[edge.key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		return minProbability
	}
	if belief.lowerOK != 0 && amt <= belief.lowerOK {
		return maxProbability
	}

	prior := bimodalPrior(amt, edge.capacity)
	if belief.estimate == 0 {
		return prior
	}

	width := math.Max(float64(edge.capacity)*0.08, 1)
	point := 1 / (1 + math.Exp(
		(float64(amt)-float64(belief.estimate))/width,
	))

	return clampProbability(0.55*prior + 0.45*point)
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	arriving lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}

	dist := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		bestScore, ok := dist[item.node]
		if !ok || item.score > bestScore {
			continue
		}
		if item.arriving != required[item.node] {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.blocked[edge.key] {
				continue
			}

			amtOver := item.arriving
			if !edge.usable(amtOver) {
				continue
			}

			reserved := r.reserved[edge.key]
			if reserved >= edge.capacity ||
				amtOver > edge.capacity-reserved {

				continue
			}

			probability := r.probability(edge, amtOver)
			if probability <= minProbability &&
				r.beliefs[edge.key].upperBad != 0 {

				continue
			}

			sending := amtOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				sending += fee
			} else {
				available := r.localBalances[edge.key.chanID]
				if reserved < available {
					available -= reserved
				} else {
					available = 0
				}
				if sending > available {
					continue
				}
			}

			risk := -math.Log(probability) * riskCostMsat
			score := item.score + float64(fee) + risk +
				r.routePenalty[edge.key] + 250

			oldScore, exists := dist[edge.key.from]
			if exists && score >= oldScore {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:     edge.key.from,
				score:    score,
				arriving: sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to

		if len(path) > len(r.edgeByKey) {
			return nil, errors.New("route contains a cycle")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta
		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}
	key := candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
	_, ok := r.edgeByKey[key]
	return key, ok
}

func routeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) reserve(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}
		r.reserved[key] += routeAmount(rt, i)
	}
}

func (r *candidateRouter) release(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}

		amt := routeAmount(rt, i)
		if amt >= r.reserved[key] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}

	if amt < r.lastRemaining {
		r.consecutiveFailures = 0
	}
	r.lastRemaining = amt

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	if partsLeft == 0 {
		return nil, errors.New("maximum parts in flight")
	}

	shard := r.baseShard
	if shard <= 0 || shard > amt {
		shard = amt
	}

	minNeeded := ceilDiv(amt, lnwire.MilliSatoshi(partsLeft))
	if shard < minNeeded {
		shard = minNeeded
	}
	if shard > amt {
		shard = amt
	}

	minShard := lnwire.MilliSatoshi(10_000)
	if amt < minShard {
		minShard = amt
	}

	var lastErr error
	for shard >= minShard {
		rt, err := r.findRoute(shard)
		if err == nil {
			r.reserve(rt)
			return rt, nil
		}
		lastErr = err

		nextShard := lnwire.MilliSatoshi(
			float64(shard) * lowerRetryFactor,
		)
		if nextShard >= shard {
			nextShard = shard - 1
		}
		if nextShard < minNeeded {
			break
		}
		shard = nextShard
	}

	if shard != minNeeded {
		rt, err := r.findRoute(minNeeded)
		if err == nil {
			r.reserve(rt)
			return rt, nil
		}
		lastErr = err
	}

	if lastErr == nil {
		lastErr = errors.New("no route found")
	}
	return nil, lastErr
}

type codedFailure interface {
	Code() lnwire.FailCode
}

func (r *candidateRouter) saveBelief(key candidateEdgeKey,
	belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	estimate := amt
	remaining := edge.capacity - amt
	if remaining > 0 {
		estimate += remaining * 3 / 4
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}

	estimate := amt * 35 / 100
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}
	if belief.lowerOK > belief.estimate {
		belief.estimate = belief.lowerOK
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.release(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if ok {
				r.recordSuccess(key, routeAmount(rt, i))
				r.routePenalty[key] *= 0.25
			}
		}
		r.consecutiveFailures = 0
		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if ok {
				r.routePenalty[key] += riskCostMsat / 2
			}
		}
		r.consecutiveFailures++
		return nil
	}

	for i := 0; i < failIndex; i++ {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.recordSuccess(key, routeAmount(rt, i))
		}
	}

	key, ok := r.routeEdge(rt, failIndex)
	if !ok {
		return nil
	}

	code := lnwire.FailCode(0)
	if failure, ok := result.Failure.(codedFailure); ok {
		code = failure.Code()
	}

	switch code {
	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.blocked[key] = true

	default:
		r.recordFailure(key, routeAmount(rt, failIndex))
		r.routePenalty[key] += riskCostMsat
	}

	r.consecutiveFailures++
	if r.consecutiveFailures >= 2 {
		delivered := deliveredAmount(rt)
		retry := lnwire.MilliSatoshi(
			float64(delivered) * lowerRetryFactor,
		)
		if retry > 0 && retry < r.baseShard {
			r.baseShard = retry
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	riskCostMsat     = 250000.0
	minProbability   = 0.003
	maxProbability   = 0.995
	lowerRetryFactor = 0.70
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[candidateEdgeKey]liquidityBelief
}{
	values: make(map[candidateEdgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	localSpent    map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]liquidityBelief
	blocked       map[candidateEdgeKey]bool
	reserved      map[candidateEdgeKey]lnwire.MilliSatoshi
	routePenalty  map[candidateEdgeKey]float64

	baseShard           lnwire.MilliSatoshi
	lastRemaining       lnwire.MilliSatoshi
	consecutiveFailures uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeByKey:     make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		localSpent:    make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[candidateEdgeKey]liquidityBelief),
		blocked:       make(map[candidateEdgeKey]bool),
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		routePenalty:  make(map[candidateEdgeKey]float64),
		lastRemaining: spec.Amount,
	}

	parts := uint32(1)
	switch {
	case spec.Amount > 1_000_000_000:
		parts = 6
	case spec.Amount > 250_000_000:
		parts = 4
	case spec.Amount > 50_000_000:
		parts = 2
	}
	if spec.MaxParts != 0 && parts > spec.MaxParts {
		parts = spec.MaxParts
	}
	if parts == 0 {
		parts = 1
	}
	r.baseShard = ceilDiv(
		spec.Amount, lnwire.MilliSatoshi(parts),
	)

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edgeByKey[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, belief := range sharedBeliefs.values {
		if _, ok := r.edgeByKey[key]; ok {
			r.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}
	return (a + b - 1) / b
}

func clampAmount(amt, capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if amt < 0 {
		return 0
	}
	if amt > capacity {
		return capacity
	}
	return amt
}

func clampProbability(p float64) float64 {
	if p < minProbability {
		return minProbability
	}
	if p > maxProbability {
		return maxProbability
	}
	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-x/0.025)
	highMode := 0.48 / (1 + math.Exp(14*(x-0.78)))

	return clampProbability(0.005 + lowMode + highMode)
}

func (r *candidateRouter) localAvailable(
	edge *candidateEdge) lnwire.MilliSatoshi {

	available := r.localBalances[edge.key.chanID]

	spent := r.localSpent[edge.key.chanID]
	if spent >= available {
		return 0
	}
	available -= spent

	reserved := r.reserved[edge.key]
	if reserved >= available {
		return 0
	}

	return available - reserved
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if amt > r.localAvailable(edge) {
			return minProbability
		}
		return maxProbability
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK != 0 && amt <= belief.lowerOK {
		return maxProbability
	}

	prior := bimodalPrior(amt, edge.capacity)
	if belief.upperBad != 0 && amt >= belief.upperBad {
		return minProbability
	}
	if belief.estimate == 0 {
		return prior
	}

	width := math.Max(float64(edge.capacity)*0.07, 1)
	point := 1 / (1 + math.Exp(
		(float64(amt)-float64(belief.estimate))/width,
	))

	return clampProbability(0.50*prior + 0.50*point)
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	arriving lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}

	dist := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)

		bestScore, ok := dist[item.node]
		if !ok || item.score > bestScore {
			continue
		}
		if required[item.node] != item.arriving {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.blocked[edge.key] {
				continue
			}

			amtOver := item.arriving
			if !edge.usable(amtOver) {
				continue
			}

			reserved := r.reserved[edge.key]
			if reserved >= edge.capacity ||
				amtOver > edge.capacity-reserved {

				continue
			}

			sending := amtOver
			fee := lnwire.MilliSatoshi(0)

			if edge.key.from == r.source {
				if sending > r.localAvailable(edge) {
					continue
				}
			} else {
				fee = edge.fee(amtOver)
				if fee < 0 ||
					amtOver > lnwire.MilliSatoshi(
						math.MaxInt64,
					)-fee {

					continue
				}
				sending += fee
			}

			probability := r.probability(edge, amtOver)
			risk := -math.Log(probability) * riskCostMsat
			score := item.score + float64(fee) + risk +
				r.routePenalty[edge.key] + 250

			oldScore, exists := dist[edge.key.from]
			if exists && score >= oldScore {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge

			heap.Push(pq, &dijkstraItem{
				node:     edge.key.from,
				score:    score,
				arriving: sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to

		if len(path) > len(r.edgeByKey) {
			return nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		fee := forwardingEdge.fee(amtOver[i+1])
		if fee < 0 ||
			amtOver[i+1] > lnwire.MilliSatoshi(
				math.MaxInt64,
			)-fee {

			return nil, errors.New("route amount overflow")
		}

		amtOver[i] = amtOver[i+1] + fee
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta

		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	key := candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
	_, ok := r.edgeByKey[key]

	return key, ok
}

func routeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) routeProbability(rt *route.Route) float64 {
	probability := 1.0

	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			return minProbability
		}

		edge := r.edgeByKey[key]
		probability *= r.probability(
			edge, routeAmount(rt, i),
		)
	}

	if probability < math.SmallestNonzeroFloat64 {
		return math.SmallestNonzeroFloat64
	}
	return probability
}

func (r *candidateRouter) reserve(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.reserved[key] += routeAmount(rt, i)
		}
	}
}

func (r *candidateRouter) release(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}

		amt := routeAmount(rt, i)
		if amt >= r.reserved[key] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
	}
}

func appendCandidate(values []lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return values
	}

	seen[value] = true
	return append(values, value)
}

func (r *candidateRouter) shardCandidates(amt,
	minimum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 12)

	for _, numerator := range []int64{
		100, 84, 70, 58, 48, 40, 33, 27,
	} {
		value := lnwire.MilliSatoshi(
			int64(amt) * numerator / 100,
		)
		values = appendCandidate(
			values, seen, value, minimum, amt,
		)
	}

	values = appendCandidate(
		values, seen, r.baseShard, minimum, amt,
	)
	values = appendCandidate(
		values, seen, minimum, minimum, amt,
	)

	return values
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 ||
		inFlightHtlcs >= r.spec.MaxParts {

		return nil, errors.New("maximum parts in flight")
	}

	if amt < r.lastRemaining {
		r.consecutiveFailures = 0
	}
	r.lastRemaining = amt

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	minimum := ceilDiv(
		amt, lnwire.MilliSatoshi(partsLeft),
	)

	var (
		bestRoute   *route.Route
		bestUtility = math.Inf(-1)
		lastErr     error
	)

	for _, shard := range r.shardCandidates(amt, minimum) {
		rt, err := r.findRoute(shard)
		if err != nil {
			lastErr = err
			continue
		}

		probability := r.routeProbability(rt)
		sizeRatio := float64(shard) / float64(minimum)
		fee := rt.TotalAmount - deliveredAmount(rt)

		utility := math.Log(probability) +
			1.35*math.Log(sizeRatio) -
			float64(fee)/2_000_000

		if shard == amt {
			utility += 0.08
		}
		if utility > bestUtility {
			bestUtility = utility
			bestRoute = rt
		}
	}

	if bestRoute == nil {
		if lastErr == nil {
			lastErr = errors.New("no route found")
		}
		return nil, lastErr
	}

	r.reserve(bestRoute)
	return bestRoute, nil
}

type codedFailure interface {
	Code() lnwire.FailCode
}

func (r *candidateRouter) saveBelief(key candidateEdgeKey,
	belief liquidityBelief) {

	edge := r.edgeByKey[key]
	if edge == nil {
		return
	}

	belief.lowerOK = clampAmount(
		belief.lowerOK, edge.capacity,
	)
	belief.upperBad = clampAmount(
		belief.upperBad, edge.capacity,
	)
	belief.estimate = clampAmount(
		belief.estimate, edge.capacity,
	)

	if belief.upperBad != 0 &&
		belief.lowerOK >= belief.upperBad {

		belief.upperBad = 0
	}

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordProbeSuccess(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	estimate := amt
	if edge.capacity > amt {
		estimate += (edge.capacity - amt) * 3 / 4
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}

	estimate := amt * 30 / 100
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}
	if belief.lowerOK > belief.estimate {
		belief.estimate = belief.lowerOK
	}

	r.saveBelief(key, belief)
}

func subtractBound(value,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value == 0 || value <= amt {
		return 0
	}
	return value - amt
}

func addBound(value, amt,
	capacity lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value > capacity-amt {
		return capacity
	}
	return value + amt
}

func (r *candidateRouter) recordSettlement(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil {
		return
	}

	if key.from == r.source {
		r.localSpent[key.chanID] += amt
		return
	}

	belief := r.beliefs[key]
	preEstimate := belief.estimate

	inferred := amt
	if edge.capacity > amt {
		inferred += (edge.capacity - amt) * 3 / 4
	}
	if inferred > preEstimate {
		preEstimate = inferred
	}

	belief.lowerOK = subtractBound(belief.lowerOK, amt)
	belief.upperBad = subtractBound(belief.upperBad, amt)
	belief.estimate = subtractBound(preEstimate, amt)
	r.saveBelief(key, belief)

	reverseKey := candidateEdgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edgeByKey[reverseKey]
	if reverseEdge == nil || reverseKey.from == r.source {
		return
	}

	reverse := r.beliefs[reverseKey]
	reverse.lowerOK = addBound(
		reverse.lowerOK, amt, reverseEdge.capacity,
	)
	if reverse.lowerOK < amt {
		reverse.lowerOK = amt
	}
	reverse.estimate = addBound(
		reverse.estimate, amt, reverseEdge.capacity,
	)
	if reverse.estimate < reverse.lowerOK {
		reverse.estimate = reverse.lowerOK
	}
	if reverse.upperBad != 0 {
		reverse.upperBad = addBound(
			reverse.upperBad, amt, reverseEdge.capacity,
		)
	}

	r.saveBelief(reverseKey, reverse)
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.release(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if !ok {
				continue
			}

			r.recordSettlement(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.20
		}

		r.consecutiveFailures = 0
		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if ok {
				r.routePenalty[key] += riskCostMsat / 2
			}
		}

		r.consecutiveFailures++
		return nil
	}

	for i := 0; i < failIndex; i++ {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.recordProbeSuccess(
				key, routeAmount(rt, i),
			)
			r.routePenalty[key] *= 0.75
		}
	}

	key, ok := r.routeEdge(rt, failIndex)
	if !ok {
		return nil
	}

	code := lnwire.FailCode(0)
	if failure, ok := result.Failure.(codedFailure); ok {
		code = failure.Code()
	}

	switch code {
	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.blocked[key] = true

	default:
		r.recordFailure(
			key, routeAmount(rt, failIndex),
		)
		r.routePenalty[key] += riskCostMsat
	}

	r.consecutiveFailures++

	delivered := deliveredAmount(rt)
	retry := lnwire.MilliSatoshi(
		float64(delivered) * lowerRetryFactor,
	)
	if retry > 0 && retry < r.baseShard {
		r.baseShard = retry
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta  = uint32(40)
	riskCostMsat    = 260000.0
	minProbability  = 0.003
	maxProbability  = 0.995
	diversityCost   = 6000000.0
	minimumShard    = lnwire.MilliSatoshi(10_000)
	maxPlanCorridors = 8
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return true
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[candidateEdgeKey]liquidityBelief
}{
	values: make(map[candidateEdgeKey]liquidityBelief),
}

type pathCandidate struct {
	edges []*candidateEdge
	limit lnwire.MilliSatoshi
	score float64
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	localSpent    map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]liquidityBelief
	blocked       map[candidateEdgeKey]bool
	reserved      map[candidateEdgeKey]lnwire.MilliSatoshi
	routePenalty  map[candidateEdgeKey]float64

	lastRemaining       lnwire.MilliSatoshi
	consecutiveFailures uint32
	retryHint           lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeByKey:      make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		localSpent:     make(map[uint64]lnwire.MilliSatoshi),
		beliefs:        make(map[candidateEdgeKey]liquidityBelief),
		blocked:        make(map[candidateEdgeKey]bool),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		routePenalty:   make(map[candidateEdgeKey]float64),
		lastRemaining:  spec.Amount,
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edgeByKey[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, belief := range sharedBeliefs.values {
		if _, ok := r.edgeByKey[key]; ok {
			r.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}
	return (a + b - 1) / b
}

func clampProbability(p float64) float64 {
	if p < minProbability {
		return minProbability
	}
	if p > maxProbability {
		return maxProbability
	}
	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-x/0.025)
	highMode := 0.48 / (1 + math.Exp(14*(x-0.78)))

	return clampProbability(0.005 + lowMode + highMode)
}

func subtractFloor(value, amount lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if amount >= value {
		return 0
	}
	return value - amount
}

func (r *candidateRouter) localAvailable(
	key candidateEdgeKey) lnwire.MilliSatoshi {

	available := r.localBalances[key.chanID]
	available = subtractFloor(available, r.localSpent[key.chanID])
	available = subtractFloor(available, r.reserved[key])

	return available
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if amt > r.localAvailable(edge.key) {
			return minProbability
		}
		return maxProbability
	}

	belief := r.beliefs[edge.key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		return minProbability
	}
	if belief.lowerOK != 0 && amt <= belief.lowerOK {
		return maxProbability
	}

	prior := bimodalPrior(amt, edge.capacity)
	if belief.estimate == 0 {
		return prior
	}

	width := math.Max(float64(edge.capacity)*0.07, 1)
	point := 1 / (1 + math.Exp(
		(float64(amt)-float64(belief.estimate))/width,
	))

	return clampProbability(0.52*prior + 0.48*point)
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	arriving lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findPath(amt lnwire.MilliSatoshi,
	diversity map[candidateEdgeKey]int) ([]*candidateEdge, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	dist := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)

		bestScore, ok := dist[item.node]
		if !ok || item.score > bestScore {
			continue
		}
		if item.arriving != required[item.node] {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.blocked[edge.key] {
				continue
			}

			amtOver := item.arriving
			if !edge.usable(amtOver) {
				continue
			}

			reserved := r.reserved[edge.key]
			if reserved >= edge.capacity ||
				amtOver > edge.capacity-reserved {

				continue
			}

			if edge.key.from == r.source &&
				amtOver > r.localAvailable(edge.key) {

				continue
			}

			belief := r.beliefs[edge.key]
			if belief.upperBad != 0 && amtOver >= belief.upperBad {
				continue
			}

			probability := r.probability(edge, amtOver)
			sending := amtOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				sending += fee
			}

			risk := -math.Log(probability) * riskCostMsat
			capacityBonus := 0.0
			if edge.capacity > 0 {
				spare := float64(edge.capacity-amtOver) /
					float64(edge.capacity)
				capacityBonus = math.Min(spare, 1) * 18000
			}

			score := item.score + float64(fee) + risk +
				r.routePenalty[edge.key] + 250 -
				capacityBonus

			if count := diversity[edge.key]; count != 0 {
				score += float64(count) * diversityCost
			}

			oldScore, exists := dist[edge.key.from]
			if exists && score >= oldScore {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:     edge.key.from,
				score:    score,
				arriving: sending,
			})
		}
	}

	score, ok := dist[r.source]
	if !ok {
		return nil, 0, errors.New("no route found")
	}

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, 0, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edgeByKey) {
			return nil, 0, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, 0, errors.New("empty route")
	}

	return path, score, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		if !edge.usable(amtOver[i]) {
			return nil, errors.New("path cannot carry amount")
		}

		forward := amt
		expiry := finalCltvDelta
		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) routeFeasible(rt *route.Route) bool {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok || r.blocked[key] {
			return false
		}

		edge := r.edgeByKey[key]
		amt := routeAmount(rt, i)
		if edge == nil || !edge.usable(amt) {
			return false
		}

		if edge.key.from == r.source {
			if amt > r.localAvailable(key) {
				return false
			}
			continue
		}

		reserved := r.reserved[key]
		if reserved >= edge.capacity ||
			amt > edge.capacity-reserved {

			return false
		}

		belief := r.beliefs[key]
		if belief.upperBad != 0 && amt >= belief.upperBad {
			return false
		}
	}

	return true
}

func (r *candidateRouter) pathLimit(path []*candidateEdge,
	maxAmount lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if maxAmount <= 0 {
		return 0
	}

	low := lnwire.MilliSatoshi(0)
	high := maxAmount

	for low < high {
		mid := low + (high-low+1)/2
		rt, err := r.buildRoute(mid, path)
		if err == nil && r.routeFeasible(rt) {
			low = mid
		} else {
			high = mid - 1
		}
	}

	return low
}

func pathID(path []*candidateEdge) string {
	id := ""
	for _, edge := range path {
		id += fmt.Sprintf(
			"%d:%x:%x/", edge.key.chanID, edge.key.from,
			edge.key.to,
		)
	}
	return id
}

func (r *candidateRouter) probeAmount(remaining lnwire.MilliSatoshi,
	parts uint32) lnwire.MilliSatoshi {

	if parts == 0 {
		parts = 1
	}

	probe := ceilDiv(
		remaining, lnwire.MilliSatoshi(parts)*6,
	)
	if probe < 100_000 {
		probe = 100_000
	}
	if probe > 50_000_000 {
		probe = 50_000_000
	}
	if probe > remaining {
		probe = remaining
	}

	return probe
}

func (r *candidateRouter) planPaths(remaining lnwire.MilliSatoshi,
	parts uint32) []pathCandidate {

	count := int(parts)
	if count < 1 {
		count = 1
	}
	if count > maxPlanCorridors {
		count = maxPlanCorridors
	}

	probes := []lnwire.MilliSatoshi{
		r.probeAmount(remaining, parts),
	}
	if probes[0] > minimumShard {
		probes = append(probes, minimumShard)
	}

	diversity := make(map[candidateEdgeKey]int)
	seen := make(map[string]bool)
	plans := make([]pathCandidate, 0, count)

	for len(plans) < count {
		var (
			path  []*candidateEdge
			score float64
			err   error
		)

		for _, probe := range probes {
			path, score, err = r.findPath(probe, diversity)
			if err == nil {
				break
			}
		}
		if err != nil {
			break
		}

		id := pathID(path)
		for _, edge := range path {
			diversity[edge.key]++
		}

		if seen[id] {
			if len(plans) != 0 {
				break
			}
			continue
		}
		seen[id] = true

		limit := r.pathLimit(path, remaining)
		if limit < minimumShard && limit < remaining {
			continue
		}

		plans = append(plans, pathCandidate{
			edges: path,
			limit: limit,
			score: score,
		})
	}

	sort.SliceStable(plans, func(i, j int) bool {
		pi := r.pathReliability(plans[i])
		pj := r.pathReliability(plans[j])
		if math.Abs(pi-pj) > 0.03 {
			return pi > pj
		}
		if plans[i].limit != plans[j].limit {
			return plans[i].limit > plans[j].limit
		}
		return plans[i].score < plans[j].score
	})

	return plans
}

func (r *candidateRouter) pathReliability(
	plan pathCandidate) float64 {

	if plan.limit <= 0 {
		return 0
	}

	probe := plan.limit
	if probe > 50_000_000 {
		probe = 50_000_000
	}

	probability := 1.0
	for _, edge := range plan.edges {
		probability *= r.probability(edge, probe)
	}

	return probability
}

func plannedAllocation(remaining lnwire.MilliSatoshi,
	plans []pathCandidate) lnwire.MilliSatoshi {

	if len(plans) == 0 {
		return 0
	}
	if len(plans) == 1 {
		if plans[0].limit < remaining {
			return plans[0].limit
		}
		return remaining
	}

	total := lnwire.MilliSatoshi(0)
	other := lnwire.MilliSatoshi(0)
	for i, plan := range plans {
		total += plan.limit
		if i != 0 {
			other += plan.limit
		}
	}

	if total <= 0 {
		return 0
	}

	allocation := lnwire.MilliSatoshi(
		float64(remaining) *
			float64(plans[0].limit) / float64(total),
	)

	requiredNow := subtractFloor(remaining, other)
	if allocation < requiredNow {
		allocation = requiredNow
	}

	fairMinimum := ceilDiv(
		remaining, lnwire.MilliSatoshi(len(plans)),
	)
	if allocation < fairMinimum &&
		plans[0].limit >= fairMinimum {

		allocation = fairMinimum
	}

	if allocation > plans[0].limit {
		allocation = plans[0].limit
	}
	if allocation > remaining {
		allocation = remaining
	}
	if allocation < minimumShard && remaining >= minimumShard {
		if plans[0].limit >= minimumShard {
			allocation = minimumShard
		}
	}

	return allocation
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	key := candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
	_, ok := r.edgeByKey[key]
	return key, ok
}

func routeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) reserve(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}
		r.reserved[key] += routeAmount(rt, i)
	}
}

func (r *candidateRouter) release(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}

		amt := routeAmount(rt, i)
		if amt >= r.reserved[key] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum parts in flight")
	}

	if amt < r.lastRemaining {
		r.consecutiveFailures = 0
		r.retryHint = 0
	}
	r.lastRemaining = amt

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	if partsLeft == 0 {
		return nil, errors.New("maximum parts in flight")
	}

	plans := r.planPaths(amt, partsLeft)
	if len(plans) != 0 {
		shard := plannedAllocation(amt, plans)

		if r.retryHint != 0 && shard > r.retryHint {
			shard = r.retryHint
		}
		if shard > plans[0].limit {
			shard = plans[0].limit
		}
		if shard > amt {
			shard = amt
		}

		for shard > 0 {
			rt, err := r.buildRoute(shard, plans[0].edges)
			if err == nil && r.routeFeasible(rt) {
				r.reserve(rt)
				return rt, nil
			}

			next := shard * 2 / 3
			if next >= shard {
				next = shard - 1
			}
			if next < minimumShard && amt >= minimumShard {
				break
			}
			shard = next
		}
	}

	candidates := []lnwire.MilliSatoshi{
		amt,
		ceilDiv(amt, lnwire.MilliSatoshi(partsLeft)),
		amt * 2 / 3,
		amt / 2,
		amt / 3,
		minimumShard,
	}
	if r.retryHint != 0 {
		candidates = append(
			[]lnwire.MilliSatoshi{r.retryHint}, candidates...,
		)
	}

	tried := make(map[lnwire.MilliSatoshi]bool)
	var lastErr error
	for _, shard := range candidates {
		if shard <= 0 || shard > amt || tried[shard] {
			continue
		}
		tried[shard] = true

		path, _, err := r.findPath(
			shard, make(map[candidateEdgeKey]int),
		)
		if err != nil {
			lastErr = err
			continue
		}

		rt, err := r.buildRoute(shard, path)
		if err != nil || !r.routeFeasible(rt) {
			if err != nil {
				lastErr = err
			}
			continue
		}

		r.reserve(rt)
		return rt, nil
	}

	if lastErr == nil {
		lastErr = errors.New("no route found")
	}
	return nil, lastErr
}

type codedFailure interface {
	Code() lnwire.FailCode
}

func (r *candidateRouter) saveBelief(key candidateEdgeKey,
	belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordPass(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	inferred := amt
	remaining := edge.capacity - amt
	if remaining > 0 {
		inferred += remaining * 3 / 4
	}
	if inferred > belief.estimate {
		belief.estimate = inferred
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordSettlement(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil {
		return
	}

	if key.from == r.source {
		r.localSpent[key.chanID] += amt
		return
	}

	belief := r.beliefs[key]

	preEstimate := belief.estimate
	if preEstimate < amt {
		preEstimate = amt
	}
	inferred := amt
	if edge.capacity > amt {
		inferred += (edge.capacity - amt) * 3 / 4
	}
	if inferred > preEstimate {
		preEstimate = inferred
	}

	belief.estimate = subtractFloor(preEstimate, amt)
	belief.lowerOK = subtractFloor(belief.lowerOK, amt)
	if belief.upperBad != 0 {
		belief.upperBad = subtractFloor(belief.upperBad, amt)
		if belief.upperBad == 0 {
			belief.upperBad = 1
		}
	}

	likelyRemaining := lnwire.MilliSatoshi(0)
	if edge.capacity > amt {
		likelyRemaining = (edge.capacity - amt) * 2 / 3
	}
	if belief.estimate < likelyRemaining {
		belief.estimate = likelyRemaining
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}

	estimate := amt * 30 / 100
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}
	if belief.lowerOK > belief.estimate {
		belief.estimate = belief.lowerOK
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes != source {
			continue
		}

		outgoing := i + 1
		if outgoing < len(rt.Hops) {
			return outgoing
		}
		return -1
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.release(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if !ok {
				continue
			}

			r.recordSettlement(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.20
		}

		r.consecutiveFailures = 0
		r.retryHint = 0
		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if ok {
				r.routePenalty[key] += riskCostMsat * 0.45
			}
		}

		r.consecutiveFailures++
		delivered := deliveredAmount(rt)
		if delivered > minimumShard {
			r.retryHint = delivered * 2 / 3
		}
		return nil
	}

	for i := 0; i < failIndex; i++ {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.recordPass(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.75
		}
	}

	key, ok := r.routeEdge(rt, failIndex)
	if !ok {
		return nil
	}

	code := lnwire.FailCode(0)
	if failure, ok := result.Failure.(codedFailure); ok {
		code = failure.Code()
	}

	switch code {
	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.blocked[key] = true

	case lnwire.CodeTemporaryChannelFailure:
		r.recordFailure(key, routeAmount(rt, failIndex))
		r.routePenalty[key] += riskCostMsat * 1.4

	default:
		r.routePenalty[key] += riskCostMsat * 0.75
	}

	r.consecutiveFailures++

	delivered := deliveredAmount(rt)
	if delivered > minimumShard {
		factor := lnwire.MilliSatoshi(2)
		divisor := lnwire.MilliSatoshi(3)
		if r.consecutiveFailures >= 3 {
			factor = 1
			divisor = 2
		}

		retry := delivered * factor / divisor
		if retry < minimumShard {
			retry = minimumShard
		}
		r.retryHint = retry
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta   = uint32(40)
	riskCostMsat     = 250000.0
	minProbability   = 0.003
	maxProbability   = 0.995
	lowerRetryFactor = 0.68
	minShardMsat     = lnwire.MilliSatoshi(10_000)
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[candidateEdgeKey]liquidityBelief
}{
	values: make(map[candidateEdgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	localSpent    map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]liquidityBelief
	blocked       map[candidateEdgeKey]bool
	reserved      map[candidateEdgeKey]lnwire.MilliSatoshi
	routePenalty  map[candidateEdgeKey]float64

	lastRemaining       lnwire.MilliSatoshi
	retryCap            lnwire.MilliSatoshi
	consecutiveFailures uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeByKey:      make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  make(map[uint64]lnwire.MilliSatoshi),
		localSpent:     make(map[uint64]lnwire.MilliSatoshi),
		beliefs:        make(map[candidateEdgeKey]liquidityBelief),
		blocked:        make(map[candidateEdgeKey]bool),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		routePenalty:   make(map[candidateEdgeKey]float64),
		lastRemaining:  spec.Amount,
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edgeByKey[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, belief := range sharedBeliefs.values {
		if _, ok := r.edgeByKey[key]; ok {
			r.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}
	return (a + b - 1) / b
}

func minMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a < b {
		return a
	}
	return b
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}
	return b
}

func clampProbability(p float64) float64 {
	if p < minProbability {
		return minProbability
	}
	if p > maxProbability {
		return maxProbability
	}
	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-x/0.025)
	highMode := 0.48 / (1 + math.Exp(14*(x-0.78)))

	return clampProbability(0.005 + lowMode + highMode)
}

func (r *candidateRouter) localAvailable(
	edge *candidateEdge) lnwire.MilliSatoshi {

	available := r.localBalances[edge.key.chanID]
	spent := r.localSpent[edge.key.chanID]
	if spent >= available {
		return 0
	}
	available -= spent

	reserved := r.reserved[edge.key]
	if reserved >= available {
		return 0
	}
	return available - reserved
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if amt > r.localAvailable(edge) {
			return minProbability
		}
		return maxProbability
	}

	belief := r.beliefs[edge.key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		return minProbability
	}
	if belief.lowerOK != 0 && amt <= belief.lowerOK {
		return maxProbability
	}

	prior := bimodalPrior(amt, edge.capacity)
	if belief.estimate == 0 {
		return prior
	}

	width := math.Max(float64(edge.capacity)*0.07, 1)
	point := 1 / (1 + math.Exp(
		(float64(amt)-float64(belief.estimate))/width,
	))

	weight := 0.48
	if belief.lowerOK != 0 || belief.upperBad != 0 {
		weight = 0.64
	}

	return clampProbability((1-weight)*prior + weight*point)
}

func (r *candidateRouter) edgeSafeLimit(
	edge *candidateEdge) lnwire.MilliSatoshi {

	if r.blocked[edge.key] {
		return 0
	}

	limit := edge.capacity
	if edge.maxHTLC != 0 && edge.maxHTLC < limit {
		limit = edge.maxHTLC
	}

	if edge.key.from == r.source {
		limit = minMSat(limit, r.localAvailable(edge))
		if limit < edge.minHTLC {
			return 0
		}
		return limit
	}

	reserved := r.reserved[edge.key]
	if reserved >= limit {
		return 0
	}
	limit -= reserved

	belief := r.beliefs[edge.key]
	safe := limit * 72 / 100

	if belief.estimate != 0 {
		safe = belief.estimate * 90 / 100
	}
	if belief.upperBad != 0 {
		retry := belief.upperBad * 68 / 100
		safe = maxMSat(safe, retry)
	}
	if belief.lowerOK != 0 {
		safe = maxMSat(safe, belief.lowerOK)
	}

	if belief.upperBad != 0 && safe >= belief.upperBad {
		safe = belief.upperBad - 1
	}
	if safe > limit {
		safe = limit
	}
	if safe < edge.minHTLC {
		return 0
	}

	return safe
}

type widestItem struct {
	node  route.Vertex
	width lnwire.MilliSatoshi
}

type widestQueue []*widestItem

func (q widestQueue) Len() int {
	return len(q)
}

func (q widestQueue) Less(i, j int) bool {
	return q[i].width > q[j].width
}

func (q widestQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *widestQueue) Push(value any) {
	*q = append(*q, value.(*widestItem))
}

func (q *widestQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) widestAmount(
	maximum lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if maximum <= 0 {
		return 0
	}

	width := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: maximum,
	}
	pq := &widestQueue{}
	heap.Push(pq, &widestItem{
		node:  r.spec.Target,
		width: maximum,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*widestItem)
		if item.width != width[item.node] {
			continue
		}
		if item.node == r.source {
			return item.width
		}

		for _, edge := range r.incomingEdges[item.node] {
			limit := r.edgeSafeLimit(edge)
			if limit == 0 {
				continue
			}

			candidate := minMSat(item.width, limit)
			if candidate <= width[edge.key.from] {
				continue
			}

			width[edge.key.from] = candidate
			heap.Push(pq, &widestItem{
				node:  edge.key.from,
				width: candidate,
			})
		}
	}

	return 0
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	arriving lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}

	dist := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		bestScore, ok := dist[item.node]
		if !ok || item.score > bestScore {
			continue
		}
		if item.arriving != required[item.node] {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.blocked[edge.key] {
				continue
			}

			amtOver := item.arriving
			if !edge.usable(amtOver) {
				continue
			}

			reserved := r.reserved[edge.key]
			if edge.key.from != r.source {
				if reserved >= edge.capacity ||
					amtOver > edge.capacity-reserved {

					continue
				}
			}

			probability := r.probability(edge, amtOver)
			belief := r.beliefs[edge.key]
			if belief.upperBad != 0 &&
				amtOver >= belief.upperBad {

				continue
			}

			sending := amtOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				sending += fee
			} else if sending > r.localAvailable(edge) {
				continue
			}

			risk := -math.Log(probability) * riskCostMsat
			score := item.score + float64(fee) + risk +
				r.routePenalty[edge.key] + 200

			oldScore, exists := dist[edge.key.from]
			if exists && score >= oldScore {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:     edge.key.from,
				score:    score,
				arriving: sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edgeByKey) {
			return nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta
		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	key := candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
	_, ok := r.edgeByKey[key]
	return key, ok
}

func routeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) reserve(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.reserved[key] += routeAmount(rt, i)
		}
	}
}

func (r *candidateRouter) release(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}

		amt := routeAmount(rt, i)
		if amt >= r.reserved[key] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum parts in flight")
	}

	if amt < r.lastRemaining {
		r.consecutiveFailures = 0
		r.retryCap = 0
	}
	r.lastRemaining = amt

	for key, penalty := range r.routePenalty {
		penalty *= 0.90
		if penalty < 1 {
			delete(r.routePenalty, key)
		} else {
			r.routePenalty[key] = penalty
		}
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	if partsLeft == 0 {
		partsLeft = 1
	}

	desired := ceilDiv(
		amt, lnwire.MilliSatoshi(partsLeft),
	)
	if partsLeft == 1 {
		desired = amt
	}

	widest := r.widestAmount(amt)
	shard := desired
	if widest != 0 {
		safe := widest * 92 / 100
		if safe < minShardMsat {
			safe = minMSat(widest, minShardMsat)
		}
		shard = minMSat(shard, safe)
	}

	if r.retryCap != 0 && shard > r.retryCap {
		shard = r.retryCap
	}
	if shard > amt {
		shard = amt
	}

	minShard := minShardMsat
	if amt < minShard {
		minShard = amt
	}
	if shard < minShard {
		shard = minShard
	}

	var lastErr error
	tried := make(map[lnwire.MilliSatoshi]bool)

	for shard >= minShard {
		if !tried[shard] {
			tried[shard] = true
			rt, err := r.findRoute(shard)
			if err == nil {
				r.reserve(rt)
				return rt, nil
			}
			lastErr = err
		}

		if shard == minShard {
			break
		}

		nextShard := lnwire.MilliSatoshi(
			float64(shard) * lowerRetryFactor,
		)
		if nextShard >= shard {
			nextShard = shard - 1
		}
		if nextShard < minShard {
			nextShard = minShard
		}
		shard = nextShard
	}

	if !tried[amt] && partsLeft == 1 {
		rt, err := r.findRoute(amt)
		if err == nil {
			r.reserve(rt)
			return rt, nil
		}
		lastErr = err
	}

	if lastErr == nil {
		lastErr = errors.New("no route found")
	}
	return nil, lastErr
}

type codedFailure interface {
	Code() lnwire.FailCode
}

func (r *candidateRouter) saveBelief(key candidateEdgeKey,
	belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	estimate := amt
	if edge.capacity > amt {
		estimate += (edge.capacity - amt) * 3 / 4
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordSettlement(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil {
		return
	}

	if key.from == r.source {
		r.localSpent[key.chanID] += amt
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}

	lower := maxMSat(belief.lowerOK, amt)
	if lower > amt {
		belief.lowerOK = lower - amt
	} else {
		belief.lowerOK = 0
	}

	inferred := amt
	if edge.capacity > amt {
		inferred += (edge.capacity - amt) * 3 / 4
	}
	estimate := maxMSat(belief.estimate, inferred)
	if estimate > amt {
		belief.estimate = estimate - amt
	} else {
		belief.estimate = 0
	}

	if belief.upperBad != 0 {
		if belief.upperBad > amt {
			belief.upperBad -= amt
		} else {
			belief.upperBad = 0
		}
	}

	if belief.estimate > edge.capacity {
		belief.estimate = edge.capacity
	}
	if belief.lowerOK > belief.estimate {
		belief.estimate = belief.lowerOK
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}

	estimate := amt * 35 / 100
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}
	if belief.lowerOK > belief.estimate {
		belief.estimate = belief.lowerOK
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.release(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if !ok {
				continue
			}

			r.recordSettlement(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.20
		}
		r.consecutiveFailures = 0
		r.retryCap = 0
		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if ok {
				r.routePenalty[key] += riskCostMsat / 3
			}
		}

		r.consecutiveFailures++
		delivered := deliveredAmount(rt)
		retry := delivered * 3 / 4
		if retry > 0 &&
			(r.retryCap == 0 || retry < r.retryCap) {

			r.retryCap = retry
		}
		return nil
	}

	for i := 0; i < failIndex; i++ {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.recordSuccess(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.50
		}
	}

	key, ok := r.routeEdge(rt, failIndex)
	if !ok {
		return nil
	}

	code := lnwire.FailCode(0)
	if failure, ok := result.Failure.(codedFailure); ok {
		code = failure.Code()
	}

	switch code {
	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.blocked[key] = true

	default:
		failedAmt := routeAmount(rt, failIndex)
		r.recordFailure(key, failedAmt)
		r.routePenalty[key] += riskCostMsat

		delivered := deliveredAmount(rt)
		retry := lnwire.MilliSatoshi(
			float64(delivered) * lowerRetryFactor,
		)
		if retry > 0 &&
			(r.retryCap == 0 || retry < r.retryCap) {

			r.retryCap = retry
		}
	}

	r.consecutiveFailures++
	if r.consecutiveFailures >= 3 {
		for key, penalty := range r.routePenalty {
			r.routePenalty[key] = penalty * 0.72
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta   = uint32(40)
	riskCostMsat     = 320000.0
	minProbability   = 0.003
	maxProbability   = 0.995
	diversityCost    = 2200000.0
	minimumShard     = lnwire.MilliSatoshi(10_000)
	maxPlanCorridors = 8
	maxPathHops       = 24
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return true
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[candidateEdgeKey]liquidityBelief
}{
	values: make(map[candidateEdgeKey]liquidityBelief),
}

type pathCandidate struct {
	edges       []*candidateEdge
	hardLimit   lnwire.MilliSatoshi
	likelyLimit lnwire.MilliSatoshi
	score       float64
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	localSpent    map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]liquidityBelief
	blocked       map[candidateEdgeKey]bool
	reserved      map[candidateEdgeKey]lnwire.MilliSatoshi
	routePenalty  map[candidateEdgeKey]float64

	lastRemaining       lnwire.MilliSatoshi
	consecutiveFailures uint32
	retryHint           lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeByKey:      make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		localSpent:     make(map[uint64]lnwire.MilliSatoshi),
		beliefs:        make(map[candidateEdgeKey]liquidityBelief),
		blocked:        make(map[candidateEdgeKey]bool),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		routePenalty:   make(map[candidateEdgeKey]float64),
		lastRemaining:  spec.Amount,
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edgeByKey[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, belief := range sharedBeliefs.values {
		if _, ok := r.edgeByKey[key]; ok {
			r.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}

	return (a + b - 1) / b
}

func subtractFloor(value, amount lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if amount >= value {
		return 0
	}

	return value - amount
}

func clampProbability(p float64) float64 {
	if p < minProbability {
		return minProbability
	}
	if p > maxProbability {
		return maxProbability
	}

	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.51 * math.Exp(-x/0.026)
	highMode := 0.475 / (1 + math.Exp(15*(x-0.79)))

	return clampProbability(0.005 + lowMode + highMode)
}

func (r *candidateRouter) localAvailable(
	key candidateEdgeKey) lnwire.MilliSatoshi {

	available := r.localBalances[key.chanID]
	available = subtractFloor(available, r.localSpent[key.chanID])
	available = subtractFloor(available, r.reserved[key])

	return available
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if amt > r.localAvailable(edge.key) {
			return minProbability
		}

		return maxProbability
	}

	belief := r.beliefs[edge.key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		return minProbability
	}
	if belief.lowerOK != 0 && amt <= belief.lowerOK {
		return maxProbability
	}

	prior := bimodalPrior(amt, edge.capacity)
	if belief.estimate == 0 {
		return prior
	}

	width := math.Max(float64(edge.capacity)*0.055, 1)
	point := 1 / (1 + math.Exp(
		(float64(amt)-float64(belief.estimate))/width,
	))

	return clampProbability(0.43*prior + 0.57*point)
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	arriving lnwire.MilliSatoshi
	hops     int
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	if q[i].score == q[j].score {
		return q[i].hops < q[j].hops
	}

	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]

	return item
}

func (r *candidateRouter) edgeCost(edge *candidateEdge,
	amt lnwire.MilliSatoshi, fee lnwire.MilliSatoshi,
	diversity map[candidateEdgeKey]int) float64 {

	p := r.probability(edge, amt)
	cost := float64(fee) - math.Log(p)*riskCostMsat + 500

	if edge.capacity > 0 {
		load := float64(amt) / float64(edge.capacity)
		cost += 22000 * load * load
	}

	cost += r.routePenalty[edge.key]
	if count := diversity[edge.key]; count != 0 {
		cost += float64(count) * diversityCost
	}

	if cost < 1 {
		return 1
	}

	return cost
}

func (r *candidateRouter) findPath(amt lnwire.MilliSatoshi,
	diversity map[candidateEdgeKey]int) ([]*candidateEdge, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	dist := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	hopCount := map[route.Vertex]int{
		r.spec.Target: 0,
	}
	next := make(map[route.Vertex]*candidateEdge)
	settled := make(map[route.Vertex]bool)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)

		bestScore, ok := dist[item.node]
		if !ok || item.score != bestScore {
			continue
		}
		if item.arriving != required[item.node] {
			continue
		}
		if settled[item.node] {
			continue
		}
		settled[item.node] = true

		if item.node == r.source {
			break
		}
		if item.hops >= maxPathHops {
			continue
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.blocked[edge.key] {
				continue
			}
			if edge.key.from == r.spec.Target {
				continue
			}
			if settled[edge.key.from] {
				continue
			}

			amtOver := item.arriving
			if !edge.usable(amtOver) {
				continue
			}

			reserved := r.reserved[edge.key]
			if reserved >= edge.capacity ||
				amtOver > edge.capacity-reserved {

				continue
			}

			if edge.key.from == r.source &&
				amtOver > r.localAvailable(edge.key) {

				continue
			}

			belief := r.beliefs[edge.key]
			if belief.upperBad != 0 && amtOver >= belief.upperBad {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			sending := amtOver
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				sending += fee
			}

			score := item.score + r.edgeCost(
				edge, amtOver, fee, diversity,
			)
			oldScore, exists := dist[edge.key.from]
			if exists && score >= oldScore {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			hopCount[edge.key.from] = item.hops + 1
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:     edge.key.from,
				score:    score,
				arriving: sending,
				hops:     item.hops + 1,
			})
		}
	}

	score, ok := dist[r.source]
	if !ok {
		return nil, 0, errors.New("no route found")
	}

	visited := make(map[route.Vertex]bool)
	path := make([]*candidateEdge, 0, hopCount[r.source])
	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, 0, errors.New("route contains a cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, 0, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > maxPathHops {
			return nil, 0, errors.New("route exceeds hop limit")
		}
	}

	if len(path) == 0 {
		return nil, 0, errors.New("empty route")
	}

	return path, score, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		if !edge.usable(amtOver[i]) {
			return nil, errors.New("path cannot carry amount")
		}

		forward := amt
		expiry := finalCltvDelta
		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	key := candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
	_, ok := r.edgeByKey[key]

	return key, ok
}

func routeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}

	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}

	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) routeFeasible(rt *route.Route) bool {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok || r.blocked[key] {
			return false
		}

		edge := r.edgeByKey[key]
		amt := routeAmount(rt, i)
		if edge == nil || !edge.usable(amt) {
			return false
		}

		if edge.key.from == r.source {
			if amt > r.localAvailable(key) {
				return false
			}
			continue
		}

		reserved := r.reserved[key]
		if reserved >= edge.capacity ||
			amt > edge.capacity-reserved {

			return false
		}

		belief := r.beliefs[key]
		if belief.upperBad != 0 && amt >= belief.upperBad {
			return false
		}
	}

	return true
}

func (r *candidateRouter) credibleAmount(
	edge *candidateEdge) lnwire.MilliSatoshi {

	if edge.key.from == r.source {
		return r.localAvailable(edge.key)
	}

	limit := edge.capacity
	if edge.maxHTLC != 0 && edge.maxHTLC < limit {
		limit = edge.maxHTLC
	}

	reserved := r.reserved[edge.key]
	limit = subtractFloor(limit, reserved)

	belief := r.beliefs[edge.key]
	if belief.upperBad != 0 && belief.upperBad-1 < limit {
		limit = belief.upperBad - 1
	}

	if belief.estimate != 0 {
		likely := belief.estimate * 92 / 100
		if belief.lowerOK > likely {
			likely = belief.lowerOK
		}
		if likely < limit {
			limit = likely
		}

		return limit
	}

	priorLimit := edge.capacity * 72 / 100
	priorLimit = subtractFloor(priorLimit, reserved)
	if priorLimit < limit {
		limit = priorLimit
	}

	return limit
}

func (r *candidateRouter) routeLikely(rt *route.Route) bool {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			return false
		}

		edge := r.edgeByKey[key]
		if edge == nil || routeAmount(rt, i) > r.credibleAmount(edge) {
			return false
		}
	}

	return true
}

func (r *candidateRouter) amountLimit(path []*candidateEdge,
	maxAmount lnwire.MilliSatoshi, likely bool) lnwire.MilliSatoshi {

	if maxAmount <= 0 {
		return 0
	}

	low := lnwire.MilliSatoshi(0)
	high := maxAmount

	for low < high {
		mid := low + (high-low+1)/2
		rt, err := r.buildRoute(mid, path)
		ok := err == nil && r.routeFeasible(rt)
		if ok && likely {
			ok = r.routeLikely(rt)
		}

		if ok {
			low = mid
		} else {
			high = mid - 1
		}
	}

	return low
}

func pathID(path []*candidateEdge) string {
	id := ""
	for _, edge := range path {
		id += fmt.Sprintf(
			"%d:%x:%x/", edge.key.chanID, edge.key.from,
			edge.key.to,
		)
	}

	return id
}

func (r *candidateRouter) pathProbability(path []*candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	rt, err := r.buildRoute(amt, path)
	if err != nil {
		return 0
	}

	probability := 1.0
	for i, edge := range path {
		probability *= r.probability(edge, routeAmount(rt, i))
	}

	return probability
}

func (r *candidateRouter) discoveryProbe(remaining
	lnwire.MilliSatoshi, parts uint32) lnwire.MilliSatoshi {

	if parts == 0 {
		parts = 1
	}

	probe := ceilDiv(
		remaining, lnwire.MilliSatoshi(parts)*8,
	)
	if probe < 100_000 {
		probe = 100_000
	}
	if probe > 25_000_000 {
		probe = 25_000_000
	}
	if probe > remaining {
		probe = remaining
	}

	return probe
}

func (r *candidateRouter) planPaths(remaining lnwire.MilliSatoshi,
	parts uint32) []pathCandidate {

	count := int(parts)
	if count < 1 {
		count = 1
	}
	if count > maxPlanCorridors {
		count = maxPlanCorridors
	}

	probes := []lnwire.MilliSatoshi{
		r.discoveryProbe(remaining, parts),
		100_000,
		minimumShard,
	}

	diversity := make(map[candidateEdgeKey]int)
	seen := make(map[string]bool)
	plans := make([]pathCandidate, 0, count)
	maxSearches := count * 5

	for search := 0; search < maxSearches &&
		len(plans) < count; search++ {

		var (
			path  []*candidateEdge
			score float64
			err   error
		)

		for _, probe := range probes {
			if probe <= 0 || probe > remaining {
				continue
			}

			path, score, err = r.findPath(probe, diversity)
			if err == nil {
				break
			}
		}
		if err != nil {
			break
		}

		id := pathID(path)
		for _, edge := range path {
			diversity[edge.key]++
		}
		if seen[id] {
			continue
		}
		seen[id] = true

		hardLimit := r.amountLimit(path, remaining, false)
		if hardLimit <= 0 {
			continue
		}

		likelyLimit := r.amountLimit(path, hardLimit, true)
		if likelyLimit < minimumShard {
			likelyLimit = hardLimit
			if likelyLimit > 1_000_000 {
				likelyLimit = 1_000_000
			}
		}

		plans = append(plans, pathCandidate{
			edges:       path,
			hardLimit:   hardLimit,
			likelyLimit: likelyLimit,
			score:       score,
		})
	}

	sort.SliceStable(plans, func(i, j int) bool {
		pi := r.pathProbability(
			plans[i].edges, plans[i].likelyLimit,
		)
		pj := r.pathProbability(
			plans[j].edges, plans[j].likelyLimit,
		)
		if math.Abs(pi-pj) > 0.04 {
			return pi > pj
		}
		if plans[i].likelyLimit != plans[j].likelyLimit {
			return plans[i].likelyLimit > plans[j].likelyLimit
		}

		return plans[i].score < plans[j].score
	})

	return plans
}

func sumPlanLimits(plans []pathCandidate, start, count int,
	likely bool) lnwire.MilliSatoshi {

	total := lnwire.MilliSatoshi(0)
	end := start + count
	if end > len(plans) {
		end = len(plans)
	}

	for i := start; i < end; i++ {
		if likely {
			total += plans[i].likelyLimit
		} else {
			total += plans[i].hardLimit
		}
	}

	return total
}

func plannedAllocation(remaining lnwire.MilliSatoshi,
	parts uint32, plans []pathCandidate) lnwire.MilliSatoshi {

	if len(plans) == 0 || parts == 0 {
		return 0
	}

	usable := len(plans)
	if usable > int(parts) {
		usable = int(parts)
	}

	firstLimit := plans[0].likelyLimit
	totalLikely := sumPlanLimits(plans, 0, usable, true)
	if totalLikely < remaining {
		firstLimit = plans[0].hardLimit
	}

	otherCapacity := sumPlanLimits(plans, 1, usable-1, true)
	if totalLikely < remaining {
		otherCapacity = sumPlanLimits(
			plans, 1, usable-1, false,
		)
	}

	requiredNow := subtractFloor(remaining, otherCapacity)
	allocation := requiredNow

	totalWeight := totalLikely
	if totalWeight < remaining {
		totalWeight = sumPlanLimits(plans, 0, usable, false)
	}
	if totalWeight > 0 {
		weighted := lnwire.MilliSatoshi(
			float64(remaining) *
				float64(firstLimit) / float64(totalWeight),
		)
		if weighted > allocation {
			allocation = weighted
		}
	}

	if parts == 1 {
		allocation = remaining
	}
	if allocation > firstLimit {
		allocation = firstLimit
	}
	if allocation > plans[0].hardLimit {
		allocation = plans[0].hardLimit
	}
	if allocation > remaining {
		allocation = remaining
	}
	if allocation < minimumShard && remaining >= minimumShard &&
		plans[0].hardLimit >= minimumShard {

		allocation = minimumShard
	}

	return allocation
}

func (r *candidateRouter) reserve(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.reserved[key] += routeAmount(rt, i)
		}
	}
}

func (r *candidateRouter) release(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}

		amt := routeAmount(rt, i)
		if amt >= r.reserved[key] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
	}
}

func (r *candidateRouter) tryRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	rt, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, err
	}
	if !r.routeFeasible(rt) {
		return nil, errors.New("route is not feasible")
	}

	r.reserve(rt)

	return rt, nil
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 {
		return nil, errors.New("payment permits no parts")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum parts in flight")
	}

	if amt < r.lastRemaining {
		r.consecutiveFailures = 0
		r.retryHint = 0
	}
	r.lastRemaining = amt

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	plans := r.planPaths(amt, partsLeft)

	if len(plans) != 0 {
		shard := plannedAllocation(amt, partsLeft, plans)
		if r.retryHint != 0 && shard > r.retryHint {
			shard = r.retryHint
		}
		if partsLeft == 1 {
			shard = amt
		}

		for _, plan := range plans {
			tryAmt := shard
			if tryAmt > plan.hardLimit {
				tryAmt = plan.hardLimit
			}
			if tryAmt <= 0 {
				continue
			}

			rt, err := r.tryRoute(tryAmt, plan.edges)
			if err == nil {
				return rt, nil
			}
		}
	}

	candidates := []lnwire.MilliSatoshi{
		amt,
		ceilDiv(amt, lnwire.MilliSatoshi(partsLeft)),
		amt * 3 / 4,
		amt * 2 / 3,
		amt / 2,
		amt / 3,
		amt / 4,
		minimumShard,
	}
	if r.retryHint != 0 {
		candidates = append(
			[]lnwire.MilliSatoshi{r.retryHint}, candidates...,
		)
	}

	tried := make(map[lnwire.MilliSatoshi]bool)
	var lastErr error
	for _, shard := range candidates {
		if shard <= 0 || shard > amt || tried[shard] {
			continue
		}
		if partsLeft == 1 && shard != amt {
			continue
		}
		tried[shard] = true

		path, _, err := r.findPath(
			shard, make(map[candidateEdgeKey]int),
		)
		if err != nil {
			lastErr = err
			continue
		}

		rt, err := r.tryRoute(shard, path)
		if err == nil {
			return rt, nil
		}
		lastErr = err
	}

	if lastErr == nil {
		lastErr = errors.New("no route found")
	}

	return nil, lastErr
}

type codedFailure interface {
	Code() lnwire.FailCode
}

func (r *candidateRouter) saveBelief(key candidateEdgeKey,
	belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordPass(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	inferred := amt
	if edge.capacity > amt {
		inferred += (edge.capacity - amt) * 4 / 5
	}
	if inferred > belief.estimate {
		belief.estimate = inferred
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordSettlement(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil {
		return
	}

	if key.from == r.source {
		r.localSpent[key.chanID] += amt
		return
	}

	belief := r.beliefs[key]
	preEstimate := belief.estimate
	if preEstimate < amt {
		preEstimate = amt
	}

	inferred := amt
	if edge.capacity > amt {
		inferred += (edge.capacity - amt) * 4 / 5
	}
	if inferred > preEstimate {
		preEstimate = inferred
	}

	belief.estimate = subtractFloor(preEstimate, amt)
	belief.lowerOK = subtractFloor(belief.lowerOK, amt)
	if belief.upperBad != 0 {
		belief.upperBad = subtractFloor(belief.upperBad, amt)
		if belief.upperBad == 0 {
			belief.upperBad = 1
		}
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}

	estimate := amt / 4
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}
	if belief.lowerOK > belief.estimate {
		belief.estimate = belief.lowerOK
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes != source {
			continue
		}

		outgoing := i + 1
		if outgoing < len(rt.Hops) {
			return outgoing
		}

		return -1
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.release(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if !ok {
				continue
			}

			r.recordSettlement(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.15
		}

		r.consecutiveFailures = 0
		r.retryHint = 0

		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if ok {
				r.routePenalty[key] += riskCostMsat * 0.65
			}
		}

		r.consecutiveFailures++
		delivered := deliveredAmount(rt)
		if delivered > minimumShard {
			r.retryHint = delivered / 2
			if r.retryHint < minimumShard {
				r.retryHint = minimumShard
			}
		}

		return nil
	}

	for i := 0; i < failIndex; i++ {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.recordPass(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.65
		}
	}

	key, ok := r.routeEdge(rt, failIndex)
	if !ok {
		return nil
	}

	code := lnwire.FailCode(0)
	if failure, ok := result.Failure.(codedFailure); ok {
		code = failure.Code()
	}

	switch code {
	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.blocked[key] = true

	case lnwire.CodeTemporaryChannelFailure:
		r.recordFailure(key, routeAmount(rt, failIndex))
		r.routePenalty[key] += riskCostMsat * 1.8

	default:
		r.routePenalty[key] += riskCostMsat
	}

	r.consecutiveFailures++

	delivered := deliveredAmount(rt)
	if delivered > minimumShard {
		retry := delivered * 3 / 5
		if r.consecutiveFailures >= 2 {
			retry = delivered / 2
		}
		if r.consecutiveFailures >= 4 {
			retry = delivered / 3
		}
		if retry < minimumShard {
			retry = minimumShard
		}
		r.retryHint = retry
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
	samples  uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved     map[edgeKey]lnwire.MilliSatoshi
	edgeFailures map[edgeKey]uint32
	broken       map[edgeKey]bool

	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:  make(map[edgeKey]uint32),
		broken:        make(map[edgeKey]bool),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)

	// The first term models the small depleted-side tail. The second
	// models the large liquid-side mode and its cliff near capacity.
	lowMode := 0.50 * math.Exp(-18*x)
	highMode := 0.495 / (1 + math.Exp(22*(x-0.88)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}
		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := float64(edge.capacity) * 0.10
	if scale < 1 {
		scale = 1
	}
	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))

	confidence := math.Min(0.78, 0.22*float64(belief.samples))
	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]
	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	utility     float64
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{r.spec.Target: 0}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: deliver,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, ok := score[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.broken[edge.key] || !edge.usable(item.amt) {
				continue
			}

			totalLiquidity := item.amt + r.reserved[edge.key]
			if totalLiquidity > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				totalLiquidity >
					r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(edge, item.amt)
			edgeFee := edge.fee(item.amt)
			sending := item.amt + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = item.amt
			}

			// Reliability dominates. A million-msat risk scale still
			// permits fees to break ties between similarly reliable paths.
			step := -math.Log(probability) +
				float64(edgeFee)/2_000_000 +
				0.015 +
				0.32*float64(r.edgeFailures[edge.key])
			candidate := item.score + step

			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(r.edges[key], amounts[i])
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}
		path = append(path, edge)
		node = edge.key.to

		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addCandidate(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	if minimum < 1_000 {
		minimum = 1_000
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 14)

	addCandidate(&values, seen, amt, minimum, amt)
	addCandidate(&values, seen, amt*3/4, minimum, amt)
	addCandidate(&values, seen, amt*2/3, minimum, amt)
	addCandidate(&values, seen, amt/2, minimum, amt)
	addCandidate(&values, seen, amt/3, minimum, amt)
	addCandidate(&values, seen, minimum*2, minimum, amt)
	addCandidate(&values, seen, minimum*3/2, minimum, amt)
	addCandidate(&values, seen, minimum, minimum, amt)

	if r.lastFailedAmt > 0 {
		addCandidate(
			&values, seen, r.lastFailedAmt*3/4,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*2/3,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt/2,
			minimum, amt,
		)
	}

	// Failure bounds are useful shard breakpoints. Only retain the largest
	// few after deduplication to keep route search bounded.
	var bounds []lnwire.MilliSatoshi
	for key, belief := range r.beliefs {
		if r.broken[key] || belief.upperFail <= 1 {
			continue
		}
		bound := belief.upperFail * 3 / 4
		if bound >= minimum && bound <= amt {
			bounds = append(bounds, bound)
		}
	}
	sort.Slice(bounds, func(i, j int) bool {
		return bounds[i] > bounds[j]
	})
	if len(bounds) > 4 {
		bounds = bounds[:4]
	}
	for _, bound := range bounds {
		addCandidate(&values, seen, bound, minimum, amt)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})
	return values
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= 48 {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	var best *routeChoice

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		// This approximates joint route-set planning. It prices route
		// failure, fees, and the number of shards needed to cover the
		// remaining amount while reservations steer concurrent shards onto
		// distinct corridors.
		shardRatio := float64(amt) / float64(shard)
		choice.utility = -math.Log(choice.probability) +
			0.30*math.Log(shardRatio) +
			float64(choice.fee)/2_000_000

		if best == nil || choice.utility < best.utility {
			best = choice
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	for i, key := range best.keys {
		r.reserved[key] += best.amounts[i]
	}
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief
	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = amt / 3
	} else {
		belief.estimate = (2*belief.estimate + amt/3) / 3
	}
	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}
	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount lnwire.MilliSatoshi,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}
	return value - amount
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	preEstimate := belief.estimate
	if preEstimate < amt {
		preEstimate = amt
	}
	optimistic := edge.capacity * 9 / 10
	if preEstimate < optimistic {
		preEstimate = (preEstimate + optimistic) / 2
	}

	// Settlement moves liquidity away from this direction, so shift all
	// evidence by the amount that just traversed the channel.
	belief.estimate = subtractFloor(preEstimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}
	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}
	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}
	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}
	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}
	return b
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	keys, amounts := routeEdgeData(rt)
	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])
			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}
			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}
		r.lastFailedAmt = 0
		return nil
	}

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIndex = i + 1
				break
			}
		}
	}

	for _, key := range keys {
		r.edgeFailures[key]++
	}

	if failIndex < 0 || failIndex >= len(keys) {
		r.lastFailedAmt = rt.Hops[len(rt.Hops)-1].AmtToForward
		return nil
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]
	r.lastFailedAmt = rt.Hops[len(rt.Hops)-1].AmtToForward
	r.edgeFailures[key] += 2

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		// A route using an advertised policy that is rejected for fees or
		// timelocks should not be retried during this payment.
		r.broken[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta    = 40
	maxRouteAttempts  = 48
	maxAmountChoices  = 24
	maxForecastSearch = 160
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved     map[edgeKey]lnwire.MilliSatoshi
	edgeFailures map[edgeKey]uint32
	broken       map[edgeKey]bool

	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:  make(map[edgeKey]uint32),
		broken:        make(map[edgeKey]bool),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, exists := r.edges[key]; exists {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, exists := sharedBeliefs.values[key]
		if !exists {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-18*x)
	highMode := 0.495 / (1 + math.Exp(22*(x-0.88)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}

		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := float64(edge.capacity) * 0.10
	if scale < 1 {
		scale = 1
	}

	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))
	confidence := math.Min(0.80, 0.20*float64(belief.samples))

	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: deliver,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, exists := score[item.node]
		if !exists || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		needed := required[item.node]
		for _, edge := range r.incomingEdges[item.node] {
			if r.broken[edge.key] || !edge.usable(needed) {
				continue
			}

			total := needed + r.reserved[edge.key]
			if total > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				total > r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(edge, needed)
			edgeFee := edge.fee(needed)
			sending := needed + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = needed
			}

			failurePenalty := 0.20 *
				float64(r.edgeFailures[edge.key])
			step := -math.Log(probability) +
				float64(edgeFee)/2_000_000 +
				0.012 + failurePenalty
			candidate := item.score + step

			old, found := score[edge.key.from]
			if found && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
			})
		}
	}

	if _, exists := next[r.source]; !exists {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(r.edges[key], amounts[i])
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, exists := next[node]
		if !exists {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func ceilDivide(value lnwire.MilliSatoshi,
	divisor uint32) lnwire.MilliSatoshi {

	d := lnwire.MilliSatoshi(divisor)
	return (value + d - 1) / d
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := ceilDivide(amt, partsLeft)
	if minimum < 1_000 {
		minimum = 1_000
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, maxAmountChoices)

	// Enumerate balanced and deliberately unequal allocations for every
	// feasible part count. Reservations make subsequent calls choose other
	// corridors, so these values act as the first shard of a joint plan.
	for parts := uint32(1); parts <= partsLeft; parts++ {
		base := ceilDivide(amt, parts)
		addAmount(&values, seen, base, minimum, amt)

		if parts > 1 {
			addAmount(
				&values, seen, base*9/8, minimum, amt,
			)
			addAmount(
				&values, seen, base*5/4, minimum, amt,
			)
			addAmount(
				&values, seen, base*3/2, minimum, amt,
			)
		}
	}

	if r.lastFailedAmt > 0 {
		addAmount(
			&values, seen, r.lastFailedAmt*4/5,
			minimum, amt,
		)
		addAmount(
			&values, seen, r.lastFailedAmt*2/3,
			minimum, amt,
		)
		addAmount(
			&values, seen, r.lastFailedAmt/2,
			minimum, amt,
		)
	}

	var bounds []lnwire.MilliSatoshi
	for key, belief := range r.beliefs {
		if r.broken[key] {
			continue
		}

		if belief.lowerOK >= minimum && belief.lowerOK <= amt {
			bounds = append(bounds, belief.lowerOK)
		}
		if belief.upperFail > 1 {
			value := belief.upperFail * 4 / 5
			if value >= minimum && value <= amt {
				bounds = append(bounds, value)
			}
		}
		if belief.estimate >= minimum && belief.estimate <= amt {
			bounds = append(bounds, belief.estimate*9/10)
		}
	}

	sort.Slice(bounds, func(i, j int) bool {
		return bounds[i] > bounds[j]
	})
	if len(bounds) > 8 {
		bounds = bounds[:8]
	}
	for _, value := range bounds {
		addAmount(&values, seen, value, minimum, amt)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})
	if len(values) > maxAmountChoices {
		values = values[:maxAmountChoices]
	}

	return values
}

func reserveChoice(reserved map[edgeKey]lnwire.MilliSatoshi,
	choice *routeChoice) {

	for i, key := range choice.keys {
		reserved[key] += choice.amounts[i]
	}
}

func restoreReservations(destination,
	snapshot map[edgeKey]lnwire.MilliSatoshi) {

	for key := range destination {
		delete(destination, key)
	}
	for key, value := range snapshot {
		destination[key] = value
	}
}

func copyReservations(
	source map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	result := make(map[edgeKey]lnwire.MilliSatoshi, len(source))
	for key, value := range source {
		result[key] = value
	}

	return result
}

func choiceCost(choice *routeChoice) float64 {
	p := choice.probability
	if p < 0.005 {
		p = 0.005
	}

	// The logarithmic term maximizes the chance that every planned shard
	// settles. The reciprocal term mildly prices the expected retry count.
	return -math.Log(p) + 0.035/p +
		float64(choice.fee)/2_000_000
}

func (r *candidateRouter) forecastPlan(total lnwire.MilliSatoshi,
	partsLeft uint32, first *routeChoice) (float64, bool) {

	if first.deliver <= 0 || first.deliver > total {
		return 0, false
	}

	snapshot := copyReservations(r.reserved)
	defer restoreReservations(r.reserved, snapshot)

	reserveChoice(r.reserved, first)
	remaining := total - first.deliver
	score := choiceCost(first) + 0.025
	used := uint32(1)

	for remaining > 0 {
		if used >= partsLeft {
			return 0, false
		}

		slots := partsLeft - used
		shard := ceilDivide(remaining, slots)
		choice, err := r.findRoute(shard)
		if err != nil {
			// Try to place more on an available corridor so that later
			// slots are not forced below their channel minimums.
			found := false
			for divisor := uint32(2); divisor <= slots; divisor++ {
				probe := ceilDivide(remaining, divisor)
				choice, err = r.findRoute(probe)
				if err == nil {
					found = true
					break
				}
			}
			if !found {
				return 0, false
			}
		}

		reserveChoice(r.reserved, choice)
		remaining -= choice.deliver
		score += choiceCost(choice) + 0.025
		used++
	}

	// Prefer fewer parts only when end-to-end reliability is comparable.
	score += 0.012 * float64(used*used)

	return score, true
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= maxRouteAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	var best *routeChoice
	bestScore := math.Inf(1)
	searches := 0

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		if searches >= maxForecastSearch {
			break
		}

		choice, err := r.findRoute(shard)
		searches++
		if err != nil {
			continue
		}

		score, feasible := r.forecastPlan(amt, partsLeft, choice)
		if !feasible {
			continue
		}

		if best == nil || score < bestScore {
			best = choice
			bestScore = score
		}
	}

	if best == nil {
		// Preserve a reliable terminal fallback when the bounded joint
		// search cannot construct a complete portfolio.
		for _, shard := range r.candidateAmounts(amt, partsLeft) {
			choice, err := r.findRoute(shard)
			if err != nil {
				continue
			}

			score := choiceCost(choice)
			if best == nil || score < bestScore {
				best = choice
				bestScore = score
			}
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	reserveChoice(r.reserved, best)
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}

		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(key edgeKey,
	belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = amt / 3
	} else {
		belief.estimate = (2*belief.estimate + amt/3) / 3
	}

	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnForwarded(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && belief.upperFail <= amt {
		belief.upperFail = 0
	}

	optimistic := edge.capacity * 9 / 10
	if belief.estimate < amt {
		belief.estimate = amt
	}
	if belief.estimate < optimistic {
		belief.estimate = (belief.estimate + optimistic) / 2
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}

	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}

	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	estimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10
	if estimate < optimistic {
		estimate = (estimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(estimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}

	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}

	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func (r *candidateRouter) releaseReservations(keys []edgeKey,
	amounts []lnwire.MilliSatoshi) {

	for i, key := range keys {
		value := r.reserved[key]
		if value <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = value - amounts[i]
		}
	}
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("attempt route is empty")
	}

	keys, amounts := routeEdgeData(rt)
	r.releaseReservations(keys, amounts)

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}

		r.lastFailedAmt = 0
		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	r.lastFailedAmt = rt.Hops[len(rt.Hops)-1].AmtToForward

	if failIndex < 0 || failIndex >= len(keys) {
		// Unknown failures receive only a small path-level penalty. They do
		// not justify poisoning every channel on the route.
		for _, key := range keys {
			if r.edgeFailures[key] < 2 {
				r.edgeFailures[key]++
			}
		}

		return nil
	}

	// Every channel before the failing outgoing channel accepted the HTLC.
	// The failed attempt rolls back, so this is a liquidity observation
	// without the balance shift associated with settlement.
	for i := 0; i < failIndex; i++ {
		r.learnForwarded(keys[i], amounts[i])
		if r.edgeFailures[keys[i]] > 0 {
			r.edgeFailures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]
	r.edgeFailures[key] += 2

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.broken[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	minProbability = 0.003
	maxProbability = 0.995
	riskCostMsat   = 280000.0

	lowerRetryFactor = 0.62
	minShardMsat     = lnwire.MilliSatoshi(10_000)
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
	failures uint16
	success  uint16
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[candidateEdgeKey]liquidityBelief
}{
	values: make(map[candidateEdgeKey]liquidityBelief),
}

type candidateRouter struct {
	mu sync.Mutex

	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	localSpent    map[uint64]lnwire.MilliSatoshi

	beliefs      map[candidateEdgeKey]liquidityBelief
	blocked      map[candidateEdgeKey]bool
	reserved     map[candidateEdgeKey]lnwire.MilliSatoshi
	routePenalty map[candidateEdgeKey]float64

	baseShard           lnwire.MilliSatoshi
	lastRemaining       lnwire.MilliSatoshi
	consecutiveFailures uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeByKey:     make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		localSpent:    make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[candidateEdgeKey]liquidityBelief),
		blocked:       make(map[candidateEdgeKey]bool),
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		routePenalty:  make(map[candidateEdgeKey]float64),
		lastRemaining: spec.Amount,
	}

	parts := uint32(1)
	switch {
	case spec.Amount > 1_000_000_000:
		parts = 8
	case spec.Amount > 400_000_000:
		parts = 6
	case spec.Amount > 100_000_000:
		parts = 4
	case spec.Amount > 25_000_000:
		parts = 2
	}
	if spec.MaxParts != 0 && parts > spec.MaxParts {
		parts = spec.MaxParts
	}
	if parts == 0 {
		parts = 1
	}
	r.baseShard = ceilDiv(
		spec.Amount, lnwire.MilliSatoshi(parts),
	)

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, exists := r.edgeByKey[key]; exists {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, belief := range sharedBeliefs.values {
		if _, exists := r.edgeByKey[key]; exists {
			r.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}
	return (a + b - 1) / b
}

func clampProbability(p float64) float64 {
	switch {
	case p < minProbability:
		return minProbability
	case p > maxProbability:
		return maxProbability
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.51 * math.Exp(-x/0.027)
	highMode := 0.47 / (1 + math.Exp(15*(x-0.80)))

	return clampProbability(0.005 + lowMode + highMode)
}

func (r *candidateRouter) localAvailable(
	edge *candidateEdge) lnwire.MilliSatoshi {

	available := r.localBalances[edge.key.chanID]
	spent := r.localSpent[edge.key.chanID]
	reserved := r.reserved[edge.key]

	if spent >= available {
		return 0
	}
	available -= spent
	if reserved >= available {
		return 0
	}
	return available - reserved
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if amt > r.localAvailable(edge) {
			return minProbability
		}
		return maxProbability
	}

	belief := r.beliefs[edge.key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		return minProbability
	}
	if belief.lowerOK != 0 && amt <= belief.lowerOK {
		return maxProbability
	}

	prior := bimodalPrior(amt, edge.capacity)
	if belief.estimate == 0 {
		return prior
	}

	width := math.Max(float64(edge.capacity)*0.055, 1)
	point := 1 / (1 + math.Exp(
		(float64(amt)-float64(belief.estimate))/width,
	))

	if belief.failures > belief.success {
		weight := 0.72
		if belief.failures >= 3 {
			weight = 0.84
		}
		return clampProbability(
			(1-weight)*prior + weight*point,
		)
	}

	return clampProbability(0.48*prior + 0.52*point)
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	arriving lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}

	dist := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		bestScore, exists := dist[item.node]
		if !exists || item.score > bestScore {
			continue
		}
		if item.arriving != required[item.node] {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.blocked[edge.key] {
				continue
			}

			amtOver := item.arriving
			if !edge.usable(amtOver) {
				continue
			}

			reserved := r.reserved[edge.key]
			if reserved >= edge.capacity ||
				amtOver > edge.capacity-reserved {

				continue
			}

			if edge.key.from == r.source &&
				amtOver > r.localAvailable(edge) {

				continue
			}

			belief := r.beliefs[edge.key]
			if belief.upperBad != 0 &&
				amtOver >= belief.upperBad {

				continue
			}

			probability := r.probability(edge, amtOver)
			sending := amtOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				sending += fee
			}

			risk := -math.Log(probability) * riskCostMsat
			penalty := r.routePenalty[edge.key]
			score := item.score + float64(fee) + risk +
				penalty + 200

			oldScore, exists := dist[edge.key.from]
			if exists && score >= oldScore {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:     edge.key.from,
				score:    score,
				arriving: sending,
			})
		}
	}

	if _, exists := next[r.source]; !exists {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, exists := next[node]
		if !exists {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edgeByKey) {
			return nil, errors.New("route contains a cycle")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta
		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	key := candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
	_, exists := r.edgeByKey[key]
	return key, exists
}

func routeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func routeFee(rt *route.Route) lnwire.MilliSatoshi {
	delivered := deliveredAmount(rt)
	if rt.TotalAmount <= delivered {
		return 0
	}
	return rt.TotalAmount - delivered
}

func (r *candidateRouter) routeProbability(rt *route.Route) float64 {
	probability := 1.0
	for i := range rt.Hops {
		key, exists := r.routeEdge(rt, i)
		if !exists {
			return minProbability
		}

		edge := r.edgeByKey[key]
		probability *= r.probability(
			edge, routeAmount(rt, i),
		)
	}
	return probability
}

func (r *candidateRouter) reserve(rt *route.Route) {
	for i := range rt.Hops {
		key, exists := r.routeEdge(rt, i)
		if exists {
			r.reserved[key] += routeAmount(rt, i)
		}
	}
}

func (r *candidateRouter) release(rt *route.Route) {
	for i := range rt.Hops {
		key, exists := r.routeEdge(rt, i)
		if !exists {
			continue
		}

		amt := routeAmount(rt, i)
		if amt >= r.reserved[key] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
	}
}

func appendShard(values []lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return values
	}

	seen[value] = true
	return append(values, value)
}

func (r *candidateRouter) shardCandidates(amt,
	minimum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 32)

	values = appendShard(values, seen, amt, minimum, amt)
	values = appendShard(
		values, seen, r.baseShard, minimum, amt,
	)

	fractions := []float64{
		0.82, 0.68, 0.56, 0.46, 0.38, 0.31, 0.25,
		0.20, 0.16, 0.125,
	}
	for _, fraction := range fractions {
		value := lnwire.MilliSatoshi(
			float64(amt) * fraction,
		)
		values = appendShard(
			values, seen, value, minimum, amt,
		)
	}

	for _, edge := range r.edgeByKey {
		var limit lnwire.MilliSatoshi
		switch {
		case edge.key.from == r.source:
			limit = r.localAvailable(edge)

		case r.beliefs[edge.key].lowerOK != 0:
			limit = r.beliefs[edge.key].lowerOK

		case r.beliefs[edge.key].estimate != 0:
			limit = r.beliefs[edge.key].estimate * 9 / 10

		case r.beliefs[edge.key].upperBad != 0:
			limit = r.beliefs[edge.key].upperBad * 3 / 5

		default:
			continue
		}

		values = appendShard(
			values, seen, limit, minimum, amt,
		)
		values = appendShard(
			values, seen, limit*4/5, minimum, amt,
		)
	}

	values = appendShard(
		values, seen, minimum, minimum, amt,
	)
	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})

	return values
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	r.mu.Lock()
	defer r.mu.Unlock()

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}

	if amt < r.lastRemaining {
		r.consecutiveFailures = 0
	}
	r.lastRemaining = amt

	if r.spec.MaxParts != 0 &&
		inFlightHtlcs >= r.spec.MaxParts {

		return nil, errors.New("maximum parts in flight")
	}

	partsLeft := uint32(1)
	if r.spec.MaxParts > inFlightHtlcs {
		partsLeft = r.spec.MaxParts - inFlightHtlcs
	}

	minimum := ceilDiv(
		amt, lnwire.MilliSatoshi(partsLeft),
	)
	if minimum < minShardMsat {
		minimum = minShardMsat
	}
	if minimum > amt {
		minimum = amt
	}

	candidates := r.shardCandidates(amt, minimum)
	var (
		bestRoute   *route.Route
		bestUtility = math.Inf(-1)
		lastErr     error
	)

	for _, shard := range candidates {
		rt, err := r.findRoute(shard)
		if err != nil {
			lastErr = err
			continue
		}

		probability := r.routeProbability(rt)
		fee := float64(routeFee(rt))
		sizeGain := math.Log1p(
			float64(shard) / math.Max(float64(minimum), 1),
		)

		utility := 1.35*sizeGain +
			0.42*math.Log(math.Max(probability, 1e-12)) -
			fee/2_000_000

		if shard == amt {
			utility += 0.25
		}
		if probability >= 0.09 {
			utility += 0.18
		}
		if utility > bestUtility {
			bestUtility = utility
			bestRoute = rt
		}

		if shard > minimum && probability >= 0.22 {
			break
		}
	}

	if bestRoute == nil {
		if lastErr == nil {
			lastErr = errors.New("no route found")
		}
		return nil, lastErr
	}

	r.reserve(bestRoute)
	return bestRoute, nil
}

type codedFailure interface {
	Code() lnwire.FailCode
}

func (r *candidateRouter) saveBelief(key candidateEdgeKey,
	belief liquidityBelief) {

	edge := r.edgeByKey[key]
	if edge != nil {
		if belief.lowerOK > edge.capacity {
			belief.lowerOK = edge.capacity
		}
		if belief.estimate > edge.capacity {
			belief.estimate = edge.capacity
		}
		if belief.upperBad > edge.capacity {
			belief.upperBad = edge.capacity
		}
	}

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordPass(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	remaining := edge.capacity - amt
	inferred := amt + remaining*4/5
	if inferred > belief.estimate {
		belief.estimate = inferred
	}
	if belief.success < math.MaxUint16 {
		belief.success++
	}
	if belief.failures > 0 {
		belief.failures--
	}

	r.saveBelief(key, belief)
}

func subtractFloor(value,
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if amt >= value {
		return 0
	}
	return value - amt
}

func (r *candidateRouter) recordSettlement(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil {
		return
	}
	if key.from == r.source {
		r.localSpent[key.chanID] += amt
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	remaining := edge.capacity - amt
	inferredPre := amt + remaining*4/5
	if inferredPre > belief.estimate {
		belief.estimate = inferredPre
	}

	belief.lowerOK = subtractFloor(belief.lowerOK, amt)
	belief.estimate = subtractFloor(belief.estimate, amt)
	if belief.upperBad != 0 {
		belief.upperBad = subtractFloor(
			belief.upperBad, amt,
		)
		if belief.upperBad == 0 {
			belief.upperBad = 1
		}
	}
	if belief.success < math.MaxUint16 {
		belief.success++
	}
	if belief.failures > 0 {
		belief.failures--
	}
	r.saveBelief(key, belief)

	reverseKey := candidateEdgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edgeByKey[reverseKey]
	if reverseEdge == nil || reverseKey.from == r.source {
		return
	}

	reverse := r.beliefs[reverseKey]
	if reverse.estimate > reverseEdge.capacity-amt {
		reverse.estimate = reverseEdge.capacity
	} else {
		reverse.estimate += amt
	}
	if reverse.lowerOK != 0 {
		if reverse.lowerOK > reverseEdge.capacity-amt {
			reverse.lowerOK = reverseEdge.capacity
		} else {
			reverse.lowerOK += amt
		}
	}
	if reverse.upperBad != 0 {
		if reverse.upperBad > reverseEdge.capacity-amt {
			reverse.upperBad = 0
		} else {
			reverse.upperBad += amt
		}
	}
	r.saveBelief(reverseKey, reverse)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}

	estimate := amt / 5
	depletedEstimate := edge.capacity / 25
	if estimate > depletedEstimate {
		estimate = depletedEstimate
	}
	if estimate <= 0 {
		estimate = 1
	}
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}
	if belief.lowerOK > belief.estimate {
		belief.estimate = belief.lowerOK
	}
	if belief.failures < math.MaxUint16 {
		belief.failures++
	}
	if belief.success > 0 {
		belief.success--
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.mu.Lock()
	defer r.mu.Unlock()

	r.release(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, exists := r.routeEdge(rt, i)
			if !exists {
				continue
			}

			r.recordSettlement(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.18
		}

		delivered := deliveredAmount(rt)
		if delivered > 0 {
			remaining := r.lastRemaining - delivered
			if remaining > 0 {
				target := delivered
				if target > remaining {
					target = remaining
				}
				r.baseShard = target
			}
		}
		r.consecutiveFailures = 0
		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key, exists := r.routeEdge(rt, i)
			if exists {
				r.routePenalty[key] += riskCostMsat / 3
			}
		}
		r.consecutiveFailures++
		return nil
	}

	for i := 0; i < failIndex; i++ {
		key, exists := r.routeEdge(rt, i)
		if exists {
			r.recordPass(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.7
		}
	}

	key, exists := r.routeEdge(rt, failIndex)
	if !exists {
		r.consecutiveFailures++
		return nil
	}

	code := lnwire.FailCode(0)
	if failure, ok := result.Failure.(codedFailure); ok {
		code = failure.Code()
	}

	switch code {
	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.blocked[key] = true

	default:
		failedAmt := routeAmount(rt, failIndex)
		r.recordFailure(key, failedAmt)
		r.routePenalty[key] += riskCostMsat * 1.4
	}

	r.consecutiveFailures++

	delivered := deliveredAmount(rt)
	retry := lnwire.MilliSatoshi(
		float64(delivered) * lowerRetryFactor,
	)
	if retry > 0 && retry < r.baseShard {
		r.baseShard = retry
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	riskCostMsat   = 260000.0
	minProbability = 0.003
	maxProbability = 0.995

	lowerRetryFactor = 0.62
	maxShardFactor   = 2.20
	maxShardProbes   = 28
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[candidateEdgeKey]liquidityBelief
}{
	values: make(map[candidateEdgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]liquidityBelief
	blocked       map[candidateEdgeKey]bool
	reserved      map[candidateEdgeKey]lnwire.MilliSatoshi
	routePenalty  map[candidateEdgeKey]float64

	lastRemaining lnwire.MilliSatoshi
	retryHint     lnwire.MilliSatoshi
	failureCount  uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeByKey:     make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		beliefs:       make(map[candidateEdgeKey]liquidityBelief),
		blocked:       make(map[candidateEdgeKey]bool),
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		routePenalty:  make(map[candidateEdgeKey]float64),
		lastRemaining: spec.Amount,
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, exists := r.edgeByKey[key]; exists {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, belief := range sharedBeliefs.values {
		if _, exists := r.edgeByKey[key]; exists {
			r.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}
	return (a + b - 1) / b
}

func clampProbability(p float64) float64 {
	switch {
	case p < minProbability:
		return minProbability
	case p > maxProbability:
		return maxProbability
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-x/0.024)
	highMode := 0.48 / (1 + math.Exp(15*(x-0.80)))

	return clampProbability(0.005 + lowMode + highMode)
}

func (r *candidateRouter) available(edge *candidateEdge) lnwire.MilliSatoshi {
	available := edge.capacity
	if edge.key.from == r.source {
		available = r.localBalances[edge.key.chanID]
	}

	reserved := r.reserved[edge.key]
	if reserved >= available {
		return 0
	}
	return available - reserved
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if amt > r.available(edge) {
		return minProbability
	}
	if edge.key.from == r.source {
		return maxProbability
	}

	belief := r.beliefs[edge.key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		return minProbability
	}
	if belief.lowerOK != 0 && amt <= belief.lowerOK {
		return maxProbability
	}

	prior := bimodalPrior(amt, edge.capacity)
	if belief.estimate == 0 {
		return prior
	}

	width := math.Max(float64(edge.capacity)*0.065, 1)
	point := 1 / (1 + math.Exp(
		(float64(amt)-float64(belief.estimate))/width,
	))

	return clampProbability(0.52*prior + 0.48*point)
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	arriving lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoutePass(amt lnwire.MilliSatoshi,
	allowKnownBad bool) (*route.Route, error) {

	dist := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)

		bestScore, exists := dist[item.node]
		if !exists || item.score > bestScore {
			continue
		}
		if required[item.node] != item.arriving {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.blocked[edge.key] {
				continue
			}

			amtOver := item.arriving
			if !edge.usable(amtOver) || amtOver > r.available(edge) {
				continue
			}

			belief := r.beliefs[edge.key]
			knownBad := belief.upperBad != 0 &&
				amtOver >= belief.upperBad
			if knownBad && !allowKnownBad {
				continue
			}

			sending := amtOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				if fee < 0 || sending > math.MaxInt64-fee {
					continue
				}
				sending += fee
			}

			probability := r.probability(edge, amtOver)
			risk := -math.Log(probability) * riskCostMsat

			staleProbePenalty := 0.0
			if knownBad {
				staleProbePenalty = riskCostMsat * 2.4
			}

			capacityBonus := 0.0
			if edge.capacity > 0 {
				spare := float64(r.available(edge)-amtOver) /
					float64(edge.capacity)
				if spare > 0 {
					capacityBonus = math.Min(
						45000, spare*18000,
					)
				}
			}

			score := item.score + float64(fee) + risk +
				r.routePenalty[edge.key] + staleProbePenalty +
				250 - capacityBonus

			oldScore, seen := dist[edge.key.from]
			if seen && score >= oldScore {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:     edge.key.from,
				score:    score,
				arriving: sending,
			})
		}
	}

	if _, exists := next[r.source]; !exists {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}

	rt, err := r.findRoutePass(amt, false)
	if err == nil {
		return rt, nil
	}

	// Hard liquidity bounds are intentionally retained across payments.
	// If they eliminate every path, probe the least costly stale path once
	// instead of terminally giving up without refreshing the evidence.
	return r.findRoutePass(amt, true)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, exists := next[node]
		if !exists {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edgeByKey) {
			return nil, errors.New("route contains a cycle")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		fee := outgoing.fee(amtOver[i+1])
		if fee < 0 || amtOver[i+1] > math.MaxInt64-fee {
			return nil, errors.New("route amount overflow")
		}

		amtOver[i] = amtOver[i+1] + fee
		expiryOver[i] = expiryOver[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta
		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	key := candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
	_, exists := r.edgeByKey[key]

	return key, exists
}

func routeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) reserve(rt *route.Route) {
	for i := range rt.Hops {
		key, exists := r.routeEdge(rt, i)
		if exists {
			r.reserved[key] += routeAmount(rt, i)
		}
	}
}

func (r *candidateRouter) release(rt *route.Route) {
	for i := range rt.Hops {
		key, exists := r.routeEdge(rt, i)
		if !exists {
			continue
		}

		amt := routeAmount(rt, i)
		if amt >= r.reserved[key] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
	}
}

func appendProbe(probes []lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return probes
	}

	seen[value] = true
	return append(probes, value)
}

func (r *candidateRouter) shardProbes(remaining,
	minimum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	maximum := remaining
	if minimum < remaining {
		softMax := lnwire.MilliSatoshi(
			float64(minimum) * maxShardFactor,
		)
		if softMax > minimum && softMax < maximum {
			maximum = softMax
		}
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	probes := make([]lnwire.MilliSatoshi, 0, maxShardProbes)

	probes = appendProbe(probes, seen, minimum, minimum, maximum)
	for _, factor := range []float64{
		1.12, 1.28, 1.48, 1.72, 2.00, 2.20,
	} {
		probes = appendProbe(
			probes, seen,
			lnwire.MilliSatoshi(float64(minimum)*factor),
			minimum, maximum,
		)
	}

	if r.retryHint != 0 {
		probes = appendProbe(
			probes, seen, r.retryHint, minimum, maximum,
		)
	}

	for _, belief := range r.beliefs {
		if belief.lowerOK != 0 {
			for _, factor := range []float64{0.96, 0.82} {
				probes = appendProbe(
					probes, seen,
					lnwire.MilliSatoshi(
						float64(belief.lowerOK) *
							factor,
					),
					minimum, maximum,
				)
			}
		}

		if belief.upperBad != 0 {
			for _, factor := range []float64{0.72, 0.55} {
				probes = appendProbe(
					probes, seen,
					lnwire.MilliSatoshi(
						float64(belief.upperBad) *
							factor,
					),
					minimum, maximum,
				)
			}
		}
	}

	probes = appendProbe(
		probes, seen, maximum, minimum, maximum,
	)
	sort.Slice(probes, func(i, j int) bool {
		return probes[i] < probes[j]
	})

	if len(probes) <= maxShardProbes {
		return probes
	}

	trimmed := make([]lnwire.MilliSatoshi, 0, maxShardProbes)
	for i, probe := range probes {
		if len(trimmed) == maxShardProbes {
			break
		}

		remainingSlots := maxShardProbes - len(trimmed)
		remainingItems := len(probes) - i
		if i == 0 || i == len(probes)-1 ||
			remainingItems <= remainingSlots ||
			i%(len(probes)/maxShardProbes+1) == 0 {

			trimmed = append(trimmed, probe)
		}
	}

	return trimmed
}

func (r *candidateRouter) routeQuality(rt *route.Route,
	delivered, minimum lnwire.MilliSatoshi) float64 {

	logProbability := 0.0
	for i := range rt.Hops {
		key, exists := r.routeEdge(rt, i)
		if !exists {
			return math.Inf(-1)
		}

		edge := r.edgeByKey[key]
		logProbability += math.Log(
			r.probability(edge, routeAmount(rt, i)),
		)
	}

	fee := rt.TotalAmount - delivered
	sizeGain := math.Log(
		math.Max(1, float64(delivered)/float64(minimum)),
	)

	// Reliability dominates. The size term rewards a proven high-liquidity
	// corridor enough to create unequal MPP shards, while avoiding a blind
	// preference for the largest gossip-feasible amount.
	return logProbability + 0.34*sizeGain -
		float64(fee)/riskCostMsat
}

func (r *candidateRouter) chooseRoute(remaining,
	minimum lnwire.MilliSatoshi) (*route.Route, error) {

	probes := r.shardProbes(remaining, minimum)

	var (
		best        *route.Route
		bestQuality = math.Inf(-1)
		lastErr     error
	)

	for _, shard := range probes {
		rt, err := r.findRoute(shard)
		if err != nil {
			lastErr = err
			continue
		}

		quality := r.routeQuality(rt, shard, minimum)
		if best == nil || quality > bestQuality {
			best = rt
			bestQuality = quality
		}
	}

	if best != nil {
		return best, nil
	}
	if lastErr == nil {
		lastErr = errors.New("no route found")
	}

	return nil, lastErr
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum parts in flight")
	}

	if amt < r.lastRemaining {
		r.failureCount = 0
		r.retryHint = 0
	}
	r.lastRemaining = amt

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	if partsLeft == 0 {
		return nil, errors.New("maximum parts in flight")
	}

	minimum := ceilDiv(
		amt, lnwire.MilliSatoshi(partsLeft),
	)
	if minimum <= 0 || minimum > amt {
		minimum = amt
	}

	rt, err := r.chooseRoute(amt, minimum)
	if err != nil {
		return nil, err
	}

	r.reserve(rt)
	return rt, nil
}

type codedFailure interface {
	Code() lnwire.FailCode
}

func (r *candidateRouter) saveBelief(key candidateEdgeKey,
	belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	estimate := amt
	if edge.capacity > amt {
		estimate += (edge.capacity - amt) * 4 / 5
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}

	estimate := amt * 28 / 100
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}
	if belief.lowerOK > belief.estimate {
		belief.estimate = belief.lowerOK
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.release(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, exists := r.routeEdge(rt, i)
			if !exists {
				continue
			}

			r.recordSuccess(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.20
		}

		r.failureCount = 0
		r.retryHint = 0
		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key, exists := r.routeEdge(rt, i)
			if exists {
				r.routePenalty[key] += riskCostMsat * 0.45
			}
		}

		r.failureCount++
		return nil
	}

	for i := 0; i < failIndex; i++ {
		key, exists := r.routeEdge(rt, i)
		if exists {
			r.recordSuccess(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.65
		}
	}

	key, exists := r.routeEdge(rt, failIndex)
	if !exists {
		return nil
	}

	code := lnwire.FailCode(0)
	if failure, ok := result.Failure.(codedFailure); ok {
		code = failure.Code()
	}

	failedAmount := routeAmount(rt, failIndex)
	switch code {
	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.blocked[key] = true

	default:
		r.recordFailure(key, failedAmount)
		r.routePenalty[key] += riskCostMsat

		delivered := deliveredAmount(rt)
		retry := lnwire.MilliSatoshi(
			float64(delivered) * lowerRetryFactor,
		)
		if retry > 0 &&
			(r.retryHint == 0 || retry < r.retryHint) {

			r.retryHint = retry
		}
	}

	r.failureCount++
	if r.failureCount >= 3 {
		r.routePenalty[key] += riskCostMsat * 0.35
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	mu sync.Mutex

	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved     map[edgeKey]lnwire.MilliSatoshi
	edgeFailures map[edgeKey]uint32
	broken       map[edgeKey]bool

	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if spec == nil {
		return nil, errors.New("payment specification is nil")
	}

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:  make(map[edgeKey]uint32),
		broken:        make(map[edgeKey]bool),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity * 9 / 10
		}

		if belief.estimate > edge.capacity {
			belief.estimate = edge.capacity
		}
		if belief.lowerOK > edge.capacity {
			belief.lowerOK = edge.capacity
		}
		if belief.upperFail > edge.capacity {
			belief.upperFail = 0
		}

		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005

	case p > 0.985:
		return 0.985

	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)

	lowMode := 0.50 * math.Exp(-18*x)
	highMode := 0.495 / (1 + math.Exp(22*(x-0.88)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}

		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := float64(edge.capacity) * 0.08
	if scale < 1 {
		scale = 1
	}

	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))

	confidence := math.Min(0.82, 0.20*float64(belief.samples))
	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	utility     float64
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)

		best, ok := score[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.broken[edge.key] || !edge.usable(item.amt) {
				continue
			}

			totalLiquidity := item.amt + r.reserved[edge.key]
			if totalLiquidity > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				totalLiquidity > r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(edge, item.amt)
			edgeFee := edge.fee(item.amt)
			sending := item.amt + edgeFee

			if edge.key.from == r.source {
				edgeFee = 0
				sending = item.amt
			}

			failurePenalty := 0.16 *
				math.Min(4, float64(r.edgeFailures[edge.key]))

			step := -math.Log(probability) +
				float64(edgeFee)/2_500_000 +
				0.012 + failurePenalty

			candidate := item.score + step
			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(
			r.edges[key], amounts[i],
		)
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: clampRouteProbability(probability),
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func clampRouteProbability(p float64) float64 {
	if p < 0.0001 {
		return 0.0001
	}
	if p > 0.999 {
		return 0.999
	}

	return p
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to

		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New(
				"route contains a cycle",
			)
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))

	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)

		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addCandidate(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	if minimum < 1_000 {
		minimum = 1_000
	}
	if minimum > amt {
		minimum = amt
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 18)

	addCandidate(&values, seen, amt, minimum, amt)
	addCandidate(&values, seen, amt*7/8, minimum, amt)
	addCandidate(&values, seen, amt*3/4, minimum, amt)
	addCandidate(&values, seen, amt*2/3, minimum, amt)
	addCandidate(&values, seen, amt*3/5, minimum, amt)
	addCandidate(&values, seen, amt/2, minimum, amt)
	addCandidate(&values, seen, amt*2/5, minimum, amt)
	addCandidate(&values, seen, amt/3, minimum, amt)
	addCandidate(&values, seen, minimum*2, minimum, amt)
	addCandidate(&values, seen, minimum*3/2, minimum, amt)
	addCandidate(&values, seen, minimum, minimum, amt)

	if r.lastFailedAmt > 0 {
		addCandidate(
			&values, seen, r.lastFailedAmt*7/8,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*3/4,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*2/3,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt/2,
			minimum, amt,
		)
	}

	var bounds []lnwire.MilliSatoshi
	for key, belief := range r.beliefs {
		if r.broken[key] {
			continue
		}

		if belief.lowerOK >= minimum && belief.lowerOK <= amt {
			bounds = append(bounds, belief.lowerOK)
		}

		if belief.upperFail > 1 {
			safe := belief.upperFail * 7 / 8
			if safe >= minimum && safe <= amt {
				bounds = append(bounds, safe)
			}
		}

		if belief.estimate >= minimum && belief.estimate <= amt {
			bounds = append(bounds, belief.estimate*7/8)
		}
	}

	sort.Slice(bounds, func(i, j int) bool {
		return bounds[i] > bounds[j]
	})
	if len(bounds) > 6 {
		bounds = bounds[:6]
	}

	for _, bound := range bounds {
		addCandidate(&values, seen, bound, minimum, amt)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})

	return values
}

func choiceUtility(choice *routeChoice, remaining,
	shard lnwire.MilliSatoshi) float64 {

	probability := clampRouteProbability(choice.probability)
	ratio := float64(remaining) / float64(shard)

	expectedAttempts := 1 / probability
	partCost := 0.22 * math.Max(0, ratio-1)
	feeCost := float64(choice.fee) / 2_000_000

	return expectedAttempts + partCost + feeCost
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	r.mu.Lock()
	defer r.mu.Unlock()

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= 48 {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	var best *routeChoice

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		choice.utility = choiceUtility(choice, amt, shard)
		if best == nil ||
			choice.utility < best.utility-1e-12 ||
			(math.Abs(choice.utility-best.utility) <= 1e-12 &&
				choice.deliver > best.deliver) {

			best = choice
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	for i, key := range best.keys {
		r.reserved[key] += best.amounts[i]
	}
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}

		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}

		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	failedEstimate := amt / 4
	switch {
	case belief.estimate == 0:
		belief.estimate = failedEstimate

	case belief.estimate >= amt:
		belief.estimate = (
			belief.estimate + 2*failedEstimate
		) / 3

	default:
		belief.estimate = (
			2*belief.estimate + failedEstimate
		) / 3
	}

	if belief.estimate > edge.capacity {
		belief.estimate = edge.capacity
	}
	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnAvailable(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	optimistic := edge.capacity * 9 / 10
	if belief.estimate < amt {
		belief.estimate = amt
	}
	if belief.estimate < optimistic {
		belief.estimate = (
			2*belief.estimate + optimistic
		) / 3
	}

	if belief.upperFail > 0 && belief.upperFail <= belief.lowerOK {
		belief.upperFail = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}

	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}

	return b
}

func (r *candidateRouter) learnSettlement(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	preEstimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10

	if preEstimate < optimistic {
		preEstimate = (preEstimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(preEstimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}

	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}

	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func failureEdgeIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) releaseReservations(keys []edgeKey,
	amounts []lnwire.MilliSatoshi) {

	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.mu.Lock()
	defer r.mu.Unlock()

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("attempt route is empty")
	}

	keys, amounts := routeEdgeData(rt)
	r.releaseReservations(keys, amounts)

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSettlement(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}

		r.lastFailedAmt = 0
		return nil
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	r.lastFailedAmt = delivered

	failIndex := failureEdgeIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(keys) {
		for _, key := range keys {
			if r.edgeFailures[key] < 8 {
				r.edgeFailures[key]++
			}
		}

		return nil
	}

	for i := 0; i < failIndex; i++ {
		key := keys[i]
		r.learnAvailable(key, amounts[i])

		if r.edgeFailures[key] > 0 {
			r.edgeFailures[key]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]
	if r.edgeFailures[key] < 8 {
		r.edgeFailures[key] += 2
	}

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.broken[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta   = 40
	maxRouteAttempts = 64
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved      map[edgeKey]lnwire.MilliSatoshi
	edgeFailures  map[edgeKey]uint32
	broken        map[edgeKey]bool
	routeFailures map[string]uint32

	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[edgeKey]*candidateEdge),
		localBalances:  make(map[uint64]lnwire.MilliSatoshi),
		beliefs:        make(map[edgeKey]liquidityBelief),
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:   make(map[edgeKey]uint32),
		broken:         make(map[edgeKey]bool),
		routeFailures:  make(map[string]uint32),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = normalizeBelief(belief, edge.capacity)
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-18*x)
	highMode := 0.495 / (1 + math.Exp(22*(x-0.88)))

	return clampProbability(lowMode + highMode)
}

func normalizeBelief(b liquidityBelief,
	capacity lnwire.MilliSatoshi) liquidityBelief {

	if b.lowerOK > capacity {
		b.lowerOK = capacity
	}
	if b.upperFail > capacity {
		b.upperFail = 0
	}
	if b.estimate > capacity {
		b.estimate = capacity
	}
	if b.upperFail > 0 && b.lowerOK >= b.upperFail {
		b.lowerOK = b.upperFail - 1
	}
	if b.lowerOK < 0 {
		b.lowerOK = 0
	}

	return b
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}

		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	estimate := belief.estimate
	if estimate <= 0 {
		estimate = edge.capacity / 2
	}

	scale := float64(edge.capacity) * 0.08
	if scale < 1 {
		scale = 1
	}

	point := 1 / (1 + math.Exp(
		(float64(total)-float64(estimate))/scale,
	))
	confidence := math.Min(0.82, 0.18*float64(belief.samples))

	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	utility     float64
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
	signature   string
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{r.spec.Target: 0}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: deliver,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, ok := score[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		needed := required[item.node]
		for _, edge := range r.incomingEdges[item.node] {
			if r.broken[edge.key] || !edge.usable(needed) {
				continue
			}

			total := needed + r.reserved[edge.key]
			if total > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				total > r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(edge, needed)
			edgeFee := edge.fee(needed)
			sending := needed + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = needed
			}

			failurePenalty := 0.20 *
				math.Log1p(float64(r.edgeFailures[edge.key]))
			step := -math.Log(probability) +
				float64(edgeFee)/2_500_000 +
				0.012 + failurePenalty
			candidate := item.score + step

			old, exists := score[edge.key.from]
			if exists && candidate >= old-1e-12 {
				continue
			}

			score[edge.key.from] = candidate
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(r.edges[key], amounts[i])
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
		signature:   routeSignature(keys),
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func routeSignature(keys []edgeKey) string {
	var builder strings.Builder
	for _, key := range keys {
		builder.WriteString(strconv.FormatUint(key.chanID, 10))
		builder.WriteByte('/')
	}

	return builder.String()
}

func addCandidate(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	if minimum < 1_000 {
		minimum = 1_000
	}
	if minimum > amt {
		minimum = amt
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, int(partsLeft)+18)

	// Evaluate every equal-part plan. This lets the route search jointly
	// choose the effective part count instead of relying on a halving ladder.
	for parts := uint32(1); parts <= partsLeft; parts++ {
		shard := (amt + lnwire.MilliSatoshi(parts) - 1) /
			lnwire.MilliSatoshi(parts)
		addCandidate(&values, seen, shard, minimum, amt)
	}

	addCandidate(&values, seen, amt*7/8, minimum, amt)
	addCandidate(&values, seen, amt*4/5, minimum, amt)
	addCandidate(&values, seen, amt*3/4, minimum, amt)
	addCandidate(&values, seen, amt*2/3, minimum, amt)
	addCandidate(&values, seen, amt*3/5, minimum, amt)
	addCandidate(&values, seen, amt/2, minimum, amt)

	if r.lastFailedAmt > 0 {
		addCandidate(
			&values, seen, r.lastFailedAmt*7/8,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*3/4,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*2/3,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt/2,
			minimum, amt,
		)
	}

	type breakpoint struct {
		value lnwire.MilliSatoshi
		score float64
	}

	breakpoints := make([]breakpoint, 0, len(r.beliefs)*2)
	for key, belief := range r.beliefs {
		edge := r.edges[key]
		if edge == nil || r.broken[key] {
			continue
		}

		if belief.upperFail > 1 {
			value := belief.upperFail - 1
			if value >= minimum && value <= amt {
				breakpoints = append(breakpoints, breakpoint{
					value: value,
					score: float64(value) * 2,
				})
			}

			value = belief.upperFail * 3 / 4
			if value >= minimum && value <= amt {
				breakpoints = append(breakpoints, breakpoint{
					value: value,
					score: float64(value) * 1.5,
				})
			}
		}

		available := belief.estimate
		if belief.lowerOK > available {
			available = belief.lowerOK
		}
		if available > edge.capacity {
			available = edge.capacity
		}
		available -= r.reserved[key]
		if available >= minimum && available <= amt {
			breakpoints = append(breakpoints, breakpoint{
				value: available,
				score: float64(available),
			})
		}
	}

	sort.Slice(breakpoints, func(i, j int) bool {
		return breakpoints[i].score > breakpoints[j].score
	})
	if len(breakpoints) > 10 {
		breakpoints = breakpoints[:10]
	}
	for _, point := range breakpoints {
		addCandidate(
			&values, seen, point.value, minimum, amt,
		)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})

	return values
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= maxRouteAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	var best *routeChoice

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		partCount := float64(
			(amt + shard - 1) / shard,
		)
		if partCount > float64(partsLeft) {
			continue
		}

		// Reliability remains the primary objective. The mild part-count
		// term keeps reliable unequal shards preferable to repeated probing,
		// while still allowing a full payment when its probability is good.
		routePenalty := 0.34 * math.Log1p(
			float64(r.routeFailures[choice.signature]),
		)
		choice.utility = -math.Log(choice.probability) +
			0.16*math.Log(partCount) +
			float64(choice.fee)/2_500_000 +
			routePenalty

		if best == nil || choice.utility < best.utility {
			best = choice
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	for i, key := range best.keys {
		r.reserved[key] += best.amounts[i]
	}
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	edge := r.edges[key]
	if edge != nil {
		belief = normalizeBelief(belief, edge.capacity)
	}

	r.beliefs[key] = belief
	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) observePass(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.estimate < amt {
		belief.estimate = amt
	}

	optimistic := edge.capacity * 4 / 5
	if belief.estimate < optimistic {
		belief.estimate = (belief.estimate + optimistic) / 2
	}
	if belief.upperFail > 0 && belief.upperFail <= belief.lowerOK {
		belief.upperFail = 0
	}
	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	depletedEstimate := amt / 5
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = depletedEstimate
	} else {
		belief.estimate =
			(3*belief.estimate + depletedEstimate) / 4
	}

	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = belief.upperFail - 1
	}
	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}

	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}

	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	if key.from != r.source {
		belief := r.beliefs[key]
		preEstimate := maxMSat(belief.estimate, amt)
		optimistic := edge.capacity * 9 / 10
		if preEstimate < optimistic {
			preEstimate = (preEstimate + optimistic) / 2
		}

		belief.estimate = subtractFloor(preEstimate, amt, 0)
		belief.lowerOK = subtractFloor(
			maxMSat(belief.lowerOK, amt), amt, 0,
		)
		if belief.upperFail > 0 {
			belief.upperFail = subtractFloor(
				belief.upperFail, amt, 1,
			)
		}
		belief.samples++
		r.storeBelief(key, belief)
	}

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}
	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}
	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}
	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func failureEdgeIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) releaseReservations(keys []edgeKey,
	amounts []lnwire.MilliSatoshi) {

	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("attempt route is empty")
	}

	keys, amounts := routeEdgeData(rt)
	r.releaseReservations(keys, amounts)
	signature := routeSignature(keys)

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}

		delete(r.routeFailures, signature)
		r.lastFailedAmt = 0
		return nil
	}

	r.routeFailures[signature]++
	r.lastFailedAmt =
		rt.Hops[len(rt.Hops)-1].AmtToForward

	failIndex := failureEdgeIndex(
		rt, result.FailureSource,
	)
	if failIndex < 0 || failIndex >= len(keys) {
		// An unattributed failure says nothing reliable about a specific
		// channel. Penalize only this complete route so alternatives are
		// explored without poisoning every edge it contains.
		return nil
	}

	// Every channel before the failing node forwarded the HTLC. Record that
	// amount as passable without applying settlement balance changes.
	for i := 0; i < failIndex; i++ {
		r.observePass(keys[i], amounts[i])
		if r.edgeFailures[keys[i]] > 0 {
			r.edgeFailures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]
	r.edgeFailures[key]++

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)
		r.edgeFailures[key]++

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.broken[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta   = 40
	maxRouteAttempts = 48
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type attemptedRoute struct {
	pathHash uint64
	amount   lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved      map[edgeKey]lnwire.MilliSatoshi
	edgeFailures  map[edgeKey]uint32
	policyBroken  map[edgeKey]bool
	attempted     map[attemptedRoute]uint32
	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:  make(map[edgeKey]uint32),
		policyBroken:  make(map[edgeKey]bool),
		attempted:     make(map[attemptedRoute]uint32),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005

	case p > 0.985:
		return 0.985

	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-18*x)
	highMode := 0.495 / (1 + math.Exp(22*(x-0.88)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}

		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := float64(edge.capacity) * 0.08
	if scale < 1 {
		scale = 1
	}

	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))
	confidence := math.Min(0.82, 0.20*float64(belief.samples))

	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

func (r *candidateRouter) edgeAvailable(edge *candidateEdge,
	amt lnwire.MilliSatoshi) bool {

	if r.policyBroken[edge.key] || !edge.usable(amt) {
		return false
	}

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return false
	}

	if edge.key.from == r.source {
		return total <= r.localBalances[edge.key.chanID]
	}

	upper := r.beliefs[edge.key].upperFail
	return upper == 0 || total < upper
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	utility     float64
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
	pathHash    uint64
}

func hashPath(keys []edgeKey) uint64 {
	hash := uint64(1469598103934665603)
	for _, key := range keys {
		hash ^= key.chanID
		hash *= 1099511628211

		for _, b := range key.from {
			hash ^= uint64(b)
			hash *= 1099511628211
		}
		for _, b := range key.to {
			hash ^= uint64(b)
			hash *= 1099511628211
		}
	}

	return hash
}

func (r *candidateRouter) findRoute(deliver lnwire.MilliSatoshi,
	diversity map[edgeKey]float64) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{r.spec.Target: 0}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, ok := score[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if !r.edgeAvailable(edge, item.amt) {
				continue
			}

			probability := r.edgeProbability(edge, item.amt)
			edgeFee := edge.fee(item.amt)
			sending := item.amt + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = item.amt
			}

			failurePenalty := 0.24 *
				math.Log1p(float64(r.edgeFailures[edge.key]))
			capacityRatio := float64(item.amt) /
				float64(edge.capacity)
			capacityPenalty := 0.035 * capacityRatio *
				capacityRatio

			step := -math.Log(probability) +
				float64(edgeFee)/2_500_000 +
				0.012 + failurePenalty + capacityPenalty +
				diversity[edge.key]
			candidate := item.score + step

			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(
			r.edges[key], amounts[i],
		)
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
		pathHash:    hashPath(keys),
	}, nil
}

func (r *candidateRouter) routeAlternatives(
	deliver lnwire.MilliSatoshi) []*routeChoice {

	const alternatives = 5

	diversity := make(map[edgeKey]float64)
	seen := make(map[uint64]bool)
	choices := make([]*routeChoice, 0, alternatives)

	for round := 0; round < alternatives*2; round++ {
		choice, err := r.findRoute(deliver, diversity)
		if err != nil {
			break
		}

		if !seen[choice.pathHash] {
			seen[choice.pathHash] = true
			choices = append(choices, choice)
			if len(choices) == alternatives {
				break
			}
		}

		penalty := 0.30
		if seen[choice.pathHash] {
			penalty = 0.48
		}
		for _, key := range choice.keys {
			diversity[key] += penalty
		}
	}

	return choices
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to

		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New(
				"route contains a cycle",
			)
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))

	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addCandidate(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	if minimum < 1_000 {
		minimum = 1_000
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 24)

	addCandidate(&values, seen, amt, minimum, amt)
	addCandidate(&values, seen, amt*7/8, minimum, amt)
	addCandidate(&values, seen, amt*3/4, minimum, amt)
	addCandidate(&values, seen, amt*2/3, minimum, amt)
	addCandidate(&values, seen, amt*3/5, minimum, amt)
	addCandidate(&values, seen, amt/2, minimum, amt)
	addCandidate(&values, seen, amt*2/5, minimum, amt)
	addCandidate(&values, seen, amt/3, minimum, amt)
	addCandidate(&values, seen, minimum*5/2, minimum, amt)
	addCandidate(&values, seen, minimum*2, minimum, amt)
	addCandidate(&values, seen, minimum*3/2, minimum, amt)
	addCandidate(&values, seen, minimum, minimum, amt)

	if r.lastFailedAmt > 0 {
		addCandidate(
			&values, seen, r.lastFailedAmt*3/4,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*5/8,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt/2,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*3/8,
			minimum, amt,
		)
	}

	var bounds []lnwire.MilliSatoshi
	for key, belief := range r.beliefs {
		if r.policyBroken[key] || belief.upperFail <= 1 {
			continue
		}

		for _, numerator := range []lnwire.MilliSatoshi{7, 3, 2} {
			denominator := lnwire.MilliSatoshi(8)
			if numerator == 3 {
				denominator = 4
			}
			if numerator == 2 {
				denominator = 3
			}

			bound := belief.upperFail * numerator / denominator
			if bound >= minimum && bound <= amt {
				bounds = append(bounds, bound)
			}
		}
	}

	sort.Slice(bounds, func(i, j int) bool {
		return bounds[i] > bounds[j]
	})
	if len(bounds) > 8 {
		bounds = bounds[:8]
	}

	for _, bound := range bounds {
		addCandidate(
			&values, seen, bound, minimum, amt,
		)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})

	return values
}

func ceilParts(total, shard lnwire.MilliSatoshi) uint32 {
	return uint32((total + shard - 1) / shard)
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= maxRouteAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	var best *routeChoice

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		partsNeeded := ceilParts(amt, shard)
		if partsNeeded > partsLeft {
			continue
		}

		for _, choice := range r.routeAlternatives(shard) {
			attempt := attemptedRoute{
				pathHash: choice.pathHash,
				amount:   choice.deliver,
			}
			tries := r.attempted[attempt]
			if tries >= 1 {
				continue
			}

			risk := -math.Log(choice.probability)
			partFactor := math.Sqrt(float64(partsNeeded))
			choice.utility = risk*partFactor +
				0.075*float64(partsNeeded-1) +
				float64(choice.fee)/2_500_000 +
				0.20*float64(tries)

			if best == nil || choice.utility < best.utility {
				best = choice
			}
		}
	}

	if best == nil {
		return nil, errors.New("no untried route found")
	}

	for i, key := range best.keys {
		r.reserved[key] += best.amounts[i]
	}

	r.attempted[attemptedRoute{
		pathHash: best.pathHash,
		amount:   best.deliver,
	}]++
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}

		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}

		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(key edgeKey,
	belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnPassed(key edgeKey,
	amt lnwire.MilliSatoshi) {

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.estimate < amt {
		belief.estimate = amt
	}
	if belief.upperFail > 0 && belief.upperFail <= belief.lowerOK {
		belief.upperFail = 0
	}
	belief.samples++

	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	if key.from == r.source {
		balance := r.localBalances[key.chanID]
		if amt <= balance {
			r.localBalances[key.chanID] = amt - 1
		}
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	failedEstimate := amt / 4
	switch {
	case belief.estimate == 0:
		belief.estimate = failedEstimate

	case belief.estimate >= amt:
		belief.estimate = (
			belief.estimate + 2*failedEstimate
		) / 3

	default:
		belief.estimate = (
			2*belief.estimate + failedEstimate
		) / 3
	}

	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}
	belief.samples++

	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}

	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}

	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	preEstimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10
	if preEstimate < optimistic {
		preEstimate = (preEstimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(preEstimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}
	belief.samples++

	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}

	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func (r *candidateRouter) releaseReservations(keys []edgeKey,
	amounts []lnwire.MilliSatoshi) {

	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}
}

func failureEdgeIndex(rt *route.Route,
	failureSource route.Vertex) int {

	if failureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == failureSource {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("attempt route is empty")
	}

	keys, amounts := routeEdgeData(rt)
	r.releaseReservations(keys, amounts)

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}

		r.lastFailedAmt = 0
		return nil
	}

	failIndex := failureEdgeIndex(rt, result.FailureSource)
	r.lastFailedAmt = rt.Hops[len(rt.Hops)-1].AmtToForward

	if failIndex < 0 || failIndex >= len(keys) {
		return nil
	}

	for i := 0; i < failIndex; i++ {
		r.learnPassed(keys[i], amounts[i])
		if r.edgeFailures[keys[i]] > 0 {
			r.edgeFailures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]
	r.edgeFailures[key] += 2

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBroken[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved     map[edgeKey]lnwire.MilliSatoshi
	edgeFailures map[edgeKey]uint32
	broken       map[edgeKey]bool

	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:  make(map[edgeKey]uint32),
		broken:        make(map[edgeKey]bool),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-18*x)
	highMode := 0.495 / (1 + math.Exp(22*(x-0.88)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}

		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := math.Max(float64(edge.capacity)*0.10, 1)
	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))

	confidence := math.Min(0.78, 0.22*float64(belief.samples))
	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	utility     float64
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, ok := score[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.broken[edge.key] || !edge.usable(item.amt) {
				continue
			}

			total := item.amt + r.reserved[edge.key]
			if total > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				total > r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(edge, item.amt)
			edgeFee := edge.fee(item.amt)
			sending := item.amt + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = item.amt
			}

			step := -math.Log(probability) +
				float64(edgeFee)/2_000_000 +
				0.012 +
				0.22*float64(r.edgeFailures[edge.key])
			candidate := item.score + step

			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(
			r.edges[key], amounts[i],
		)
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to

		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New(
				"route contains a cycle",
			)
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addCandidate(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	if minimum < 1_000 {
		minimum = 1_000
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 18)

	addCandidate(&values, seen, amt, minimum, amt)
	addCandidate(&values, seen, amt*7/8, minimum, amt)
	addCandidate(&values, seen, amt*3/4, minimum, amt)
	addCandidate(&values, seen, amt*2/3, minimum, amt)
	addCandidate(&values, seen, amt/2, minimum, amt)
	addCandidate(&values, seen, amt/3, minimum, amt)
	addCandidate(&values, seen, minimum*2, minimum, amt)
	addCandidate(&values, seen, minimum*3/2, minimum, amt)
	addCandidate(&values, seen, minimum, minimum, amt)

	if r.lastFailedAmt > 0 {
		addCandidate(
			&values, seen, r.lastFailedAmt*4/5,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*2/3,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt/2,
			minimum, amt,
		)
	}

	var bounds []lnwire.MilliSatoshi
	for key, belief := range r.beliefs {
		if r.broken[key] {
			continue
		}

		if belief.lowerOK >= minimum && belief.lowerOK <= amt {
			bounds = append(bounds, belief.lowerOK)
		}
		if belief.upperFail > 1 {
			bounds = append(bounds, belief.upperFail*4/5)
			bounds = append(bounds, belief.upperFail*2/3)
		}
		if belief.samples > 0 && belief.estimate > 0 {
			bounds = append(bounds, belief.estimate*4/5)
		}
	}

	sort.Slice(bounds, func(i, j int) bool {
		return bounds[i] > bounds[j]
	})
	if len(bounds) > 6 {
		bounds = bounds[:6]
	}

	for _, bound := range bounds {
		addCandidate(
			&values, seen, bound, minimum, amt,
		)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})

	return values
}

func (r *candidateRouter) reserveChoice(choice *routeChoice) {
	for i, key := range choice.keys {
		r.reserved[key] += choice.amounts[i]
	}
}

func (r *candidateRouter) releaseChoice(choice *routeChoice) {
	for i, key := range choice.keys {
		value := r.reserved[key]
		if value <= choice.amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = value - choice.amounts[i]
		}
	}
}

func choiceCost(choice *routeChoice) float64 {
	return -math.Log(choice.probability) +
		float64(choice.fee)/2_000_000
}

func (r *candidateRouter) evaluatePlan(first *routeChoice,
	total lnwire.MilliSatoshi, partsLeft uint32) (float64, bool) {

	partCount := uint32(
		(total + first.deliver - 1) / first.deliver,
	)
	if partCount == 0 {
		partCount = 1
	}
	if partCount > partsLeft {
		return 0, false
	}

	choices := []*routeChoice{first}
	r.reserveChoice(first)

	defer func() {
		for i := len(choices) - 1; i >= 0; i-- {
			r.releaseChoice(choices[i])
		}
	}()

	score := choiceCost(first)
	remaining := total - first.deliver

	for slots := partCount - 1; slots > 0; slots-- {
		shard := (remaining + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)

		choice, err := r.findRoute(shard)
		if err != nil {
			return 0, false
		}

		choices = append(choices, choice)
		r.reserveChoice(choice)
		score += choiceCost(choice)
		remaining -= shard
	}

	if remaining != 0 {
		return 0, false
	}

	// This prices the expected reliability of the complete route set.
	// The small per-part charge avoids unnecessary fragmentation when
	// similarly reliable plans exist.
	score += 0.065 * float64(partCount)

	return score, true
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= 48 {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	var best *routeChoice

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		utility, ok := r.evaluatePlan(
			choice, amt, partsLeft,
		)
		if !ok {
			continue
		}
		choice.utility = utility

		if best == nil || choice.utility < best.utility {
			best = choice
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.reserveChoice(best)
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func normalizeBelief(edge *candidateEdge,
	belief *liquidityBelief) {

	if belief.estimate < 0 {
		belief.estimate = 0
	}
	if belief.estimate > edge.capacity {
		belief.estimate = edge.capacity
	}
	if belief.lowerOK > edge.capacity {
		belief.lowerOK = edge.capacity
	}
	if belief.upperFail > edge.capacity {
		belief.upperFail = 0
	}
	if belief.upperFail > 0 &&
		belief.lowerOK >= belief.upperFail {

		belief.upperFail = 0
	}
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	edge := r.edges[key]
	if edge != nil {
		normalizeBelief(edge, &belief)
	}

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = amt / 3
	} else {
		belief.estimate = (2*belief.estimate + amt/3) / 3
	}

	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnProbeSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.estimate < amt {
		belief.estimate = amt
	}

	optimistic := edge.capacity * 4 / 5
	if belief.estimate < optimistic {
		belief.estimate =
			(2*belief.estimate + optimistic) / 3
	}

	if belief.upperFail > 0 && belief.upperFail <= amt {
		belief.upperFail = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}

	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}

	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	preEstimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10
	if preEstimate < optimistic {
		preEstimate = (preEstimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(preEstimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}

	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}

	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func failureEdgeIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	keys, amounts := routeEdgeData(rt)
	for i, key := range keys {
		value := r.reserved[key]
		if value <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = value - amounts[i]
		}
	}

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}

		r.lastFailedAmt = 0
		return nil
	}

	if len(rt.Hops) == 0 {
		return nil
	}

	r.lastFailedAmt =
		rt.Hops[len(rt.Hops)-1].AmtToForward

	failIndex := failureEdgeIndex(
		rt, result.FailureSource,
	)
	if failIndex < 0 || failIndex >= len(keys) {
		for _, key := range keys {
			r.edgeFailures[key]++
		}

		return nil
	}

	// Every edge before the reported failure forwarded the HTLC. Since
	// the failed attempt unwinds, this is evidence without a balance
	// shift.
	for i := 0; i < failIndex; i++ {
		r.learnProbeSuccess(keys[i], amounts[i])
		if r.edgeFailures[keys[i]] > 0 {
			r.edgeFailures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex] + r.reserved[key]
	r.edgeFailures[key] += 2

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.broken[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	maxAttempts    = 48
	maxPlanParts   = 16
	planBeamWidth  = 12
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved     map[edgeKey]lnwire.MilliSatoshi
	edgeFailures map[edgeKey]uint32
	broken       map[edgeKey]bool

	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if spec == nil {
		return nil, errors.New("payment specification is nil")
	}

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:  make(map[edgeKey]uint32),
		broken:        make(map[edgeKey]bool),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-18*x)
	highMode := 0.495 / (1 + math.Exp(22*(x-0.88)))

	return clampProbability(lowMode + highMode)
}

func reservedAmount(reservations map[edgeKey]lnwire.MilliSatoshi,
	key edgeKey) lnwire.MilliSatoshi {

	if reservations == nil {
		return 0
	}

	return reservations[key]
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi) float64 {

	total := amt + reservedAmount(reservations, edge.key)
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}

		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := float64(edge.capacity) * 0.10
	if scale < 1 {
		scale = 1
	}

	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))
	confidence := math.Min(0.78, 0.22*float64(belief.samples))

	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
}

func (r *candidateRouter) findRoute(deliver lnwire.MilliSatoshi,
	reservations map[edgeKey]lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{r.spec.Target: 0}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, ok := score[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.broken[edge.key] || !edge.usable(item.amt) {
				continue
			}

			reserved := reservedAmount(reservations, edge.key)
			if item.amt+reserved > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				item.amt+reserved >
					r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(
				edge, item.amt, reservations,
			)
			edgeFee := edge.fee(item.amt)
			sending := item.amt + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = item.amt
			}

			failurePenalty := 0.20 *
				float64(r.edgeFailures[edge.key])
			step := -math.Log(probability) +
				float64(edgeFee)/2_500_000 +
				0.012 + failurePenalty
			candidate := item.score + step

			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(
			r.edges[key], amounts[i], reservations,
		)
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to

		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func cloneReservations(
	source map[edgeKey]lnwire.MilliSatoshi) map[edgeKey]lnwire.MilliSatoshi {

	clone := make(map[edgeKey]lnwire.MilliSatoshi, len(source))
	for key, amount := range source {
		clone[key] = amount
	}

	return clone
}

func reserveChoice(reservations map[edgeKey]lnwire.MilliSatoshi,
	choice *routeChoice) {

	for i, key := range choice.keys {
		reservations[key] += choice.amounts[i]
	}
}

func addAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	maximum lnwire.MilliSatoshi) {

	if value < 1_000 {
		value = 1_000
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) planningAmounts(
	remaining lnwire.MilliSatoshi, slots uint32,
	reservations map[edgeKey]lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 20)

	addAmount(&values, seen, remaining, remaining)
	if slots > 1 {
		slotsMSat := lnwire.MilliSatoshi(slots)
		balanced := (remaining + slotsMSat - 1) / slotsMSat

		addAmount(&values, seen, remaining*4/5, remaining)
		addAmount(&values, seen, remaining*3/4, remaining)
		addAmount(&values, seen, remaining*2/3, remaining)
		addAmount(&values, seen, remaining/2, remaining)
		addAmount(&values, seen, remaining*2/5, remaining)
		addAmount(&values, seen, remaining/3, remaining)
		addAmount(&values, seen, remaining/4, remaining)
		addAmount(&values, seen, balanced*3/2, remaining)
		addAmount(&values, seen, balanced*5/4, remaining)
		addAmount(&values, seen, balanced, remaining)
	}

	if r.lastFailedAmt > 0 {
		addAmount(
			&values, seen, r.lastFailedAmt*4/5, remaining,
		)
		addAmount(
			&values, seen, r.lastFailedAmt*2/3, remaining,
		)
		addAmount(
			&values, seen, r.lastFailedAmt/2, remaining,
		)
	}

	var breakpoints []lnwire.MilliSatoshi
	for key, edge := range r.edges {
		if r.broken[key] {
			continue
		}

		reserved := reservedAmount(reservations, key)
		if reserved >= edge.capacity {
			continue
		}

		belief := r.beliefs[key]
		available := edge.capacity - reserved

		if belief.lowerOK > reserved {
			breakpoints = append(
				breakpoints, belief.lowerOK-reserved,
			)
		}
		if belief.upperFail > reserved+1 {
			breakpoints = append(
				breakpoints,
				(belief.upperFail-reserved)*3/4,
			)
		}
		if belief.estimate > reserved {
			breakpoints = append(
				breakpoints,
				(belief.estimate-reserved)*9/10,
			)
		}

		breakpoints = append(breakpoints, available*4/5)
	}

	sort.Slice(breakpoints, func(i, j int) bool {
		return breakpoints[i] > breakpoints[j]
	})

	added := 0
	for _, amount := range breakpoints {
		if amount < 1_000 || amount > remaining {
			continue
		}

		before := len(values)
		addAmount(&values, seen, amount, remaining)
		if len(values) != before {
			added++
		}
		if added == 8 {
			break
		}
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})

	return values
}

func (r *candidateRouter) incrementalRisk(choice *routeChoice,
	reservations map[edgeKey]lnwire.MilliSatoshi) float64 {

	risk := 0.0
	for i, key := range choice.keys {
		edge := r.edges[key]
		oldAmount := reservedAmount(reservations, key)

		oldProbability := 1.0
		if oldAmount > 0 {
			oldProbability = r.edgeProbability(
				edge, 0, reservations,
			)
		}

		newProbability := r.edgeProbability(
			edge, choice.amounts[i], reservations,
		)
		ratio := newProbability / oldProbability
		if ratio > 1 {
			ratio = 1
		}
		if ratio < 0.005 {
			ratio = 0.005
		}

		risk += -math.Log(ratio)
	}

	return risk
}

type planState struct {
	remaining    lnwire.MilliSatoshi
	reservations map[edgeKey]lnwire.MilliSatoshi
	first        *routeChoice
	score        float64
	parts        uint32
	rank         float64
}

func (r *candidateRouter) planRouteSet(
	amount lnwire.MilliSatoshi, partsLeft uint32) *routeChoice {

	if partsLeft == 0 {
		return nil
	}
	if partsLeft > maxPlanParts {
		partsLeft = maxPlanParts
	}

	states := []*planState{{
		remaining:    amount,
		reservations: cloneReservations(r.reserved),
	}}

	var best *planState

	for depth := uint32(0); depth < partsLeft; depth++ {
		nextStates := make([]*planState, 0, planBeamWidth*8)

		for _, state := range states {
			if state.remaining == 0 {
				if best == nil || state.score < best.score {
					best = state
				}
				continue
			}

			slots := partsLeft - depth
			for _, shard := range r.planningAmounts(
				state.remaining, slots, state.reservations,
			) {
				if shard < state.remaining && slots == 1 {
					continue
				}

				choice, err := r.findRoute(
					shard, state.reservations,
				)
				if err != nil {
					continue
				}

				reservations := cloneReservations(
					state.reservations,
				)
				stepRisk := r.incrementalRisk(
					choice, state.reservations,
				)
				reserveChoice(reservations, choice)

				first := state.first
				if first == nil {
					first = choice
				}

				remaining := state.remaining - shard
				score := state.score + stepRisk +
					float64(choice.fee)/3_000_000 +
					0.025

				child := &planState{
					remaining:    remaining,
					reservations: reservations,
					first:        first,
					score:        score,
					parts:        state.parts + 1,
				}
				child.rank = child.score +
					float64(child.remaining)/
						float64(amount)

				if remaining == 0 {
					if best == nil || score < best.score {
						best = child
					}
				}

				nextStates = append(nextStates, child)
			}
		}

		if len(nextStates) == 0 {
			break
		}

		sort.Slice(nextStates, func(i, j int) bool {
			if nextStates[i].rank == nextStates[j].rank {
				return nextStates[i].remaining <
					nextStates[j].remaining
			}

			return nextStates[i].rank < nextStates[j].rank
		})

		if len(nextStates) > planBeamWidth {
			nextStates = nextStates[:planBeamWidth]
		}
		states = nextStates
	}

	if best != nil {
		return best.first
	}

	return nil
}

func (r *candidateRouter) fallbackRoute(
	amount lnwire.MilliSatoshi,
	partsLeft uint32) *routeChoice {

	var best *routeChoice
	bestScore := math.Inf(1)

	for _, shard := range r.planningAmounts(
		amount, partsLeft, r.reserved,
	) {
		choice, err := r.findRoute(shard, r.reserved)
		if err != nil {
			continue
		}

		parts := math.Ceil(
			float64(amount) / float64(shard),
		)
		score := r.incrementalRisk(choice, r.reserved) +
			0.08*parts +
			float64(choice.fee)/2_500_000

		if score < bestScore {
			best = choice
			bestScore = score
		}
	}

	return best
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	best := r.planRouteSet(amt, partsLeft)
	if best == nil {
		best = r.fallbackRoute(amt, partsLeft)
	}
	if best == nil {
		return nil, errors.New("no route found")
	}

	reserveChoice(r.reserved, best)
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = amt / 3
	} else {
		belief.estimate = (2*belief.estimate + amt/3) / 3
	}

	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnProbeSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && belief.upperFail <= belief.lowerOK {
		belief.upperFail = 0
	}

	optimistic := edge.capacity * 9 / 10
	if belief.estimate < amt {
		belief.estimate = amt
	}
	if belief.estimate < optimistic {
		belief.estimate = (belief.estimate + optimistic) / 2
	}
	if belief.estimate > edge.capacity {
		belief.estimate = edge.capacity
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}

	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}

	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	preEstimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10
	if preEstimate < optimistic {
		preEstimate = (preEstimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(preEstimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}

	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}

	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func (r *candidateRouter) releaseReservations(keys []edgeKey,
	amounts []lnwire.MilliSatoshi) {

	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}
}

func failureEdgeIndex(rt *route.Route,
	failureSource route.Vertex) int {

	if failureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == failureSource {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("attempt route is empty")
	}

	keys, amounts := routeEdgeData(rt)
	r.releaseReservations(keys, amounts)

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}

		r.lastFailedAmt = 0
		return nil
	}

	delivered := rt.Hops[len(rt.Hops)-1].AmtToForward
	r.lastFailedAmt = delivered

	failIndex := failureEdgeIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(keys) {
		for _, key := range keys {
			r.edgeFailures[key]++
		}

		return nil
	}

	// Every edge before the failing edge forwarded the HTLC. This proves
	// liquidity for the attempted amount, but the failed HTLC rolled back,
	// so these observations must not shift channel balances.
	for i := 0; i < failIndex; i++ {
		r.learnProbeSuccess(keys[i], amounts[i])
		if r.edgeFailures[keys[i]] > 0 {
			r.edgeFailures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]
	r.edgeFailures[key] += 3

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.broken[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	minProbability = 0.003
	maxProbability = 0.995

	// Reliability is the primary routing objective. Fees remain relevant,
	// but should not make a cheap, low-probability route dominate a much
	// more reliable route.
	riskCostMsat = 300000.0

	// Candidate shard sizes form a geometric ladder. Route selection then
	// jointly chooses the shard and path with the greatest expected
	// progress.
	shardStep = 0.72

	maxShardCandidates = 18
	minShardMsat       = lnwire.MilliSatoshi(10_000)
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(
	amt lnwire.MilliSatoshi) bool {

	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return true
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[candidateEdgeKey]liquidityBelief
}{
	values: make(map[candidateEdgeKey]liquidityBelief),
}

type amountPenalty struct {
	threshold lnwire.MilliSatoshi
	cost      float64
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]liquidityBelief
	blocked       map[candidateEdgeKey]bool
	reserved      map[candidateEdgeKey]lnwire.MilliSatoshi
	penalties     map[candidateEdgeKey]amountPenalty

	initialShard lnwire.MilliSatoshi
	lastFailed  lnwire.MilliSatoshi
	lastRemain  lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeByKey:     make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		beliefs:       make(map[candidateEdgeKey]liquidityBelief),
		blocked:       make(map[candidateEdgeKey]bool),
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		penalties:     make(map[candidateEdgeKey]amountPenalty),
		lastRemain:    spec.Amount,
	}

	parts := spec.MaxParts
	if parts == 0 {
		parts = 1
	}
	r.initialShard = ceilDiv(
		spec.Amount, lnwire.MilliSatoshi(parts),
	)

	ctx := context.Background()
	seen := map[route.Vertex]bool{
		source: true,
	}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edgeByKey[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, belief := range sharedBeliefs.values {
		if _, ok := r.edgeByKey[key]; ok {
			r.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}

	return (a + b - 1) / b
}

func clampProbability(p float64) float64 {
	if p < minProbability {
		return minProbability
	}
	if p > maxProbability {
		return maxProbability
	}

	return p
}

func bimodalPrior(
	amt, capacity lnwire.MilliSatoshi) float64 {

	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)

	// The first mode describes tiny payments that can pass even when the
	// directed side is nearly depleted. The second describes channels
	// whose balance is concentrated on the usable side.
	lowMode := 0.50 * math.Exp(-x/0.024)
	highMode := 0.48 / (1 + math.Exp(15*(x-0.77)))

	return clampProbability(0.005 + lowMode + highMode)
}

func (r *candidateRouter) availableLocal(
	edge *candidateEdge) lnwire.MilliSatoshi {

	available := r.localBalances[edge.key.chanID]
	reserved := r.reserved[edge.key]
	if reserved >= available {
		return 0
	}

	return available - reserved
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.key.from == r.source {
		if amt > r.availableLocal(edge) {
			return minProbability
		}

		return maxProbability
	}

	belief := r.beliefs[edge.key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		return minProbability
	}
	if belief.lowerOK != 0 && amt <= belief.lowerOK {
		return maxProbability
	}

	prior := bimodalPrior(amt, edge.capacity)
	if belief.estimate == 0 {
		return prior
	}

	width := math.Max(float64(edge.capacity)*0.065, 1)
	point := 1 / (1 + math.Exp(
		(float64(amt)-float64(belief.estimate))/width,
	))

	// Bounds carry the strongest evidence. Between them, the estimate is
	// useful but the bimodal prior remains dominant enough to prevent a
	// single observation from overfitting the route choice.
	return clampProbability(0.60*prior + 0.40*point)
}

func (r *candidateRouter) edgePenalty(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) float64 {

	penalty, ok := r.penalties[key]
	if !ok || penalty.cost <= 0 {
		return 0
	}

	if penalty.threshold <= 0 || amt >= penalty.threshold {
		return penalty.cost
	}

	// A liquidity failure is evidence against the attempted amount, not
	// against every smaller shard. Penalty strength falls quadratically
	// below the failed amount.
	ratio := float64(amt) / float64(penalty.threshold)
	return penalty.cost * ratio * ratio * 0.20
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	arriving lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]

	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}

	dist := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)

		bestScore, ok := dist[item.node]
		if !ok || item.score > bestScore {
			continue
		}
		if item.arriving != required[item.node] {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.blocked[edge.key] {
				continue
			}

			amtOver := item.arriving
			if !edge.usable(amtOver) {
				continue
			}

			reserved := r.reserved[edge.key]
			if reserved >= edge.capacity ||
				amtOver > edge.capacity-reserved {

				continue
			}

			if edge.key.from == r.source &&
				amtOver > r.availableLocal(edge) {

				continue
			}

			probability := r.probability(edge, amtOver)
			belief := r.beliefs[edge.key]
			if belief.upperBad != 0 &&
				amtOver >= belief.upperBad {

				continue
			}

			sending := amtOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				sending += fee
			} else if sending > r.availableLocal(edge) {
				continue
			}

			risk := -math.Log(probability) * riskCostMsat
			score := item.score + float64(fee) + risk +
				r.edgePenalty(edge.key, amtOver) + 200

			oldScore, exists := dist[edge.key.from]
			if exists && score >= oldScore {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge

			heap.Push(pq, &dijkstraItem{
				node:     edge.key.from,
				score:    score,
				arriving: sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to

		if len(path) > len(r.edgeByKey) {
			return nil, errors.New("route contains a cycle")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta

		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	key := candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
	_, ok := r.edgeByKey[key]

	return key, ok
}

func routeAmount(
	rt *route.Route, index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}

	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(
	rt *route.Route) lnwire.MilliSatoshi {

	if len(rt.Hops) == 0 {
		return 0
	}

	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func routeFee(rt *route.Route) lnwire.MilliSatoshi {
	delivered := deliveredAmount(rt)
	if rt.TotalAmount <= delivered {
		return 0
	}

	return rt.TotalAmount - delivered
}

func (r *candidateRouter) routeProbability(
	rt *route.Route) float64 {

	probability := 1.0
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			return minProbability
		}

		edge := r.edgeByKey[key]
		if edge == nil {
			return minProbability
		}

		probability *= r.probability(
			edge, routeAmount(rt, i),
		)
	}

	return clampProbability(probability)
}

func (r *candidateRouter) reserve(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}

		r.reserved[key] += routeAmount(rt, i)
	}
}

func (r *candidateRouter) release(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}

		amt := routeAmount(rt, i)
		if amt >= r.reserved[key] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
	}
}

func addShardCandidate(candidates map[lnwire.MilliSatoshi]struct{},
	value, remaining lnwire.MilliSatoshi) {

	if value <= 0 {
		return
	}
	if value > remaining {
		value = remaining
	}

	minimum := minShardMsat
	if remaining < minimum {
		minimum = remaining
	}
	if value < minimum {
		return
	}

	candidates[value] = struct{}{}
}

func (r *candidateRouter) shardCandidates(
	remaining lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	candidates := make(map[lnwire.MilliSatoshi]struct{})
	addShardCandidate(candidates, remaining, remaining)
	addShardCandidate(candidates, r.initialShard, remaining)

	if r.lastFailed > 0 {
		addShardCandidate(
			candidates,
			lnwire.MilliSatoshi(
				float64(r.lastFailed)*shardStep,
			),
			remaining,
		)
		addShardCandidate(
			candidates,
			r.lastFailed/2,
			remaining,
		)
	}

	// A compact geometric ladder covers both large single-path attempts
	// and deliberately unequal MPP shards. Each amount is evaluated with
	// its own best path, making the choice a joint amount-route decision.
	value := remaining
	for i := 0; i < maxShardCandidates; i++ {
		addShardCandidate(candidates, value, remaining)

		next := lnwire.MilliSatoshi(
			float64(value) * shardStep,
		)
		if next >= value {
			next = value - 1
		}
		if next < minShardMsat {
			break
		}
		value = next
	}

	// Evidence-derived boundaries are particularly valuable after a
	// failure because they probe just below a channel's known cliff.
	for _, belief := range r.beliefs {
		if belief.upperBad != 0 {
			addShardCandidate(
				candidates,
				lnwire.MilliSatoshi(
					float64(belief.upperBad)*0.67,
				),
				remaining,
			)
		}
		if belief.lowerOK != 0 {
			addShardCandidate(
				candidates, belief.lowerOK, remaining,
			)
		}
		if belief.estimate != 0 {
			addShardCandidate(
				candidates,
				lnwire.MilliSatoshi(
					float64(belief.estimate)*0.82,
				),
				remaining,
			)
		}
	}

	values := make([]lnwire.MilliSatoshi, 0, len(candidates))
	for candidate := range candidates {
		values = append(values, candidate)
	}
	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})

	return values
}

func (r *candidateRouter) RequestRoute(
	amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if inFlightHtlcs >= r.spec.MaxParts &&
		r.spec.MaxParts != 0 {

		return nil, errors.New("maximum parts in flight")
	}

	if amt < r.lastRemain {
		r.lastFailed = 0
	}
	r.lastRemain = amt

	var (
		bestRoute *route.Route
		bestScore = -1.0
		lastErr   error
	)

	for _, shard := range r.shardCandidates(amt) {
		rt, err := r.findRoute(shard)
		if err != nil {
			lastErr = err
			continue
		}

		probability := r.routeProbability(rt)
		fee := float64(routeFee(rt))

		// Expected progress rewards large shards, while the exponent makes
		// reliability more important than raw size. A modest fee term
		// breaks ties without steering traffic toward fragile cheap paths.
		progress := float64(shard) *
			math.Pow(probability, 1.35)
		feeCost := fee * 25
		score := progress - feeCost

		if score > bestScore {
			bestScore = score
			bestRoute = rt
		}
	}

	if bestRoute == nil {
		if lastErr == nil {
			lastErr = errors.New("no route found")
		}

		return nil, lastErr
	}

	r.reserve(bestRoute)
	return bestRoute, nil
}

type codedFailure interface {
	Code() lnwire.FailCode
}

func (r *candidateRouter) saveBelief(
	key candidateEdgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordSuccess(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]

	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	// In a bimodal channel, passing a meaningful amount is evidence that
	// the directed balance lies in the high mode.
	estimate := amt
	remaining := edge.capacity - amt
	if remaining > 0 {
		estimate += remaining * 3 / 4
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(
	key candidateEdgeKey, amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]

	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}

	// A liquidity miss in a bimodal channel strongly favors the depleted
	// mode, while still permitting useful retries below the failed amount.
	estimate := amt * 30 / 100
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}
	if belief.lowerOK > belief.estimate {
		belief.estimate = belief.lowerOK
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) failureIndex(
	rt *route.Route, source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) addPenalty(
	key candidateEdgeKey, amt lnwire.MilliSatoshi,
	cost float64) {

	current := r.penalties[key]

	if current.threshold == 0 ||
		amt < current.threshold {

		current.threshold = amt
	}
	current.cost += cost
	if current.cost > riskCostMsat*4 {
		current.cost = riskCostMsat * 4
	}

	r.penalties[key] = current
}

func (r *candidateRouter) rewardEdge(
	key candidateEdgeKey) {

	penalty, ok := r.penalties[key]
	if !ok {
		return
	}

	penalty.cost *= 0.20
	if penalty.cost < 1 {
		delete(r.penalties, key)
		return
	}

	r.penalties[key] = penalty
}

func (r *candidateRouter) ReportAttempt(
	_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.release(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if !ok {
				continue
			}

			r.recordSuccess(key, routeAmount(rt, i))
			r.rewardEdge(key)
		}

		r.lastFailed = 0
		return nil
	}

	delivered := deliveredAmount(rt)
	if delivered > 0 {
		r.lastFailed = delivered
	}

	failIndex := r.failureIndex(
		rt, result.FailureSource,
	)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if ok {
				r.addPenalty(
					key, routeAmount(rt, i),
					riskCostMsat/3,
				)
			}
		}

		return nil
	}

	// Every edge before the failing node carried the HTLC successfully.
	for i := 0; i < failIndex; i++ {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}

		r.recordSuccess(key, routeAmount(rt, i))
		r.rewardEdge(key)
	}

	key, ok := r.routeEdge(rt, failIndex)
	if !ok {
		return nil
	}

	code := lnwire.FailCode(0)
	if failure, ok := result.Failure.(codedFailure); ok {
		code = failure.Code()
	}

	switch code {
	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		// These failures are deterministic for the advertised policy and
		// constructed route, so retrying this directed edge is wasteful.
		r.blocked[key] = true

	case lnwire.CodeTemporaryChannelFailure:
		r.recordFailure(
			key, routeAmount(rt, failIndex),
		)
		r.addPenalty(
			key, routeAmount(rt, failIndex),
			riskCostMsat,
		)

	default:
		// Unknown failures should encourage route exploration without
		// creating a permanent liquidity bound from ambiguous evidence.
		r.addPenalty(
			key, routeAmount(rt, failIndex),
			riskCostMsat/2,
		)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta    = uint32(40)
	riskCostMsat      = 300000.0
	minProbability    = 0.003
	maxProbability    = 0.995
	lowerRetryFactor  = 0.62
	minShardMsat      = lnwire.MilliSatoshi(10_000)
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return true
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
}

var sharedCandidateBeliefs = struct {
	sync.Mutex
	values map[candidateEdgeKey]liquidityBelief
}{
	values: make(map[candidateEdgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]liquidityBelief
	failedNow     map[candidateEdgeKey]lnwire.MilliSatoshi
	blocked       map[candidateEdgeKey]bool
	reserved      map[candidateEdgeKey]lnwire.MilliSatoshi
	used          map[candidateEdgeKey]lnwire.MilliSatoshi
	routePenalty  map[candidateEdgeKey]float64

	baseShard lnwire.MilliSatoshi
	lastFailed lnwire.MilliSatoshi
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeByKey:      make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]liquidityBelief),
		failedNow:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		blocked:        make(map[candidateEdgeKey]bool),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		used:           make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		routePenalty:   make(map[candidateEdgeKey]float64),
	}

	parts := spec.MaxParts
	if parts == 0 {
		parts = 1
	}

	switch {
	case spec.Amount < 25_000_000:
		parts = 1
	case spec.Amount < 100_000_000 && parts > 2:
		parts = 2
	case spec.Amount < 300_000_000 && parts > 4:
		parts = 4
	}

	r.baseShard = ceilDiv(
		spec.Amount, lnwire.MilliSatoshi(parts),
	)

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edgeByKey[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedCandidateBeliefs.Lock()
	for key, belief := range sharedCandidateBeliefs.values {
		if _, ok := r.edgeByKey[key]; ok {
			r.beliefs[key] = belief
		}
	}
	sharedCandidateBeliefs.Unlock()

	return r, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}

	return (a + b - 1) / b
}

func subtractFloor(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b >= a {
		return 0
	}

	return a - b
}

func clampProbability(p float64) float64 {
	if p < minProbability {
		return minProbability
	}
	if p > maxProbability {
		return maxProbability
	}

	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.51 * math.Exp(-x/0.024)
	highMode := 0.475 / (1 + math.Exp(15*(x-0.80)))

	return clampProbability(0.004 + lowMode + highMode)
}

func (r *candidateRouter) available(edge *candidateEdge) lnwire.MilliSatoshi {
	available := edge.capacity
	available = subtractFloor(available, r.used[edge.key])
	available = subtractFloor(available, r.reserved[edge.key])

	if edge.key.from == r.source {
		local := r.localBalances[edge.key.chanID]
		local = subtractFloor(local, r.used[edge.key])
		local = subtractFloor(local, r.reserved[edge.key])
		if local < available {
			available = local
		}
	}

	return available
}

func (r *candidateRouter) adjustedBelief(
	key candidateEdgeKey) liquidityBelief {

	belief := r.beliefs[key]
	consumed := r.used[key]

	belief.lowerOK = subtractFloor(belief.lowerOK, consumed)
	belief.estimate = subtractFloor(belief.estimate, consumed)

	if belief.upperBad != 0 {
		if consumed >= belief.upperBad {
			belief.upperBad = 1
		} else {
			belief.upperBad -= consumed
		}
	}

	return belief
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	available := r.available(edge)
	if amt > available {
		return minProbability
	}
	if edge.key.from == r.source {
		return maxProbability
	}

	if upper := r.failedNow[edge.key]; upper != 0 && amt >= upper {
		return minProbability
	}

	belief := r.adjustedBelief(edge.key)
	if belief.lowerOK != 0 && amt <= belief.lowerOK {
		return maxProbability
	}

	prior := bimodalPrior(amt, available)
	if belief.estimate == 0 && belief.upperBad == 0 {
		return prior
	}

	estimate := belief.estimate
	if estimate == 0 && belief.upperBad != 0 {
		estimate = belief.upperBad * 35 / 100
	}

	width := math.Max(float64(edge.capacity)*0.06, 1)
	point := 1 / (1 + math.Exp(
		(float64(amt)-float64(estimate))/width,
	))

	if belief.upperBad != 0 && amt >= belief.upperBad {
		point *= 0.08
	}

	return clampProbability(0.48*prior + 0.52*point)
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	arriving lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]

	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	dist := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)

		bestScore, ok := dist[item.node]
		if !ok || item.score > bestScore {
			continue
		}
		if item.arriving != required[item.node] {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.blocked[edge.key] {
				continue
			}

			amtOver := item.arriving
			if !edge.usable(amtOver) ||
				amtOver > r.available(edge) {

				continue
			}

			if upper := r.failedNow[edge.key]; upper != 0 &&
				amtOver >= upper {

				continue
			}

			sending := amtOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				sending += fee
			} else if sending > r.available(edge) {
				continue
			}

			probability := r.probability(edge, amtOver)
			risk := -math.Log(probability) * riskCostMsat

			utilization := float64(amtOver) /
				math.Max(float64(r.available(edge)), 1)
			capacityCost := utilization * utilization * 20_000

			score := item.score + float64(fee) + risk +
				capacityCost + r.routePenalty[edge.key] + 200

			oldScore, exists := dist[edge.key.from]
			if exists && score >= oldScore {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge

			heap.Push(pq, &dijkstraItem{
				node:     edge.key.from,
				score:    score,
				arriving: sending,
			})
		}
	}

	score, ok := dist[r.source]
	if !ok {
		return nil, 0, errors.New("no route found")
	}
	if _, ok := next[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, score, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to

		if len(path) > len(r.edgeByKey) {
			return nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta

		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	key := candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
	_, ok := r.edgeByKey[key]

	return key, ok
}

func routeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}

	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}

	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) reserve(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.reserved[key] += routeAmount(rt, i)
		}
	}
}

func (r *candidateRouter) release(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}

		amt := routeAmount(rt, i)
		if amt >= r.reserved[key] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
	}
}

func appendShardCandidate(values []lnwire.MilliSatoshi,
	value, floor, ceiling lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if value < floor {
		value = floor
	}
	if value > ceiling {
		value = ceiling
	}
	if value <= 0 {
		return values
	}

	for _, existing := range values {
		diff := existing - value
		if diff < 0 {
			diff = -diff
		}
		if diff <= 1 {
			return values
		}
	}

	return append(values, value)
}

func (r *candidateRouter) shardCandidates(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	floor := ceilDiv(
		amt, lnwire.MilliSatoshi(partsLeft)*2,
	)
	if floor < minShardMsat {
		floor = minShardMsat
	}
	if floor > amt {
		floor = amt
	}

	target := r.baseShard
	if target <= 0 || target > amt {
		target = ceilDiv(amt, lnwire.MilliSatoshi(partsLeft))
	}

	var values []lnwire.MilliSatoshi
	values = appendShardCandidate(values, target, floor, amt)

	if r.lastFailed != 0 {
		retry := lnwire.MilliSatoshi(
			float64(r.lastFailed) * lowerRetryFactor,
		)
		values = appendShardCandidate(values, retry, floor, amt)
	}

	equal := ceilDiv(amt, lnwire.MilliSatoshi(partsLeft))
	values = appendShardCandidate(values, equal, floor, amt)

	for _, factor := range []float64{0.82, 0.68, 0.54} {
		next := lnwire.MilliSatoshi(float64(target) * factor)
		values = appendShardCandidate(values, next, floor, amt)
	}

	values = appendShardCandidate(values, floor, floor, amt)

	return values
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum parts in flight")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	candidates := r.shardCandidates(amt, partsLeft)

	var (
		bestRoute *route.Route
		bestScore = math.Inf(1)
		lastErr   error
	)

	floor := candidates[len(candidates)-1]
	for _, shard := range candidates {
		rt, score, err := r.findRoute(shard)
		if err != nil {
			lastErr = err
			continue
		}

		sizeCredit := 35_000 * math.Log1p(
			float64(shard) / math.Max(float64(floor), 1),
		)
		adjusted := score - sizeCredit

		if adjusted < bestScore {
			bestScore = adjusted
			bestRoute = rt
		}
	}

	if bestRoute == nil {
		if lastErr == nil {
			lastErr = errors.New("no route found")
		}

		return nil, lastErr
	}

	r.reserve(bestRoute)
	return bestRoute, nil
}

type codedFailure interface {
	Code() lnwire.FailCode
}

func (r *candidateRouter) saveBelief(key candidateEdgeKey,
	belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedCandidateBeliefs.Lock()
	sharedCandidateBeliefs.values[key] = belief
	sharedCandidateBeliefs.Unlock()
}

func (r *candidateRouter) recordSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	estimate := amt
	remaining := subtractFloor(edge.capacity, amt)
	estimate += remaining * 4 / 5

	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) consumeBelief(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	belief.lowerOK = subtractFloor(belief.lowerOK, amt)
	belief.estimate = subtractFloor(belief.estimate, amt)

	if belief.upperBad != 0 {
		if amt >= belief.upperBad {
			belief.upperBad = 1
		} else {
			belief.upperBad -= amt
		}
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}

	estimate := amt * 30 / 100
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}
	if belief.lowerOK > belief.estimate {
		belief.estimate = belief.lowerOK
	}

	r.failedNow[key] = amt
	r.saveBelief(key, belief)
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.release(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if !ok {
				continue
			}

			amt := routeAmount(rt, i)
			r.recordSuccess(key, amt)
			r.routePenalty[key] *= 0.15
		}

		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if !ok {
				continue
			}

			amt := routeAmount(rt, i)
			r.consumeBelief(key, amt)
			r.used[key] += amt
		}

		r.lastFailed = 0
		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if ok {
				r.routePenalty[key] += riskCostMsat * 0.35
			}
		}

		r.lastFailed = deliveredAmount(rt)
		if r.lastFailed > 0 {
			r.baseShard = lnwire.MilliSatoshi(
				float64(r.lastFailed) * lowerRetryFactor,
			)
		}

		return nil
	}

	for i := 0; i < failIndex; i++ {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.recordSuccess(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.5
		}
	}

	key, ok := r.routeEdge(rt, failIndex)
	if !ok {
		return nil
	}

	code := lnwire.FailCode(0)
	if failure, ok := result.Failure.(codedFailure); ok {
		code = failure.Code()
	}

	switch code {
	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.blocked[key] = true

	default:
		failedAmt := routeAmount(rt, failIndex)
		r.recordFailure(key, failedAmt)
		r.routePenalty[key] += riskCostMsat

		r.lastFailed = deliveredAmount(rt)
		if r.lastFailed > 0 {
			retry := lnwire.MilliSatoshi(
				float64(r.lastFailed) * lowerRetryFactor,
			)
			if retry > 0 {
				r.baseShard = retry
			}
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta   = uint32(40)
	riskCostMsat     = 260000.0
	minProbability   = 0.003
	maxProbability   = 0.995
	lowerRetryFactor = 0.64
	minShardMsat     = lnwire.MilliSatoshi(10_000)
	maxPlanCandidates = 18
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return true
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[candidateEdgeKey]liquidityBelief
}{
	values: make(map[candidateEdgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]liquidityBelief
	blocked       map[candidateEdgeKey]bool
	reserved      map[candidateEdgeKey]lnwire.MilliSatoshi
	routePenalty  map[candidateEdgeKey]float64

	baseShard           lnwire.MilliSatoshi
	lastRemaining       lnwire.MilliSatoshi
	consecutiveFailures uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeByKey:     make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		beliefs:       make(map[candidateEdgeKey]liquidityBelief),
		blocked:       make(map[candidateEdgeKey]bool),
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		routePenalty:  make(map[candidateEdgeKey]float64),
		lastRemaining: spec.Amount,
	}

	parts := spec.MaxParts
	if parts == 0 {
		parts = 1
	}
	r.baseShard = ceilDiv(spec.Amount, lnwire.MilliSatoshi(parts))

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edgeByKey[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, belief := range sharedBeliefs.values {
		if _, ok := r.edgeByKey[key]; ok {
			r.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}
	return (a + b - 1) / b
}

func clampProbability(p float64) float64 {
	if p < minProbability {
		return minProbability
	}
	if p > maxProbability {
		return maxProbability
	}
	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.51 * math.Exp(-x/0.026)
	highMode := 0.475 / (1 + math.Exp(15*(x-0.79)))

	return clampProbability(0.005 + lowMode + highMode)
}

func (r *candidateRouter) available(edge *candidateEdge) lnwire.MilliSatoshi {
	available := edge.capacity
	if edge.key.from == r.source {
		available = r.localBalances[edge.key.chanID]
	}

	reserved := r.reserved[edge.key]
	if reserved >= available {
		return 0
	}
	return available - reserved
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if amt > r.available(edge) {
		return minProbability
	}
	if edge.key.from == r.source {
		return maxProbability
	}

	belief := r.beliefs[edge.key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		return minProbability
	}
	if belief.lowerOK != 0 && amt <= belief.lowerOK {
		return maxProbability
	}

	prior := bimodalPrior(amt, edge.capacity)
	if belief.estimate == 0 {
		return prior
	}

	width := math.Max(float64(edge.capacity)*0.07, 1)
	point := 1 / (1 + math.Exp(
		(float64(amt)-float64(belief.estimate))/width,
	))

	return clampProbability(0.52*prior + 0.48*point)
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	arriving lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}

	dist := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		bestScore, ok := dist[item.node]
		if !ok || item.score > bestScore {
			continue
		}
		if item.arriving != required[item.node] {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.blocked[edge.key] {
				continue
			}

			amtOver := item.arriving
			if !edge.usable(amtOver) || amtOver > r.available(edge) {
				continue
			}

			probability := r.probability(edge, amtOver)
			belief := r.beliefs[edge.key]
			if probability <= minProbability &&
				belief.upperBad != 0 &&
				amtOver >= belief.upperBad {

				continue
			}

			sending := amtOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				sending += fee
			}

			if sending > r.available(edge) {
				continue
			}

			risk := -math.Log(probability) * riskCostMsat
			score := item.score + float64(fee) + risk +
				r.routePenalty[edge.key] + 200

			oldScore, exists := dist[edge.key.from]
			if exists && score >= oldScore {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:     edge.key.from,
				score:    score,
				arriving: sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edgeByKey) {
			return nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta
		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	key := candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
	_, ok := r.edgeByKey[key]

	return key, ok
}

func routeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) reserve(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.reserved[key] += routeAmount(rt, i)
		}
	}
}

func (r *candidateRouter) release(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}

		amt := routeAmount(rt, i)
		if amt >= r.reserved[key] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
	}
}

func (r *candidateRouter) routeProbability(rt *route.Route) float64 {
	probability := 1.0
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			return minProbability
		}

		edge := r.edgeByKey[key]
		probability *= r.probability(edge, routeAmount(rt, i))
	}

	return clampProbability(probability)
}

func addCandidate(values map[lnwire.MilliSatoshi]struct{},
	value, floor, ceiling lnwire.MilliSatoshi) {

	if value < floor || value > ceiling || value <= 0 {
		return
	}
	values[value] = struct{}{}
}

func (r *candidateRouter) shardCandidates(amt,
	equal lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	floor := equal / 3
	if floor < minShardMsat {
		floor = minShardMsat
	}
	if floor > amt {
		floor = amt
	}

	values := make(map[lnwire.MilliSatoshi]struct{})
	addCandidate(values, amt, floor, amt)
	addCandidate(values, equal, floor, amt)
	addCandidate(values, r.baseShard, floor, amt)
	addCandidate(values, equal*2, floor, amt)
	addCandidate(values, equal*3/2, floor, amt)
	addCandidate(values, equal*4/3, floor, amt)
	addCandidate(values, equal*5/4, floor, amt)
	addCandidate(values, equal*3/4, floor, amt)
	addCandidate(values, equal*2/3, floor, amt)
	addCandidate(values, equal/2, floor, amt)
	addCandidate(values, amt*4/5, floor, amt)
	addCandidate(values, amt*2/3, floor, amt)
	addCandidate(values, amt/2, floor, amt)
	addCandidate(values, amt/3, floor, amt)
	addCandidate(values, floor, floor, amt)

	var bestOK lnwire.MilliSatoshi
	var bestRetry lnwire.MilliSatoshi
	for key, belief := range r.beliefs {
		if r.blocked[key] {
			continue
		}

		if belief.lowerOK >= floor && belief.lowerOK <= amt &&
			belief.lowerOK > bestOK {

			bestOK = belief.lowerOK
		}

		if belief.upperBad != 0 {
			retry := belief.upperBad * 62 / 100
			if retry >= floor && retry <= amt && retry > bestRetry {
				bestRetry = retry
			}
		}
	}

	addCandidate(values, bestOK, floor, amt)
	addCandidate(values, bestRetry, floor, amt)

	candidates := make([]lnwire.MilliSatoshi, 0, len(values))
	for value := range values {
		candidates = append(candidates, value)
	}
	sort.Slice(candidates, func(i, j int) bool {
		return candidates[i] > candidates[j]
	})

	if len(candidates) <= maxPlanCandidates {
		return candidates
	}

	trimmed := append(
		[]lnwire.MilliSatoshi(nil),
		candidates[:maxPlanCandidates-2]...,
	)
	trimmed = append(
		trimmed,
		candidates[len(candidates)-2],
		candidates[len(candidates)-1],
	)

	return trimmed
}

func (r *candidateRouter) planRoute(amt,
	equal lnwire.MilliSatoshi) (*route.Route, error) {

	candidates := r.shardCandidates(amt, equal)

	var bestRoute *route.Route
	bestUtility := math.Inf(-1)
	var lastErr error

	for _, shard := range candidates {
		rt, err := r.findRoute(shard)
		if err != nil {
			lastErr = err
			continue
		}

		probability := r.routeProbability(rt)
		fees := rt.TotalAmount - deliveredAmount(rt)
		progress := math.Log(
			math.Max(float64(shard)/float64(equal), 0.05),
		)

		utility := math.Log(probability) + 0.48*progress -
			float64(fees)/750000.0

		if shard < equal {
			utility += 0.30 * progress
		}
		if probability >= 0.70 {
			utility += 0.18
		}
		if shard == amt && probability >= 0.45 {
			utility += 0.20
		}

		if bestRoute == nil || utility > bestUtility {
			bestRoute = rt
			bestUtility = utility
		}
	}

	if bestRoute != nil {
		return bestRoute, nil
	}
	if lastErr == nil {
		lastErr = errors.New("no route found")
	}

	return nil, lastErr
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum parts in flight")
	}

	if amt < r.lastRemaining {
		r.consecutiveFailures = 0
	}
	r.lastRemaining = amt

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	if partsLeft == 0 {
		return nil, errors.New("maximum parts in flight")
	}

	equal := ceilDiv(amt, lnwire.MilliSatoshi(partsLeft))
	if partsLeft == 1 {
		equal = amt
	}

	rt, err := r.planRoute(amt, equal)
	if err != nil {
		return nil, err
	}

	r.reserve(rt)
	return rt, nil
}

type codedFailure interface {
	Code() lnwire.FailCode
}

func (r *candidateRouter) saveBelief(key candidateEdgeKey,
	belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	estimate := amt + (edge.capacity-amt)*4/5
	if estimate > edge.capacity {
		estimate = edge.capacity
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}

	estimate := amt * 30 / 100
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}
	if belief.estimate < belief.lowerOK {
		belief.estimate = belief.lowerOK
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.release(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if !ok {
				continue
			}

			r.recordSuccess(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.20
		}

		delivered := deliveredAmount(rt)
		if delivered > r.baseShard {
			r.baseShard = delivered
		}
		r.consecutiveFailures = 0

		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if ok {
				r.routePenalty[key] += riskCostMsat / 2
			}
		}
		r.consecutiveFailures++
		return nil
	}

	for i := 0; i < failIndex; i++ {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.recordSuccess(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.70
		}
	}

	key, ok := r.routeEdge(rt, failIndex)
	if !ok {
		return nil
	}

	code := lnwire.FailCode(0)
	if failure, ok := result.Failure.(codedFailure); ok {
		code = failure.Code()
	}

	switch code {
	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.blocked[key] = true

	default:
		failedAmount := routeAmount(rt, failIndex)
		r.recordFailure(key, failedAmount)
		r.routePenalty[key] += riskCostMsat

		retry := deliveredAmount(rt) * 62 / 100
		if retry >= minShardMsat &&
			(r.baseShard == 0 || retry < r.baseShard) {

			r.baseShard = retry
		}
	}

	r.consecutiveFailures++
	if r.consecutiveFailures >= 3 {
		for edgeKey, penalty := range r.routePenalty {
			if edgeKey == key {
				continue
			}
			r.routePenalty[edgeKey] = penalty * 0.85
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta  = 40
	maxRouteAttempts = 72
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved       map[edgeKey]lnwire.MilliSatoshi
	edgeFailures   map[edgeKey]uint32
	policyFailures map[edgeKey]bool
	routeFailures  map[string]uint32
	lastFailedAmt  lnwire.MilliSatoshi
	attempts       uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:          source,
		spec:            spec,
		incomingEdges:   make(map[route.Vertex][]*candidateEdge),
		edges:           make(map[edgeKey]*candidateEdge),
		localBalances:   make(map[uint64]lnwire.MilliSatoshi),
		beliefs:         make(map[edgeKey]liquidityBelief),
		reserved:        make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:    make(map[edgeKey]uint32),
		policyFailures:  make(map[edgeKey]bool),
		routeFailures:   make(map[string]uint32),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-18*x)
	highMode := 0.495 / (1 + math.Exp(22*(x-0.88)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}
		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := math.Max(float64(edge.capacity)*0.09, 1)
	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))

	confidence := math.Min(0.80, 0.20*float64(belief.samples))
	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	utility     float64
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
	signature   string
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{r.spec.Target: 0}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, ok := score[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		requiredAtNode := deliver
		if item.node != r.spec.Target {
			pathEdge := next[item.node]
			if pathEdge == nil {
				continue
			}

			requiredAtNode = requiredAmount(
				item.node, r.spec.Target, deliver, next,
			)
			if requiredAtNode <= 0 {
				continue
			}
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.policyFailures[edge.key] ||
				!edge.usable(requiredAtNode) {

				continue
			}

			total := requiredAtNode + r.reserved[edge.key]
			if total > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				total > r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(edge, requiredAtNode)
			edgeFee := edge.fee(requiredAtNode)
			sending := requiredAtNode + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = requiredAtNode
			}

			reservationRatio := float64(r.reserved[edge.key]) /
				math.Max(float64(edge.capacity), 1)
			failurePenalty := 0.55 *
				math.Min(float64(r.edgeFailures[edge.key]), 6)

			step := -math.Log(probability) +
				float64(edgeFee)/2_500_000 +
				0.012 +
				failurePenalty +
				0.70*reservationRatio

			candidate := item.score + step
			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
			})

			_ = sending
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(r.edges[key], amounts[i])
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
		signature:   routeSignature(keys, deliver),
	}, nil
}

func requiredAmount(node, target route.Vertex,
	deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) lnwire.MilliSatoshi {

	var path []*candidateEdge
	for node != target {
		edge := next[node]
		if edge == nil {
			return 0
		}
		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(next)+1 {
			return 0
		}
	}

	amt := deliver
	for i := len(path) - 1; i > 0; i-- {
		amt += path[i].fee(amt)
	}

	return amt
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	last := len(path) - 1
	amounts[last] = deliver
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func routeSignature(keys []edgeKey,
	deliver lnwire.MilliSatoshi) string {

	var builder strings.Builder
	for _, key := range keys {
		builder.WriteString(strconv.FormatUint(key.chanID, 10))
		builder.WriteByte('/')
	}
	builder.WriteByte('@')
	builder.WriteString(strconv.FormatInt(int64(deliver), 10))

	return builder.String()
}

func addCandidate(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	partCount := lnwire.MilliSatoshi(partsLeft)
	minimum := (amt + partCount - 1) / partCount
	if minimum < 1_000 {
		minimum = 1_000
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 20)

	addCandidate(&values, seen, minimum, minimum, amt)
	addCandidate(&values, seen, minimum*5/4, minimum, amt)
	addCandidate(&values, seen, minimum*3/2, minimum, amt)
	addCandidate(&values, seen, minimum*2, minimum, amt)
	addCandidate(&values, seen, amt/2, minimum, amt)
	addCandidate(&values, seen, amt*2/3, minimum, amt)
	addCandidate(&values, seen, amt*3/4, minimum, amt)
	addCandidate(&values, seen, amt, minimum, amt)

	if r.lastFailedAmt > 0 {
		addCandidate(
			&values, seen, r.lastFailedAmt/2, minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*3/5, minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*2/3, minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*3/4, minimum, amt,
		)
	}

	var bounds []lnwire.MilliSatoshi
	for key, belief := range r.beliefs {
		if r.policyFailures[key] || belief.upperFail <= 1 {
			continue
		}

		for _, factor := range []lnwire.MilliSatoshi{1, 2, 3} {
			bound := belief.upperFail * factor / 4
			if bound >= minimum && bound <= amt {
				bounds = append(bounds, bound)
			}
		}
	}

	sort.Slice(bounds, func(i, j int) bool {
		return bounds[i] > bounds[j]
	})
	if len(bounds) > 8 {
		bounds = bounds[:8]
	}
	for _, bound := range bounds {
		addCandidate(&values, seen, bound, minimum, amt)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] < values[j]
	})

	return values
}

func ceilParts(total, shard lnwire.MilliSatoshi) uint32 {
	if shard <= 0 {
		return math.MaxUint32
	}

	return uint32((total + shard - 1) / shard)
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= maxRouteAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	var best *routeChoice

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		partsNeeded := ceilParts(amt, shard)
		if partsNeeded > partsLeft {
			continue
		}

		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		risk := -math.Log(choice.probability)
		repeatPenalty := 1.35 *
			float64(r.routeFailures[choice.signature])
		partPenalty := 0.075 * float64(partsNeeded-1)
		feePenalty := float64(choice.fee) / 2_500_000

		// Prefer reliable, deliberately sized shards. The low part penalty
		// lets reliability dominate while still avoiding needless splits.
		choice.utility = risk + repeatPenalty +
			partPenalty + feePenalty

		if best == nil || choice.utility < best.utility {
			best = choice
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	for i, key := range best.keys {
		r.reserved[key] += best.amounts[i]
	}
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnForwarded(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.estimate < amt {
		belief.estimate = amt
	}

	optimistic := edge.capacity * 4 / 5
	if belief.estimate < optimistic {
		belief.estimate = (belief.estimate + optimistic) / 2
	}
	if belief.upperFail > 0 && belief.upperFail <= belief.lowerOK {
		belief.upperFail = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	depletedEstimate := amt / 4
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = depletedEstimate
	} else {
		belief.estimate =
			(3*belief.estimate + depletedEstimate) / 4
	}

	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}
	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}
	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]

	// A successful transfer is strong evidence for the liquid mode. Before
	// applying the transfer, infer that a substantial fraction of capacity
	// was available in this direction.
	inferredBefore := maxMSat(belief.lowerOK, amt)
	liquidMode := edge.capacity * 4 / 5
	if inferredBefore < liquidMode {
		inferredBefore = liquidMode
	}

	estimateBefore := maxMSat(belief.estimate, inferredBefore)
	belief.lowerOK = subtractFloor(inferredBefore, amt, 0)
	belief.estimate = subtractFloor(estimateBefore, amt, 0)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}
	if belief.upperFail > 0 &&
		belief.lowerOK >= belief.upperFail {

		belief.upperFail = 0
	}

	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}
	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func failureEdgeIndex(rt *route.Route,
	failureSource route.Vertex) int {

	if failureSource == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes != failureSource {
			continue
		}

		// A node reports failure for its outgoing channel. The final
		// recipient has no outgoing route edge.
		return i + 1
	}

	return -1
}

func (r *candidateRouter) releaseReservation(keys []edgeKey,
	amounts []lnwire.MilliSatoshi) {

	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("attempt route is empty")
	}

	keys, amounts := routeEdgeData(rt)
	r.releaseReservation(keys, amounts)

	signature := routeSignature(
		keys, rt.Hops[len(rt.Hops)-1].AmtToForward,
	)

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}

		delete(r.routeFailures, signature)
		r.lastFailedAmt = 0
		return nil
	}

	r.routeFailures[signature]++
	r.lastFailedAmt =
		rt.Hops[len(rt.Hops)-1].AmtToForward

	failIndex := failureEdgeIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(keys) {
		return nil
	}

	// A failure returned by a downstream node proves that every preceding
	// channel carried the HTLC. Record that evidence without shifting
	// liquidity because the failed HTLC is rolled back.
	for i := 0; i < failIndex; i++ {
		r.learnForwarded(keys[i], amounts[i])
		if r.edgeFailures[keys[i]] > 0 {
			r.edgeFailures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.edgeFailures[key]++
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.edgeFailures[key] += 2
		r.policyFailures[key] = true

	default:
		r.edgeFailures[key]++
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi
	baseFee  lnwire.MilliSatoshi
	feeRate  lnwire.MilliSatoshi
	delta    uint16
	minHTLC  lnwire.MilliSatoshi
	maxHTLC  lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feeRate/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incoming map[route.Vertex][]*candidateEdge
	edges    map[edgeKey]*candidateEdge
	local    map[uint64]lnwire.MilliSatoshi
	beliefs  map[edgeKey]liquidityBelief

	reserved map[edgeKey]lnwire.MilliSatoshi
	failures map[edgeKey]uint32
	broken   map[edgeKey]bool

	lastFailed lnwire.MilliSatoshi
	attempts   uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:   source,
		spec:     spec,
		incoming: make(map[route.Vertex][]*candidateEdge),
		edges:    make(map[edgeKey]*candidateEdge),
		local:    make(map[uint64]lnwire.MilliSatoshi),
		beliefs:  make(map[edgeKey]liquidityBelief),
		reserved: make(map[edgeKey]lnwire.MilliSatoshi),
		failures: make(map[edgeKey]uint32),
		broken:   make(map[edgeKey]bool),
	}
	for id, balance := range localBalances {
		r.local[id] = balance
	}

	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	ctx := context.Background()

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: policy.FeeBaseMSat,
					feeRate: policy.FeeProportionalMillionths,
					delta:   policy.TimeLockDelta,
					minHTLC: policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incoming[node] = append(r.incoming[node], edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	low := 0.50 * math.Exp(-18*x)
	high := 0.495 / (1 + math.Exp(22*(x-0.88)))
	return clampProbability(low + high)
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}
	if edge.key.from == r.source {
		if total <= r.local[edge.key.chanID] {
			return 0.999
		}
		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := math.Max(1, float64(edge.capacity)*0.08)
	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))
	confidence := math.Min(0.82, 0.24*float64(belief.samples))

	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

type pathItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type pathQueue []*pathItem

func (q pathQueue) Len() int           { return len(q) }
func (q pathQueue) Less(i, j int) bool { return q[i].score < q[j].score }
func (q pathQueue) Swap(i, j int)      { q[i], q[j] = q[j], q[i] }

func (q *pathQueue) Push(value any) {
	*q = append(*q, value.(*pathItem))
}

func (q *pathQueue) Pop() any {
	old := *q
	item := old[len(old)-1]
	*q = old[:len(old)-1]
	return item
}

type routeChoice struct {
	rt          *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	utility     float64
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 || r.source == r.spec.Target {
		return nil, errors.New("invalid route request")
	}

	scores := map[route.Vertex]float64{r.spec.Target: 0}
	next := make(map[route.Vertex]*candidateEdge)
	queue := &pathQueue{}
	heap.Push(queue, &pathItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for queue.Len() > 0 {
		item := heap.Pop(queue).(*pathItem)
		best, ok := scores[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incoming[item.node] {
			if r.broken[edge.key] || !edge.usable(item.amt) {
				continue
			}

			total := item.amt + r.reserved[edge.key]
			if total > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				total > r.local[edge.key.chanID] {

				continue
			}

			probability := r.probability(edge, item.amt)
			edgeFee := edge.fee(item.amt)
			sending := item.amt + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = item.amt
			}

			step := -math.Log(probability) +
				float64(edgeFee)/2_500_000 +
				0.012 +
				0.42*float64(r.failures[edge.key])
			candidate := item.score + step

			old, exists := scores[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			scores[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(queue, &pathItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.probability(r.edges[key], amounts[i])
	}

	return &routeChoice{
		rt:          rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, errors.New("incomplete route")
		}
		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New("route cycle")
		}
	}
	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.delta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	if minimum < 1_000 {
		minimum = 1_000
	}
	if minimum > amt {
		minimum = amt
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 18)

	for _, value := range []lnwire.MilliSatoshi{
		amt,
		amt * 4 / 5,
		amt * 2 / 3,
		amt / 2,
		minimum * 2,
		minimum * 3 / 2,
		minimum,
	} {
		addAmount(&values, seen, value, minimum, amt)
	}

	if r.lastFailed > 0 {
		for _, value := range []lnwire.MilliSatoshi{
			r.lastFailed * 2 / 3,
			r.lastFailed / 2,
			r.lastFailed * 2 / 5,
			r.lastFailed / 3,
			r.lastFailed / 4,
		} {
			addAmount(&values, seen, value, minimum, amt)
		}
	}

	var bounds []lnwire.MilliSatoshi
	for key, belief := range r.beliefs {
		if r.broken[key] {
			continue
		}
		if belief.lowerOK >= minimum && belief.lowerOK <= amt {
			bounds = append(bounds, belief.lowerOK)
		}
		if belief.upperFail > 1 {
			bounds = append(
				bounds,
				belief.upperFail*2/3,
				belief.upperFail/2,
				belief.upperFail/3,
			)
		}
	}

	sort.Slice(bounds, func(i, j int) bool {
		return bounds[i] > bounds[j]
	})
	if len(bounds) > 7 {
		bounds = bounds[:7]
	}
	for _, value := range bounds {
		addAmount(&values, seen, value, minimum, amt)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})
	return values
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= 48 {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	var best *routeChoice

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		partsNeeded := math.Ceil(
			float64(amt) / float64(shard),
		)
		if partsNeeded > float64(partsLeft) {
			continue
		}

		choice.utility =
			-math.Log(choice.probability)*partsNeeded +
				0.11*(partsNeeded-1) +
				float64(choice.fee)*partsNeeded/2_500_000 +
				0.18*math.Log(float64(shard)/float64(amt))

		if best == nil || choice.utility < best.utility {
			best = choice
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	for i, key := range best.keys {
		r.reserved[key] += best.amounts[i]
	}
	r.attempts++

	return best.rt, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief
	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	depleted := amt / 4
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = depleted
	} else {
		belief.estimate = (3*belief.estimate + depleted) / 4
	}
	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnProbeSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	if key.from == r.source || r.edges[key] == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.estimate < amt {
		belief.estimate = amt
	}
	if belief.upperFail > 0 && belief.upperFail <= amt {
		belief.upperFail = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}
	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}
	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	estimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10
	if estimate < optimistic {
		estimate = (estimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(estimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}
	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}
	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}
	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}
	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid attempted route")
	}

	keys, amounts := routeEdgeData(rt)
	for i, key := range keys {
		if r.reserved[key] <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amounts[i]
		}
	}

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])
			if key.from == r.source {
				balance := r.local[key.chanID]
				if amounts[i] >= balance {
					r.local[key.chanID] = 0
				} else {
					r.local[key.chanID] =
						balance - amounts[i]
				}
			}
			if r.failures[key] > 0 {
				r.failures[key]--
			}
		}

		r.lastFailed = 0
		return nil
	}

	r.lastFailed = rt.Hops[len(rt.Hops)-1].AmtToForward

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIndex = i + 1
				break
			}
		}
	}

	if failIndex < 0 || failIndex >= len(keys) {
		for _, key := range keys {
			if r.failures[key] < 3 {
				r.failures[key]++
			}
		}
		return nil
	}

	for i := 0; i < failIndex; i++ {
		r.learnProbeSuccess(keys[i], amounts[i])
		if r.failures[keys[i]] > 0 {
			r.failures[keys[i]]--
		}
	}

	key := keys[failIndex]
	if r.failures[key] < 12 {
		r.failures[key] += 2
	}

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, amounts[failIndex])

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.broken[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"strconv"
	"strings"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	maxAttempts    = 72
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved     map[edgeKey]lnwire.MilliSatoshi
	edgeFailures map[edgeKey]uint32
	broken       map[edgeKey]bool
	tried        map[string]bool

	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:  make(map[edgeKey]uint32),
		broken:        make(map[edgeKey]bool),
		tried:         make(map[string]bool),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, exists := r.edges[key]; exists {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, exists := sharedBeliefs.values[key]
		if !exists {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(probability float64) float64 {
	switch {
	case probability < 0.005:
		return 0.005
	case probability > 0.985:
		return 0.985
	default:
		return probability
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	ratio := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-18*ratio)
	highMode := 0.495 / (1 + math.Exp(22*(ratio-0.88)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}

		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := float64(edge.capacity) * 0.10
	if scale < 1 {
		scale = 1
	}

	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))
	confidence := math.Min(0.80, 0.20*float64(belief.samples))

	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	utility     float64
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
}

func (r *candidateRouter) findRoute(deliver lnwire.MilliSatoshi,
	diversity map[edgeKey]float64) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{r.spec.Target: 0}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, exists := score[item.node]
		if !exists || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.broken[edge.key] || !edge.usable(item.amt) {
				continue
			}

			total := item.amt + r.reserved[edge.key]
			if total > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				total > r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(edge, item.amt)
			edgeFee := edge.fee(item.amt)
			sending := item.amt + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = item.amt
			}

			failurePenalty := math.Min(
				0.75,
				0.12*float64(r.edgeFailures[edge.key]),
			)
			step := -math.Log(probability) +
				float64(edgeFee)/2_500_000 +
				0.012 +
				failurePenalty +
				diversity[edge.key]

			candidate := item.score + step
			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, exists := next[r.source]; !exists {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(r.edges[key], amounts[i])
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, exists := next[node]
		if !exists {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addCandidate(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) baseCandidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) ([]lnwire.MilliSatoshi,
	lnwire.MilliSatoshi) {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}, amt
	}

	minimum := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	if minimum < 1_000 {
		minimum = 1_000
	}
	if minimum > amt {
		minimum = amt
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 24)

	addCandidate(&values, seen, amt, minimum, amt)
	addCandidate(&values, seen, amt*7/8, minimum, amt)
	addCandidate(&values, seen, amt*3/4, minimum, amt)
	addCandidate(&values, seen, amt*2/3, minimum, amt)
	addCandidate(&values, seen, amt*3/5, minimum, amt)
	addCandidate(&values, seen, amt/2, minimum, amt)
	addCandidate(&values, seen, amt*2/5, minimum, amt)
	addCandidate(&values, seen, amt/3, minimum, amt)
	addCandidate(&values, seen, minimum*2, minimum, amt)
	addCandidate(&values, seen, minimum*3/2, minimum, amt)
	addCandidate(&values, seen, minimum*5/4, minimum, amt)
	addCandidate(&values, seen, minimum, minimum, amt)

	if r.lastFailedAmt > 0 {
		addCandidate(
			&values, seen, r.lastFailedAmt*4/5,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*2/3,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt/2,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt/3,
			minimum, amt,
		)
	}

	var bounds []lnwire.MilliSatoshi
	for key, belief := range r.beliefs {
		if r.broken[key] {
			continue
		}

		switch {
		case belief.upperFail > 1:
			bounds = append(
				bounds,
				belief.upperFail*4/5,
				belief.upperFail*2/3,
			)

		case belief.lowerOK > 0:
			bounds = append(bounds, belief.lowerOK)
		}
	}

	sort.Slice(bounds, func(i, j int) bool {
		return bounds[i] > bounds[j]
	})
	if len(bounds) > 8 {
		bounds = bounds[:8]
	}

	for _, bound := range bounds {
		addCandidate(
			&values, seen, bound, minimum, amt,
		)
	}

	return values, minimum
}

func (r *candidateRouter) edgePlanningLimit(
	edge *candidateEdge) lnwire.MilliSatoshi {

	reserved := r.reserved[edge.key]
	var limit lnwire.MilliSatoshi

	if edge.key.from == r.source {
		limit = r.localBalances[edge.key.chanID]
	} else {
		belief := r.beliefs[edge.key]

		switch {
		case belief.upperFail > 1:
			limit = belief.upperFail - 1

		case belief.lowerOK > 0:
			limit = maxMSat(
				belief.lowerOK,
				belief.estimate,
			)

		case belief.samples > 0 && belief.estimate > 0:
			limit = belief.estimate

		default:
			limit = edge.capacity * 4 / 5
		}
	}

	if limit > edge.capacity {
		limit = edge.capacity
	}
	if edge.maxHTLC > 0 && limit > edge.maxHTLC {
		limit = edge.maxHTLC
	}
	if reserved >= limit {
		return 0
	}

	return limit - reserved
}

func (r *candidateRouter) pathBudget(
	choice *routeChoice) lnwire.MilliSatoshi {

	if choice == nil || choice.deliver <= 0 {
		return 0
	}

	budget := float64(math.MaxInt64)
	proven := true

	for i, key := range choice.keys {
		edge := r.edges[key]
		if edge == nil || choice.amounts[i] <= 0 {
			return 0
		}

		limit := r.edgePlanningLimit(edge)
		if limit <= 0 {
			return 0
		}

		belief := r.beliefs[key]
		if key.from != r.source &&
			(belief.lowerOK == 0 ||
				limit > belief.lowerOK) {

			proven = false
		}

		deliverLimit := float64(choice.deliver) *
			float64(limit) / float64(choice.amounts[i])
		if deliverLimit < budget {
			budget = deliverLimit
		}
	}

	if math.IsInf(budget, 0) || budget <= 0 {
		return 0
	}

	// Unknown corridors are sized below their inferred high-liquidity
	// mode. Proven corridors can be filled more aggressively.
	if proven {
		budget *= 0.97
	} else {
		budget *= 0.82
	}

	if budget > float64(math.MaxInt64) {
		budget = float64(math.MaxInt64)
	}

	return lnwire.MilliSatoshi(budget)
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	values, minimum := r.baseCandidateAmounts(amt, partsLeft)
	seen := make(map[lnwire.MilliSatoshi]bool, len(values)+12)
	for _, value := range values {
		seen[value] = true
	}

	// Probe the smallest feasible shard to discover several distinct
	// corridors, then turn each corridor's inferred bottleneck into an
	// unequal shard candidate.
	diversity := make(map[edgeKey]float64)
	for i := 0; i < 6; i++ {
		choice, err := r.findRoute(minimum, diversity)
		if err != nil {
			break
		}

		budget := r.pathBudget(choice)
		addCandidate(
			&values, seen, budget, minimum, amt,
		)
		addCandidate(
			&values, seen, budget*4/5, minimum, amt,
		)

		for _, key := range choice.keys {
			diversity[key] += 0.85
		}
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})

	if len(values) > 24 {
		values = values[:24]
		if !seen[minimum] {
			values[len(values)-1] = minimum
		}
	}

	return values
}

func routeSignature(choice *routeChoice) string {
	var builder strings.Builder
	builder.Grow(24 + len(choice.keys)*20)
	builder.WriteString(strconv.FormatInt(
		int64(choice.deliver), 10,
	))

	for _, key := range choice.keys {
		builder.WriteByte('/')
		builder.WriteString(strconv.FormatUint(key.chanID, 10))
	}

	return builder.String()
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= maxAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	var best *routeChoice
	var repeated *routeChoice

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		diversity := make(map[edgeKey]float64)

		for alternative := 0; alternative < 5; alternative++ {
			choice, err := r.findRoute(shard, diversity)
			if err != nil {
				break
			}

			needed := math.Ceil(
				float64(amt) / float64(shard),
			)
			choice.utility = -math.Log(choice.probability) +
				0.055*(needed-1) +
				float64(choice.fee)/2_500_000

			signature := routeSignature(choice)
			if r.tried[signature] {
				choice.utility += 4.0
				if repeated == nil ||
					choice.utility < repeated.utility {

					repeated = choice
				}
			} else if best == nil ||
				choice.utility < best.utility {

				best = choice
			}

			for _, key := range choice.keys {
				diversity[key] += 0.95
			}
		}
	}

	if best == nil {
		best = repeated
	}
	if best == nil {
		return nil, errors.New("no route found")
	}

	r.tried[routeSignature(best)] = true
	for i, key := range best.keys {
		r.reserved[key] += best.amounts[i]
	}
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	failedEstimate := amt / 4
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = failedEstimate
	} else {
		belief.estimate =
			(3*belief.estimate + failedEstimate) / 4
	}

	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}
	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnProbeSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	optimistic := edge.capacity * 9 / 10
	if belief.estimate < optimistic {
		if belief.estimate < amt {
			belief.estimate = amt
		}
		belief.estimate =
			(belief.estimate + optimistic) / 2
	}

	if belief.upperFail > 0 &&
		belief.upperFail <= belief.lowerOK {

		belief.upperFail = 0
	}

	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}

	return value - amount
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	preEstimate := belief.estimate
	if preEstimate < amt {
		preEstimate = amt
	}

	optimistic := edge.capacity * 9 / 10
	if preEstimate < optimistic {
		preEstimate = (preEstimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(preEstimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}

	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}

	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}

	return b
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	keys, amounts := routeEdgeData(rt)
	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}

		r.lastFailedAmt = 0
		return nil
	}

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIndex = i + 1
				break
			}
		}
	}

	r.lastFailedAmt =
		rt.Hops[len(rt.Hops)-1].AmtToForward

	if failIndex < 0 || failIndex >= len(keys) {
		return nil
	}

	// Every edge before the failure carried the HTLC successfully. Since
	// the failed attempt unwinds, this is evidence without a net liquidity
	// shift.
	for i := 0; i < failIndex; i++ {
		r.learnProbeSuccess(keys[i], amounts[i])
		if r.edgeFailures[keys[i]] > 0 {
			r.edgeFailures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]
	r.edgeFailures[key] += 2

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.broken[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved map[edgeKey]lnwire.MilliSatoshi

	// paymentUpper records failures observed by this router. Unlike shared
	// beliefs, these bounds are fresh enough to exclude an amount outright.
	// A new payment receives a new router and can cheaply refresh stale shared
	// evidence if background traffic has moved liquidity.
	paymentUpper map[edgeKey]lnwire.MilliSatoshi
	edgeFailures map[edgeKey]uint32
	broken       map[edgeKey]bool

	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[edgeKey]liquidityBelief),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		paymentUpper:  make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:  make(map[edgeKey]uint32),
		broken:        make(map[edgeKey]bool),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-18*x)
	highMode := 0.495 / (1 + math.Exp(22*(x-0.88)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}
		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := float64(edge.capacity) * 0.08
	if scale < 1 {
		scale = 1
	}
	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))

	confidence := math.Min(0.82, 0.20*float64(belief.samples))
	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

func (r *candidateRouter) freshlyImpossible(edge *candidateEdge,
	amt lnwire.MilliSatoshi) bool {

	upper := r.paymentUpper[edge.key]
	return upper > 0 && amt+r.reserved[edge.key] >= upper
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]
	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	utility     float64
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{r.spec.Target: 0}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, ok := score[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.broken[edge.key] || !edge.usable(item.amt) {
				continue
			}
			if r.freshlyImpossible(edge, item.amt) {
				continue
			}

			total := item.amt + r.reserved[edge.key]
			if total > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				total > r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(edge, item.amt)
			edgeFee := edge.fee(item.amt)
			sending := item.amt + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = item.amt
			}

			// Reliability is the primary cost. Capacity enters through the
			// bimodal probability, while fees and hop count break close
			// reliability ties. Only the actually failing edge accumulates
			// the explicit failure penalty.
			step := -math.Log(probability) +
				float64(edgeFee)/3_000_000 +
				0.012 +
				0.24*float64(r.edgeFailures[edge.key])
			candidate := item.score + step

			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(r.edges[key], amounts[i])
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addCandidate(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	if minimum < 1_000 {
		minimum = 1_000
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 20)

	// Include both balanced allocations and deliberately unequal shards.
	// The latter allow a large corridor to carry most of the payment while
	// preserving enough part slots for smaller parallel corridors.
	addCandidate(&values, seen, amt, minimum, amt)
	addCandidate(&values, seen, amt*7/8, minimum, amt)
	addCandidate(&values, seen, amt*4/5, minimum, amt)
	addCandidate(&values, seen, amt*3/4, minimum, amt)
	addCandidate(&values, seen, amt*2/3, minimum, amt)
	addCandidate(&values, seen, amt*3/5, minimum, amt)
	addCandidate(&values, seen, amt/2, minimum, amt)
	addCandidate(&values, seen, amt*2/5, minimum, amt)
	addCandidate(&values, seen, amt/3, minimum, amt)
	addCandidate(&values, seen, minimum*2, minimum, amt)
	addCandidate(&values, seen, minimum*3/2, minimum, amt)
	addCandidate(&values, seen, minimum*5/4, minimum, amt)
	addCandidate(&values, seen, minimum, minimum, amt)

	if r.lastFailedAmt > 0 {
		addCandidate(
			&values, seen, r.lastFailedAmt*4/5,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*2/3,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt/2,
			minimum, amt,
		)
	}

	// Fresh failure bounds are especially useful breakpoints. Shared bounds
	// are also considered, but they do not exclude routes because background
	// traffic may have invalidated them between payments.
	var bounds []lnwire.MilliSatoshi
	for key, upper := range r.paymentUpper {
		if r.broken[key] || upper <= 1 {
			continue
		}
		for _, factor := range []lnwire.MilliSatoshi{9, 4, 2} {
			denominator := lnwire.MilliSatoshi(10)
			if factor == 4 {
				denominator = 5
			}
			if factor == 2 {
				denominator = 3
			}
			bound := upper * factor / denominator
			if bound >= minimum && bound <= amt {
				bounds = append(bounds, bound)
			}
		}
	}

	for key, belief := range r.beliefs {
		if r.broken[key] || belief.upperFail <= 1 {
			continue
		}
		bound := belief.upperFail * 4 / 5
		if bound >= minimum && bound <= amt {
			bounds = append(bounds, bound)
		}
	}

	sort.Slice(bounds, func(i, j int) bool {
		return bounds[i] > bounds[j]
	})
	if len(bounds) > 6 {
		bounds = bounds[:6]
	}
	for _, bound := range bounds {
		addCandidate(&values, seen, bound, minimum, amt)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})
	return values
}

func (r *candidateRouter) reserveChoice(choice *routeChoice) {
	for i, key := range choice.keys {
		r.reserved[key] += choice.amounts[i]
	}
}

func (r *candidateRouter) releaseChoice(choice *routeChoice) {
	for i, key := range choice.keys {
		reserved := r.reserved[key]
		if reserved <= choice.amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - choice.amounts[i]
		}
	}
}

// continuationScore performs a bounded one-step route-set lookahead. It tests
// whether the remainder has a plausible route after the candidate's liquidity
// is reserved. This favors unequal allocations across genuinely independent
// corridors instead of discovering every split through failed attempts.
func (r *candidateRouter) continuationScore(choice *routeChoice,
	remaining lnwire.MilliSatoshi, partsLeft uint32) float64 {

	if remaining <= choice.deliver {
		return 0
	}
	if partsLeft <= 1 {
		return 20
	}

	after := remaining - choice.deliver
	slots := partsLeft - 1
	nextMinimum := (after + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)
	if nextMinimum < 1_000 {
		nextMinimum = 1_000
	}

	r.reserveChoice(choice)
	defer r.releaseChoice(choice)

	nextChoice, err := r.findRoute(nextMinimum)
	if err != nil {
		return 8
	}

	// Reward a continuation that uses few of the same directed channels.
	overlap := 0
	used := make(map[edgeKey]bool, len(choice.keys))
	for _, key := range choice.keys {
		used[key] = true
	}
	for _, key := range nextChoice.keys {
		if used[key] {
			overlap++
		}
	}

	return 0.30*-math.Log(nextChoice.probability) +
		0.16*float64(overlap) +
		float64(nextChoice.fee)/6_000_000
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= 48 {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	var best *routeChoice

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		// Estimate the cost of covering the entire remainder with similarly
		// reliable shards. This prevents a small shard from looking cheap
		// merely because it exposes less liquidity.
		shardsNeeded := float64(amt) / float64(shard)
		risk := -math.Log(choice.probability) * shardsNeeded
		fees := float64(choice.fee) * shardsNeeded / 3_000_000
		partCost := 0.06 * shardsNeeded
		lookahead := r.continuationScore(
			choice, amt, partsLeft,
		)

		choice.utility = risk + fees + partCost + lookahead
		if best == nil || choice.utility < best.utility {
			best = choice
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	r.reserveChoice(best)
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	fresh := r.paymentUpper[key]
	if fresh == 0 || amt < fresh {
		r.paymentUpper[key] = amt
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = amt / 4
	} else {
		belief.estimate = (3*belief.estimate + amt/4) / 4
	}
	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}
	belief.samples++
	r.storeBelief(key, belief)
}

// learnProbeSuccess records that an edge accepted an HTLC before a downstream
// failure. Since the attempt did not settle, no liquidity is shifted.
func (r *candidateRouter) learnProbeSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.estimate < amt {
		belief.estimate = amt
	}

	// Under the bimodal model, accepting a meaningful probe is evidence for
	// the liquid mode, but the proven lower bound remains authoritative.
	optimistic := edge.capacity * 4 / 5
	if belief.estimate < optimistic {
		belief.estimate = (belief.estimate + optimistic) / 2
	}
	if belief.upperFail > 0 && belief.upperFail <= belief.lowerOK {
		belief.upperFail = 0
	}
	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}
	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}
	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	preEstimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10
	if preEstimate < optimistic {
		preEstimate = (preEstimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(preEstimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}
	if belief.lowerOK >= belief.upperFail && belief.upperFail > 0 {
		belief.upperFail = 0
	}
	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}
	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	keys, amounts := routeEdgeData(rt)
	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}

		r.lastFailedAmt = 0
		return nil
	}

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIndex = i + 1
				break
			}
		}
	}

	r.lastFailedAmt = rt.Hops[len(rt.Hops)-1].AmtToForward

	if failIndex < 0 || failIndex >= len(keys) {
		// Unknown attribution should mildly discourage the whole path, but
		// must not create false hard liquidity bounds.
		for _, key := range keys {
			r.edgeFailures[key]++
		}
		return nil
	}

	// Every edge before the failing edge accepted the HTLC. Preserve that
	// positive evidence without applying settlement liquidity movement.
	for i := 0; i < failIndex; i++ {
		r.learnProbeSuccess(keys[i], amounts[i])
		if r.edgeFailures[keys[i]] > 0 {
			r.edgeFailures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]
	r.edgeFailures[key] += 2

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		// The route was built from the advertised directional policy. Avoid
		// repeating a policy-invalid edge for the remainder of this payment.
		r.broken[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta   = 40
	maxRouteAttempts = 96
)

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved       map[edgeKey]lnwire.MilliSatoshi
	edgeFailures   map[edgeKey]uint32
	lastFailureAmt map[edgeKey]lnwire.MilliSatoshi
	broken         map[edgeKey]bool
	routeTries     map[uint64]uint32

	lastFailedDeliver lnwire.MilliSatoshi
	attempts          uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:          source,
		spec:            spec,
		incomingEdges:   make(map[route.Vertex][]*candidateEdge),
		edges:           make(map[edgeKey]*candidateEdge),
		localBalances:   make(map[uint64]lnwire.MilliSatoshi),
		beliefs:         make(map[edgeKey]liquidityBelief),
		reserved:        make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:    make(map[edgeKey]uint32),
		lastFailureAmt:  make(map[edgeKey]lnwire.MilliSatoshi),
		broken:          make(map[edgeKey]bool),
		routeTries:      make(map[uint64]uint32),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity / 2
		}

		normalizeBelief(&belief, edge.capacity)
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func normalizeBelief(belief *liquidityBelief,
	capacity lnwire.MilliSatoshi) {

	if belief.lowerOK > capacity {
		belief.lowerOK = capacity
	}
	if belief.estimate > capacity {
		belief.estimate = capacity
	}
	if belief.upperFail > capacity {
		belief.upperFail = 0
	}
	if belief.upperFail > 0 &&
		belief.lowerOK >= belief.upperFail {

		belief.lowerOK = belief.upperFail - 1
	}
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-18*x)
	highMode := 0.495 / (1 + math.Exp(22*(x-0.88)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}

		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	estimate := belief.estimate
	if estimate == 0 {
		estimate = edge.capacity / 2
	}

	scale := float64(edge.capacity) * 0.08
	if belief.upperFail > belief.lowerOK {
		interval := float64(belief.upperFail - belief.lowerOK)
		if interval/3 < scale {
			scale = interval / 3
		}
	}
	if scale < 1 {
		scale = 1
	}

	point := 1 / (1 + math.Exp(
		(float64(total)-float64(estimate))/scale,
	))

	confidence := math.Min(0.82, 0.20*float64(belief.samples))
	probability := (1-confidence)*prior + confidence*point

	return clampProbability(probability)
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]

	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	utility     float64
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
	fingerprint uint64
}

func (r *candidateRouter) failurePenalty(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	failures := r.edgeFailures[edge.key]
	if failures == 0 {
		return 0
	}

	failedAmt := r.lastFailureAmt[edge.key]
	if failedAmt == 0 {
		return 0.20 * float64(failures)
	}

	ratio := float64(amt) / float64(failedAmt)
	switch {
	case ratio >= 0.90:
		return 0.55 * float64(failures)
	case ratio >= 0.55:
		return 0.22 * float64(failures)
	case ratio >= 0.30:
		return 0.08 * float64(failures)
	default:
		return 0.02 * float64(failures)
	}
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, ok := score[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.broken[edge.key] || !edge.usable(item.amt) {
				continue
			}

			total := item.amt + r.reserved[edge.key]
			if total > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				total > r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(edge, item.amt)
			edgeFee := edge.fee(item.amt)
			sending := item.amt + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = item.amt
			}

			step := -math.Log(probability) +
				float64(edgeFee)/2_500_000 +
				0.012 +
				r.failurePenalty(edge, item.amt)
			candidate := item.score + step

			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		probability *= r.edgeProbability(
			r.edges[key], amounts[i],
		)
	}

	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		keys:        keys,
		amounts:     amounts,
		fingerprint: routeFingerprint(keys, deliver),
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New(
				"route contains a cycle",
			)
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func addCandidate(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func appendEdgeBreakpoints(values *[]lnwire.MilliSatoshi,
	edge *candidateEdge, belief liquidityBelief) {

	capacity := edge.capacity
	if edge.maxHTLC > 0 && edge.maxHTLC < capacity {
		capacity = edge.maxHTLC
	}

	*values = append(
		*values,
		capacity*9/10,
		capacity*3/4,
	)

	if belief.lowerOK > 0 {
		*values = append(
			*values,
			belief.lowerOK,
			belief.lowerOK*9/10,
		)
	}
	if belief.estimate > 0 {
		*values = append(
			*values,
			belief.estimate*9/10,
			belief.estimate*3/4,
		)
	}
	if belief.upperFail > 1 {
		*values = append(
			*values,
			(belief.upperFail-1)*2/3,
			(belief.upperFail-1)/2,
			(belief.upperFail-1)/3,
		)
	}
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	if minimum < 1_000 {
		minimum = 1_000
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 32)

	addCandidate(&values, seen, amt, minimum, amt)
	addCandidate(&values, seen, amt*4/5, minimum, amt)
	addCandidate(&values, seen, amt*2/3, minimum, amt)
	addCandidate(&values, seen, amt/2, minimum, amt)
	addCandidate(&values, seen, amt/3, minimum, amt)
	addCandidate(&values, seen, minimum*3, minimum, amt)
	addCandidate(&values, seen, minimum*2, minimum, amt)
	addCandidate(&values, seen, minimum*3/2, minimum, amt)
	addCandidate(&values, seen, minimum, minimum, amt)

	if r.lastFailedDeliver > 0 {
		addCandidate(
			&values, seen, r.lastFailedDeliver*3/5,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedDeliver*2/5,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedDeliver/4,
			minimum, amt,
		)
	}

	var breakpoints []lnwire.MilliSatoshi
	for _, edge := range r.incomingEdges[r.spec.Target] {
		if !r.broken[edge.key] {
			appendEdgeBreakpoints(
				&breakpoints, edge, r.beliefs[edge.key],
			)
		}
	}
	for _, edge := range r.edges {
		if edge.key.from != r.source || r.broken[edge.key] {
			continue
		}

		available := r.localBalances[edge.key.chanID] -
			r.reserved[edge.key]
		if available > 0 {
			breakpoints = append(
				breakpoints,
				available*9/10,
				available*3/4,
			)
		}
	}

	sort.Slice(breakpoints, func(i, j int) bool {
		return breakpoints[i] > breakpoints[j]
	})

	added := 0
	for _, breakpoint := range breakpoints {
		before := len(values)
		addCandidate(
			&values, seen, breakpoint, minimum, amt,
		)
		if len(values) > before {
			added++
		}
		if added >= 16 {
			break
		}
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})

	return values
}

func routeFingerprint(keys []edgeKey,
	deliver lnwire.MilliSatoshi) uint64 {

	const (
		offset = uint64(1469598103934665603)
		prime  = uint64(1099511628211)
	)

	hash := offset
	mix := func(value uint64) {
		for i := 0; i < 8; i++ {
			hash ^= value & 0xff
			hash *= prime
			value >>= 8
		}
	}

	mix(uint64(deliver))
	for _, key := range keys {
		mix(key.chanID)
	}

	return hash
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= maxRouteAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	var best *routeChoice

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		choice, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		requiredParts := uint32(
			(amt + shard - 1) / shard,
		)
		if requiredParts > partsLeft {
			continue
		}

		// Approximate the risk of completing the remaining payment with
		// similarly sized parts. This avoids repeatedly choosing the
		// smallest legal shard merely because one tiny attempt is safe.
		partCount := float64(requiredParts)
		risk := -math.Log(choice.probability)
		feeCost := partCount *
			float64(choice.fee) / 2_500_000
		retryCost := 0.65 * float64(
			r.routeTries[choice.fingerprint],
		)

		choice.utility = partCount*(risk+0.045) +
			feeCost + retryCost

		// Prefer an exact final shard when choices have similar expected
		// completion cost.
		if shard == amt {
			choice.utility -= 0.03
		}

		if best == nil || choice.utility < best.utility {
			best = choice
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	for i, key := range best.keys {
		r.reserved[key] += best.amounts[i]
	}
	r.routeTries[best.fingerprint]++
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(key edgeKey,
	belief liquidityBelief) {

	edge := r.edges[key]
	if edge != nil {
		normalizeBelief(&belief, edge.capacity)
	}

	r.beliefs[key] = belief
	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	// Under a bimodal prior, a miss is evidence that this direction is
	// likely in its depleted mode. Retain lower-amount retries, but move
	// the point estimate substantially below the failed amount.
	depletedEstimate := amt / 5
	if belief.estimate == 0 ||
		depletedEstimate < belief.estimate {

		belief.estimate = depletedEstimate
	} else {
		belief.estimate =
			(3*belief.estimate + depletedEstimate) / 4
	}

	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = belief.upperFail - 1
	}
	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnPass(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	optimistic := edge.capacity * 9 / 10
	if belief.estimate < amt {
		belief.estimate = amt
	}
	if belief.estimate < optimistic {
		belief.estimate =
			(belief.estimate + optimistic) / 2
	}

	if belief.upperFail > 0 && belief.upperFail <= amt {
		belief.upperFail = 0
	}
	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}

	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}

	return b
}

func (r *candidateRouter) learnSettlement(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	preEstimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10
	if preEstimate < optimistic {
		preEstimate = (preEstimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(preEstimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}
	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}

	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}
	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}

	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func (r *candidateRouter) releaseReservation(keys []edgeKey,
	amounts []lnwire.MilliSatoshi) {

	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}
}

func failureEdgeIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("attempt route is empty")
	}

	keys, amounts := routeEdgeData(rt)
	r.releaseReservation(keys, amounts)

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSettlement(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}

		r.lastFailedDeliver = 0
		return nil
	}

	deliver := rt.Hops[len(rt.Hops)-1].AmtToForward
	r.lastFailedDeliver = deliver

	failIndex := failureEdgeIndex(
		rt, result.FailureSource,
	)
	if failIndex < 0 || failIndex >= len(keys) {
		return nil
	}

	// Every edge before the failure source successfully forwarded the
	// attempt. Since the failed HTLC unwinds, this proves a lower bound
	// without moving channel liquidity.
	for i := 0; i < failIndex; i++ {
		r.learnPass(keys[i], amounts[i])
		if r.edgeFailures[keys[i]] > 0 {
			r.edgeFailures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)
		r.edgeFailures[key]++
		r.lastFailureAmt[key] = failedAmt

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.broken[key] = true
		r.edgeFailures[key] += 3
		r.lastFailureAmt[key] = failedAmt
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type liquidityBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	samples   uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[edgeKey]liquidityBelief
}{
	values: make(map[edgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[edgeKey]liquidityBelief

	reserved      map[edgeKey]lnwire.MilliSatoshi
	edgeFailures  map[edgeKey]uint32
	broken        map[edgeKey]bool
	routeFailures map[uint64]uint32

	lastFailedAmt lnwire.MilliSatoshi
	attempts      uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[edgeKey]*candidateEdge),
		localBalances:  make(map[uint64]lnwire.MilliSatoshi),
		beliefs:        make(map[edgeKey]liquidityBelief),
		reserved:       make(map[edgeKey]lnwire.MilliSatoshi),
		edgeFailures:   make(map[edgeKey]uint32),
		broken:         make(map[edgeKey]bool),
		routeFailures:  make(map[uint64]uint32),
	}

	for chanID, balance := range localBalances {
		r.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edges[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, edge := range r.edges {
		belief, ok := sharedBeliefs.values[key]
		if !ok {
			belief.estimate = edge.capacity / 2
		}
		r.beliefs[key] = belief
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.50 * math.Exp(-18*x)
	highMode := 0.495 / (1 + math.Exp(22*(x-0.88)))

	return clampProbability(lowMode + highMode)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0.005
	}

	if edge.key.from == r.source {
		if total <= r.localBalances[edge.key.chanID] {
			return 0.999
		}
		return 0.001
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, edge.capacity)
	if belief.samples == 0 {
		return prior
	}

	scale := float64(edge.capacity) * 0.08
	if scale < 1 {
		scale = 1
	}
	point := 1 / (1 + math.Exp(
		(float64(total)-float64(belief.estimate))/scale,
	))

	confidence := math.Min(0.82, 0.24*float64(belief.samples))
	return clampProbability(
		(1-confidence)*prior + confidence*point,
	)
}

type dijkstraItem struct {
	node  route.Vertex
	score float64
	amt   lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := old[len(old)-1]
	*q = old[:len(old)-1]
	return last
}

type routeChoice struct {
	route       *route.Route
	deliver     lnwire.MilliSatoshi
	probability float64
	fee         lnwire.MilliSatoshi
	utility     float64
	fingerprint uint64
	keys        []edgeKey
	amounts     []lnwire.MilliSatoshi
}

func (r *candidateRouter) findRoute(deliver lnwire.MilliSatoshi,
	banned map[edgeKey]bool) (*routeChoice, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is payment target")
	}

	score := map[route.Vertex]float64{r.spec.Target: 0}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node: r.spec.Target,
		amt:  deliver,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		best, ok := score[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if banned[edge.key] || r.broken[edge.key] {
				continue
			}

			edgeFee := edge.fee(item.amt)
			sending := item.amt + edgeFee
			if edge.key.from == r.source {
				edgeFee = 0
				sending = item.amt
			}

			if !edge.usable(sending) {
				continue
			}

			total := sending + r.reserved[edge.key]
			if total > edge.capacity {
				continue
			}
			if edge.key.from == r.source &&
				total > r.localBalances[edge.key.chanID] {

				continue
			}

			probability := r.edgeProbability(edge, sending)
			step := -math.Log(probability) +
				float64(edgeFee)/2_500_000 +
				0.012 +
				0.38*float64(r.edgeFailures[edge.key])
			candidate := item.score + step

			old, exists := score[edge.key.from]
			if exists && candidate >= old {
				continue
			}

			score[edge.key.from] = candidate
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:  edge.key.from,
				score: candidate,
				amt:   sending,
			})
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	rt, keys, amounts, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, err
	}

	probability := 1.0
	for i, key := range keys {
		edge := r.edges[key]
		if edge == nil || !edge.usable(amounts[i]) {
			return nil, errors.New("route violates edge constraints")
		}
		probability *= r.edgeProbability(edge, amounts[i])
	}

	fingerprint := routeFingerprint(keys, deliver)
	return &routeChoice{
		route:       rt,
		deliver:     deliver,
		probability: probability,
		fee:         rt.TotalAmount - deliver,
		fingerprint: fingerprint,
		keys:        keys,
		amounts:     amounts,
	}, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, []edgeKey,
	[]lnwire.MilliSatoshi, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, nil, nil, fmt.Errorf(
				"broken path at %v", node,
			)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edges) {
			return nil, nil, nil, errors.New("route contains a cycle")
		}
	}

	if len(path) == 0 {
		return nil, nil, nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	amounts[len(path)-1] = deliver
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	keys := make([]edgeKey, len(path))
	for i, edge := range path {
		if !edge.usable(amounts[i]) {
			return nil, nil, nil, errors.New(
				"constructed amount violates policy",
			)
		}

		forward := deliver
		expiry := uint32(finalCltvDelta)
		if i+1 < len(path) {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
		keys[i] = edge.key
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, keys, amounts, nil
}

func routeFingerprint(keys []edgeKey,
	amt lnwire.MilliSatoshi) uint64 {

	hash := uint64(1469598103934665603)
	mix := func(value uint64) {
		hash ^= value
		hash *= 1099511628211
	}

	mix(uint64(amt))
	for _, key := range keys {
		mix(key.chanID)
		for _, value := range key.from {
			mix(uint64(value))
		}
		for _, value := range key.to {
			mix(uint64(value))
		}
	}

	return hash
}

func addCandidate(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) candidateAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := lnwire.MilliSatoshi(1_000)
	if amt < minimum {
		minimum = amt
	}

	average := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)

	seen := make(map[lnwire.MilliSatoshi]bool)
	values := make([]lnwire.MilliSatoshi, 0, 20)

	addCandidate(&values, seen, amt, minimum, amt)
	addCandidate(&values, seen, amt*7/8, minimum, amt)
	addCandidate(&values, seen, amt*3/4, minimum, amt)
	addCandidate(&values, seen, amt*2/3, minimum, amt)
	addCandidate(&values, seen, amt/2, minimum, amt)
	addCandidate(&values, seen, average*3/2, minimum, amt)
	addCandidate(&values, seen, average*5/4, minimum, amt)
	addCandidate(&values, seen, average, minimum, amt)
	addCandidate(&values, seen, average*3/4, minimum, amt)
	addCandidate(&values, seen, average/2, minimum, amt)
	addCandidate(&values, seen, amt/4, minimum, amt)
	addCandidate(&values, seen, amt/8, minimum, amt)

	if r.lastFailedAmt > 0 {
		addCandidate(
			&values, seen, r.lastFailedAmt*3/4,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt*2/3,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt/2,
			minimum, amt,
		)
		addCandidate(
			&values, seen, r.lastFailedAmt/3,
			minimum, amt,
		)
	}

	var breakpoints []lnwire.MilliSatoshi
	for key, belief := range r.beliefs {
		if r.broken[key] {
			continue
		}

		if belief.lowerOK > 0 {
			breakpoints = append(
				breakpoints, belief.lowerOK*9/10,
			)
		}
		if belief.upperFail > 1 {
			breakpoints = append(
				breakpoints,
				belief.upperFail*2/3,
				belief.upperFail/2,
			)
		}
		if belief.samples > 0 && belief.estimate > 0 {
			breakpoints = append(
				breakpoints, belief.estimate*3/4,
			)
		}
	}

	sort.Slice(breakpoints, func(i, j int) bool {
		di := absMSat(breakpoints[i] - average)
		dj := absMSat(breakpoints[j] - average)
		return di < dj
	})
	if len(breakpoints) > 6 {
		breakpoints = breakpoints[:6]
	}

	for _, value := range breakpoints {
		addCandidate(
			&values, seen, value, minimum, amt,
		)
	}

	sort.Slice(values, func(i, j int) bool {
		return values[i] > values[j]
	})
	return values
}

func absMSat(value lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if value < 0 {
		return -value
	}
	return value
}

func samePath(a, b []edgeKey) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func (r *candidateRouter) routeAlternatives(
	deliver lnwire.MilliSatoshi) []*routeChoice {

	base, err := r.findRoute(deliver, nil)
	if err != nil {
		return nil
	}

	choices := []*routeChoice{base}
	limit := len(base.keys)
	if limit > 7 {
		limit = 7
	}

	for i := 0; i < limit; i++ {
		banned := map[edgeKey]bool{
			base.keys[i]: true,
		}
		choice, err := r.findRoute(deliver, banned)
		if err != nil {
			continue
		}

		duplicate := false
		for _, existing := range choices {
			if samePath(existing.keys, choice.keys) {
				duplicate = true
				break
			}
		}
		if duplicate {
			continue
		}

		choices = append(choices, choice)
		if len(choices) >= 4 {
			break
		}
	}

	return choices
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum number of parts reached")
	}
	if r.attempts >= 48 {
		return nil, errors.New("routing attempt budget exhausted")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	average := float64(amt) / float64(partsLeft)
	var best *routeChoice

	for _, shard := range r.candidateAmounts(amt, partsLeft) {
		for _, choice := range r.routeAlternatives(shard) {
			probabilityCost := -math.Log(choice.probability)
			feeCost := float64(choice.fee) / 2_500_000
			routeRetryCost := 1.35 *
				float64(r.routeFailures[choice.fingerprint])

			shardSize := float64(shard)
			partsPressure := 0.0
			if shardSize < average {
				deficit := (average - shardSize) / average
				partsPressure = 0.55 * deficit * deficit
			} else {
				partsPressure = 0.10 *
					math.Log1p(shardSize/average-1)
			}

			progressReward := 0.16 *
				math.Log1p(shardSize/average)
			choice.utility = probabilityCost + feeCost +
				routeRetryCost + partsPressure -
				progressReward

			if best == nil || choice.utility < best.utility {
				best = choice
			}
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	for i, key := range best.keys {
		r.reserved[key] += best.amounts[i]
	}
	r.attempts++

	return best.route, nil
}

func routeEdgeData(rt *route.Route) ([]edgeKey,
	[]lnwire.MilliSatoshi) {

	keys := make([]edgeKey, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		keys[i] = edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
		from = hop.PubKeyBytes
	}

	return keys, amounts
}

func (r *candidateRouter) storeBelief(
	key edgeKey, belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) learnPass(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.estimate < amt {
		belief.estimate = amt
	}
	if belief.upperFail > 0 && belief.upperFail <= amt {
		belief.upperFail = 0
	}
	belief.samples++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key edgeKey,
	amt lnwire.MilliSatoshi) {

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}

	failureEstimate := amt / 4
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = failureEstimate
	} else {
		belief.estimate = (
			3*belief.estimate + failureEstimate,
		) / 4
	}

	if belief.lowerOK >= belief.upperFail {
		belief.lowerOK = 0
	}
	belief.samples++
	r.storeBelief(key, belief)
}

func subtractFloor(value, amount,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value <= floor+amount {
		return floor
	}
	return value - amount
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}
	return b
}

func (r *candidateRouter) learnSuccess(key edgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	preEstimate := maxMSat(belief.estimate, amt)
	optimistic := edge.capacity * 9 / 10
	if preEstimate < optimistic {
		preEstimate = (preEstimate + optimistic) / 2
	}

	belief.estimate = subtractFloor(preEstimate, amt, 0)
	belief.lowerOK = subtractFloor(
		maxMSat(belief.lowerOK, amt), amt, 0,
	)
	if belief.upperFail > 0 {
		belief.upperFail = subtractFloor(
			belief.upperFail, amt, 1,
		)
	}
	belief.samples++
	r.storeBelief(key, belief)

	reverse := edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
	reverseEdge := r.edges[reverse]
	if reverseEdge == nil {
		return
	}

	reverseBelief := r.beliefs[reverse]
	reverseBelief.estimate += amt
	if reverseBelief.estimate > reverseEdge.capacity {
		reverseBelief.estimate = reverseEdge.capacity
	}
	if reverseBelief.lowerOK > 0 {
		reverseBelief.lowerOK += amt
		if reverseBelief.lowerOK > reverseEdge.capacity {
			reverseBelief.lowerOK = reverseEdge.capacity
		}
	}
	if reverseBelief.upperFail > 0 {
		reverseBelief.upperFail += amt
		if reverseBelief.upperFail > reverseEdge.capacity {
			reverseBelief.upperFail = 0
		}
	}
	reverseBelief.samples++
	r.storeBelief(reverse, reverseBelief)
}

func (r *candidateRouter) releaseReservation(keys []edgeKey,
	amounts []lnwire.MilliSatoshi) {

	for i, key := range keys {
		reserved := r.reserved[key]
		if reserved <= amounts[i] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] = reserved - amounts[i]
		}
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	keys, amounts := routeEdgeData(rt)
	r.releaseReservation(keys, amounts)

	deliver := rt.Hops[len(rt.Hops)-1].AmtToForward
	fingerprint := routeFingerprint(keys, deliver)

	if result.Failure == nil {
		for i, key := range keys {
			r.learnSuccess(key, amounts[i])

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if amounts[i] >= balance {
					r.localBalances[key.chanID] = 0
				} else {
					r.localBalances[key.chanID] =
						balance - amounts[i]
				}
			}

			if r.edgeFailures[key] > 0 {
				r.edgeFailures[key]--
			}
		}

		delete(r.routeFailures, fingerprint)
		r.lastFailedAmt = 0
		return nil
	}

	r.routeFailures[fingerprint]++
	r.lastFailedAmt = deliver

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIndex = i + 1
				break
			}
		}
	}

	if failIndex < 0 || failIndex >= len(keys) {
		for _, key := range keys {
			r.edgeFailures[key]++
		}
		return nil
	}

	for i := 0; i < failIndex; i++ {
		r.learnPass(keys[i], amounts[i])
		if r.edgeFailures[keys[i]] > 0 {
			r.edgeFailures[keys[i]]--
		}
	}

	key := keys[failIndex]
	failedAmt := amounts[failIndex]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, failedAmt)
		r.edgeFailures[key] += 3

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.broken[key] = true
		r.edgeFailures[key] += 8

	default:
		r.edgeFailures[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = uint32(40)

	riskCostMsat   = 300000.0
	minProbability = 0.003
	maxProbability = 0.995

	lowerRetryFactor = 0.62
	minShardMsat     = lnwire.MilliSatoshi(10_000)
	maxShardQuotes   = 24
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	return true
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
}

var sharedBeliefs = struct {
	sync.Mutex
	values map[candidateEdgeKey]liquidityBelief
}{
	values: make(map[candidateEdgeKey]liquidityBelief),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	beliefs       map[candidateEdgeKey]liquidityBelief
	blocked       map[candidateEdgeKey]bool
	reserved      map[candidateEdgeKey]lnwire.MilliSatoshi
	routePenalty  map[candidateEdgeKey]float64

	preferredShard      lnwire.MilliSatoshi
	lastRemaining       lnwire.MilliSatoshi
	consecutiveFailures uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeByKey:     make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		beliefs:       make(map[candidateEdgeKey]liquidityBelief),
		blocked:       make(map[candidateEdgeKey]bool),
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		routePenalty:  make(map[candidateEdgeKey]float64),
		lastRemaining: spec.Amount,
	}

	parts := spec.MaxParts
	if parts == 0 {
		parts = 1
	}
	r.preferredShard = ceilDiv(
		spec.Amount, lnwire.MilliSatoshi(parts),
	)

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edgeByKey[key]; ok {
					return nil
				}

				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.edgeByKey[key] = edge
				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	sharedBeliefs.Lock()
	for key, belief := range sharedBeliefs.values {
		if _, ok := r.edgeByKey[key]; ok {
			r.beliefs[key] = belief
		}
	}
	sharedBeliefs.Unlock()

	return r, nil
}

func ceilDiv(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if b <= 0 {
		return a
	}
	return (a + b - 1) / b
}

func clampProbability(p float64) float64 {
	switch {
	case p < minProbability:
		return minProbability
	case p > maxProbability:
		return maxProbability
	default:
		return p
	}
}

func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.51 * math.Exp(-x/0.024)
	highMode := 0.475 / (1 + math.Exp(15*(x-0.79)))

	return clampProbability(0.005 + lowMode + highMode)
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	reserved := r.reserved[edge.key]
	if reserved >= edge.capacity || amt > edge.capacity-reserved {
		return minProbability
	}

	effective := amt + reserved
	if edge.key.from == r.source {
		available := r.localBalances[edge.key.chanID]
		if reserved >= available || amt > available-reserved {
			return minProbability
		}
		return maxProbability
	}

	belief := r.beliefs[edge.key]
	if belief.upperBad != 0 && effective >= belief.upperBad {
		return minProbability
	}
	if reserved == 0 && belief.lowerOK != 0 &&
		amt <= belief.lowerOK {

		return maxProbability
	}

	prior := bimodalPrior(effective, edge.capacity)
	if belief.estimate == 0 {
		return prior
	}

	width := math.Max(float64(edge.capacity)*0.065, 1)
	point := 1 / (1 + math.Exp(
		(float64(effective)-float64(belief.estimate))/width,
	))

	weight := 0.48
	if belief.lowerOK != 0 || belief.upperBad != 0 {
		weight = 0.62
	}

	return clampProbability(
		(1-weight)*prior + weight*point,
	)
}

type dijkstraItem struct {
	node     route.Vertex
	score    float64
	arriving lnwire.MilliSatoshi
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}

	dist := map[route.Vertex]float64{
		r.spec.Target: 0,
	}
	required := map[route.Vertex]lnwire.MilliSatoshi{
		r.spec.Target: amt,
	}
	next := make(map[route.Vertex]*candidateEdge)

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:     r.spec.Target,
		arriving: amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		bestScore, ok := dist[item.node]
		if !ok || item.score > bestScore {
			continue
		}
		if item.arriving != required[item.node] {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.blocked[edge.key] {
				continue
			}

			amtOver := item.arriving
			if !edge.usable(amtOver) {
				continue
			}

			reserved := r.reserved[edge.key]
			if reserved >= edge.capacity ||
				amtOver > edge.capacity-reserved {

				continue
			}

			probability := r.probability(edge, amtOver)
			belief := r.beliefs[edge.key]
			if probability <= minProbability &&
				belief.upperBad != 0 &&
				amtOver+reserved >= belief.upperBad {

				continue
			}

			sending := amtOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
				sending += fee
			} else {
				available := r.localBalances[edge.key.chanID]
				if reserved >= available ||
					sending > available-reserved {

					continue
				}
			}

			risk := -math.Log(probability) * riskCostMsat
			congestion := 0.0
			if reserved > 0 {
				congestion = 90000 *
					float64(reserved) /
					float64(edge.capacity)
			}

			score := item.score + float64(fee) + risk +
				congestion + r.routePenalty[edge.key] + 200

			oldScore, exists := dist[edge.key.from]
			if exists && score >= oldScore {
				continue
			}

			dist[edge.key.from] = score
			required[edge.key.from] = sending
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:     edge.key.from,
				score:    score,
				arriving: sending,
			})
		}
	}

	score, ok := dist[r.source]
	if !ok {
		return nil, 0, errors.New("no route found")
	}
	if _, ok := next[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, score, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
		if len(path) > len(r.edgeByKey) {
			return nil, errors.New("route contains a cycle")
		}
	}
	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := finalCltvDelta
		if i < last {
			forward = amtOver[i+1]
			expiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	key := candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
	_, ok := r.edgeByKey[key]

	return key, ok
}

func routeAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func deliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) reserve(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.reserved[key] += routeAmount(rt, i)
		}
	}
}

func (r *candidateRouter) release(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := r.routeEdge(rt, i)
		if !ok {
			continue
		}

		amt := routeAmount(rt, i)
		if amt >= r.reserved[key] {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
	}
}

func addShardCandidate(values map[lnwire.MilliSatoshi]struct{},
	value, remaining, minimum lnwire.MilliSatoshi) {

	if value < minimum {
		value = minimum
	}
	if value > remaining {
		value = remaining
	}
	if value > 0 {
		values[value] = struct{}{}
	}
}

func distanceFromIdeal(value,
	ideal lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if value > ideal {
		return value - ideal
	}
	return ideal - value
}

func (r *candidateRouter) shardCandidates(
	remaining lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	ideal := ceilDiv(
		remaining, lnwire.MilliSatoshi(partsLeft),
	)
	minimum := minShardMsat
	if remaining < minimum {
		minimum = remaining
	}

	values := make(map[lnwire.MilliSatoshi]struct{})
	ratios := []float64{
		0.42, 0.55, 0.68, 0.82, 1.0, 1.18, 1.42, 1.75, 2.2,
	}
	for _, ratio := range ratios {
		addShardCandidate(
			values,
			lnwire.MilliSatoshi(float64(ideal)*ratio),
			remaining, minimum,
		)
	}

	addShardCandidate(
		values, r.preferredShard, remaining, minimum,
	)

	for _, belief := range r.beliefs {
		if belief.lowerOK != 0 {
			addShardCandidate(
				values, belief.lowerOK*97/100,
				remaining, minimum,
			)
		}
		if belief.upperBad != 0 {
			addShardCandidate(
				values,
				lnwire.MilliSatoshi(
					float64(belief.upperBad)*
						lowerRetryFactor,
				),
				remaining, minimum,
			)
		}
		if belief.estimate != 0 {
			addShardCandidate(
				values, belief.estimate*82/100,
				remaining, minimum,
			)
		}
	}

	for key, edge := range r.edgeByKey {
		if key.from != r.source && key.to != r.spec.Target {
			continue
		}

		available := edge.capacity
		if key.from == r.source {
			available = r.localBalances[key.chanID]
		}
		if reserved := r.reserved[key]; reserved < available {
			available -= reserved
		} else {
			continue
		}

		addShardCandidate(
			values, available*72/100, remaining, minimum,
		)
		addShardCandidate(
			values, available*90/100, remaining, minimum,
		)
	}

	candidates := make([]lnwire.MilliSatoshi, 0, len(values))
	for value := range values {
		candidates = append(candidates, value)
	}

	sort.Slice(candidates, func(i, j int) bool {
		di := distanceFromIdeal(candidates[i], ideal)
		dj := distanceFromIdeal(candidates[j], ideal)
		if di == dj {
			return candidates[i] > candidates[j]
		}
		return di < dj
	})

	if len(candidates) > maxShardQuotes {
		candidates = candidates[:maxShardQuotes]
	}

	return candidates
}

func allocationPenalty(shard, ideal,
	remaining lnwire.MilliSatoshi) float64 {

	difference := float64(distanceFromIdeal(shard, ideal))
	weight := 0.0015
	if shard < ideal {
		weight = 0.0022
	}

	penalty := difference * weight
	progress := float64(shard) / math.Max(float64(remaining), 1)
	penalty -= progress * 45000

	return penalty
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum parts in flight")
	}

	if amt < r.lastRemaining {
		r.consecutiveFailures = 0
	}
	r.lastRemaining = amt

	partsLeft := r.spec.MaxParts - inFlightHtlcs
	if partsLeft == 0 {
		return nil, errors.New("maximum parts in flight")
	}

	ideal := ceilDiv(amt, lnwire.MilliSatoshi(partsLeft))
	candidates := r.shardCandidates(amt, partsLeft)

	var (
		bestRoute *route.Route
		bestScore = math.Inf(1)
		lastErr   error
	)

	for _, shard := range candidates {
		rt, routeScore, err := r.findRoute(shard)
		if err != nil {
			lastErr = err
			continue
		}

		score := routeScore + allocationPenalty(
			shard, ideal, amt,
		)
		if score < bestScore {
			bestScore = score
			bestRoute = rt
		}
	}

	if bestRoute == nil {
		if lastErr == nil {
			lastErr = errors.New("no route found")
		}
		return nil, lastErr
	}

	r.reserve(bestRoute)
	return bestRoute, nil
}

type codedFailure interface {
	Code() lnwire.FailCode
}

func (r *candidateRouter) saveBelief(key candidateEdgeKey,
	belief liquidityBelief) {

	r.beliefs[key] = belief

	sharedBeliefs.Lock()
	sharedBeliefs.values[key] = belief
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) recordSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperBad != 0 && amt >= belief.upperBad {
		belief.upperBad = 0
	}
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}

	estimate := amt + (edge.capacity-amt)*4/5
	if estimate > edge.capacity {
		estimate = edge.capacity
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) recordFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	edge := r.edgeByKey[key]
	if edge == nil || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}
	if belief.upperBad == 0 || amt < belief.upperBad {
		belief.upperBad = amt
	}

	estimate := amt * 30 / 100
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}
	if belief.lowerOK > belief.estimate {
		belief.estimate = belief.lowerOK
	}

	r.saveBelief(key, belief)
}

func (r *candidateRouter) failureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	r.release(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if !ok {
				continue
			}

			r.recordSuccess(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.20
		}

		delivered := deliveredAmount(rt)
		if delivered > 0 {
			r.preferredShard = delivered
		}
		r.consecutiveFailures = 0

		return nil
	}

	failIndex := r.failureIndex(rt, result.FailureSource)
	if failIndex < 0 || failIndex >= len(rt.Hops) {
		for i := range rt.Hops {
			key, ok := r.routeEdge(rt, i)
			if ok {
				r.routePenalty[key] += riskCostMsat / 3
			}
		}
		r.consecutiveFailures++
		return nil
	}

	for i := 0; i < failIndex; i++ {
		key, ok := r.routeEdge(rt, i)
		if ok {
			r.recordSuccess(key, routeAmount(rt, i))
			r.routePenalty[key] *= 0.65
		}
	}

	key, ok := r.routeEdge(rt, failIndex)
	if !ok {
		r.consecutiveFailures++
		return nil
	}

	code := lnwire.FailCode(0)
	if failure, ok := result.Failure.(codedFailure); ok {
		code = failure.Code()
	}

	switch code {
	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.blocked[key] = true

	default:
		failedAmount := routeAmount(rt, failIndex)
		r.recordFailure(key, failedAmount)
		r.routePenalty[key] += riskCostMsat * 0.72

		delivered := deliveredAmount(rt)
		retry := lnwire.MilliSatoshi(
			float64(delivered) * lowerRetryFactor,
		)
		if retry >= minShardMsat {
			r.preferredShard = retry
		}
	}

	r.consecutiveFailures++
	if r.consecutiveFailures >= 3 {
		for penaltyKey, penalty := range r.routePenalty {
			if penaltyKey != key {
				r.routePenalty[penaltyKey] = penalty * 0.85
			}
		}
	}

	return nil
}
